    'c926b5f4': '"Nosotros somos la Casa Attis."',
    '982bfd18': '"Con el apoyo de las Casas Strymon y Dodona, seguimos siendo la Casa más poderosa de Cademia..."*"...digan lo que digan los partidarios de la Casa Comana."',
    'a7533222': '"La Casa Comana es una casa de vileza y engaño."',
    '4d702458': '"La Casa Nicander es una valiosa aliada nuestra."',
    '3403b225': '"La Casa Dodona es una Casa honorable, aunque algo vulgar."',
    '40d1af51': '"La Casa Atussa ya no tiene importancia."',
    '9a1744d9': '"La Casa Strymon tiene bastante con mantener el control de Catamarca."',
