    '7dc32c93': '"Reconócelo: la Casa @Attis nunca tuvo lo necesario para gobernar la ciudad de Cademia."',
    '4a58cf0b': '"¡Hay que admirar a quien deja una Casa gobernante para hacerse herrero!"',
