    'dafc4087': '"Dicen que los magos ayudan a mantener el orden del mundo: no lo están haciendo muy bien, ¿verdad?"',
    '721d59e5': '"Algo terrible, pero las crisis sacan lo mejor, o lo peor, de la gente."',
