    '650f6e9d': '"Naxos está en Cademia."',
    '87383388': '"Myus está en Kosha."',
    '168e55ef': '"Darius está ahora en Catamarca."',
    '8b76817e': '"Nuestro señor Alaric está decayendo, eso está claro.  Qué lástima."',
    'c5ff4bc9': '"Ah, ¿te refieres al bufón del Rey de la Tierra?  Un pájaro muy raro, y nunca mejor dicho."',
