    '9d4c06c0': '"Paris está casado con mi prima Helen."',
    '15e95581': '"Niobe es la hija de mi prima Helen y de su marido Paris."',
    'adf0bf26': '"Mi primo Dares lleva la Casa de Comidas de Dares, uno de los mejores sitios para comer de Cademia."',
    '51ec2f6f': '"Diomede es la mujer de mi primo Dares."',
    '1a943acc': '"Da la casualidad de que la Casa Dodona lleva las mejores posadas y tabernas de Cythera."',
    '37188ae2': '"Servimos las cosechas del Viñedo de la Costa Norte y también las del Viñedo del Sur."*"Por desgracia, nuestro envío del Viñedo de la Costa Norte se está retrasando un poco."',
