    'ef70afef': '"Abydos fue un asentamiento que surgió de Pnyx hace unos 700 años, pero fue destruido."',
    'a6e03c6e': '"Todo mago aprende la lección del conjuro del gólem, aunque aprenderla por las malas es mucho peor."*"¿Conoces la historia?"',
    'ef747599': '"Entonces lo entiendes..."',
    '25c10eed': '"Pues bien, hubo un tiempo en que era común que un mago construyera un gólem: un ser hecho de arcilla y dotado de poder por la magia."*"Se usaban para hacer tareas físicas sencillas, pues eran inmensamente fuertes.  Pero había un problema."*"No había forma de deshacer al gólem, salvo destruyéndolo físicamente.  Y cuando su amo moría, nadie podía controlarlos."*"Se desmandaban y causaban gran violencia y destrucción.  Por desgracia, todavía quedan unos cuantos hoy en día."*"Por eso el estudiante que empieza aprende que todos sus conjuros pueden tener consecuencias duraderas."',
    '26b2f8f9': '"Todo Mago ha tenido que leer las Profecías de Neleneus."*"Por desgracia, solo se conservan la Primera y la Tercera: debería haber ejemplares en la Biblioteca del Magisterium."',
