    'd6696d39': 'Ceca', 'a3ceb237': 'La ceca oficial está ',
    'c3e63e31': 'Mago Bryaxis', 'c1c5ee31': 'Tiene una casita propia en el extremo nordeste de la ciudad.',
    '52216e10': 'Juez Berossus', '0beef0f0': 'El juez Berossus vive en el Castillo de los Tiranos, en el extremo norte de la ciudad.',
    '607f31ab': 'Maga Anisa', 'd909d6e3': 'Vive en una casita justo al sudeste de los Comunes.',
    'f345f285': 'Thoas el Herrero', '9da1d7f7': 'La herrería de Thoas está ',
    'c6c0b30e': 'Oeneus el Flechero', '787a304a': 'Tiene un taller ',
    '1d3c009a': 'Alastor el Curtidor', 'bda40090': 'Su curtiduría está ', 'e32905ed': ': basta con seguir el olor.',
    '6d856ded': 'Hypsenor el Sastre', 'ea27f9fa': 'Hypsenor tiene una tiendecita al norte de los Comunes.',
    '6761a859': 'Antenor el Comerciante', '906776b8': 'El comerciante Antenor tiene una tiendecita al noroeste de los Comunes.',
    '0f9006a7': 'La Sala del Rey de la Tierra queda al norte, cruzando el bosque: deberías seguir el camino desde Odemia.',
    'bbad4fae': 'Catamarca queda al sudeste, cruzando el Sitia y luego bajando por la costa.',
    '9c812be3': 'Odemia queda subiendo por el camino que sale de la ciudad hacia el nordeste.',
    '4d43a565': 'Pnyx queda en la costa occidental, por el camino que sale de la ciudad hacia el oeste.',
    '6b9925a0': 'Kosha queda más al sur, siguiendo la costa desde la ciudad.',
    'd90a21f3': '"Demodocus estuvo tocando en una de las tabernas de por aquí."',
    '00dea0a5': '"Hace tiempo que Demodocus no anda por aquí."',
