Object.assign(DELV_TRANSLATION_ES.text, {
  // the dice game of the three taverns: "I roll a " + a number word + ...
  '0812': {
    '9941611a': '"Lo siento, pero aquí no se fía: vuelve cuando tengas los óbolos"',
    '2a4d2037': '"¿Necesitas que te explique las reglas?"',
    '76b96bb8': '"Es muy sencillo: tenemos tres dados.  Los dos míos son negros y el tuyo es blanco.  Yo tiro el primero, y luego tú tiras tu dado.  Si coinciden, ganas 2 a 1."*"Si no coinciden, tiro mi segundo dado.  Si tu dado blanco queda \'atrapado\' entre mis dos dados negros, gano yo.  Por atrapado quiero decir que el número de tu dado esté entre los de mis dos dados, y eso incluye que sea igual al de mi segundo dado."*"Por cada punto que estés por encima de mi dado más alto o por debajo del más bajo, eso es lo que ganas.  Por ejemplo, si saco un 5 y un 6, y tú habías sacado un 1, ¡te llevas 4 a 1!"*"Tenemos una regla especial: si la paga fuera 1 a 1, eso solo significa que volvemos a jugar sin más, sin tener que repetir la apuesta ni nada."*"¿Te parece divertido?"',
    '962b4d5d': '"Bueno, quizá en otra ocasión."',
    '8c3035bf': '"Bien: vamos allá, entonces."',
    '8d393c46': '"¡Ah, tenemos aquí a un experto!"*',
    'ba2719ef': 'uno', 'be248829': 'dos', '888603c3': 'tres', '2f69f5a5': 'cuatro', 'aeb44395': 'cinco', 'ca3007ab': 'seis',
    '7fb49853': '"Lo siento: parece que estás sin blanca.  Más suerte la próxima vez."',
    '99eff83c': '"Yo saco un ',
    '1fcf6067': ' y tú sacas un ',
    '66085eff': '¡Coinciden, así que ganas 2 óbolos!"*',
    '395b89f7': 'Luego saco un ',
    '1e6a72e9': '"Por desgracia, eso significa que gano yo.  Ahora te quedan ',
    'eebdbfe0': '"¡Ah, tenemos ganador!  Ganas ',
    '491f168e': ', lo que te deja en ',
    'b0f498e8': '"Eso es un empate, así que volvemos a jugar..."*',
    '9b49471a': '"¿Otra partida?"',
    '1c64d3b2': '"Muy bien: vamos."*',
    'e39c8767': '"Muy bien."',
  },
  // what a tavern keeper says, and the rumours, each printed between quotes
  '0813': {
    'a6c1c5af': '"Parece que tu viaje es difícil.  Quizá deberías pedir a otros que se @unan a tu misión."',
    '17d53c19': '"Esta plaga ha hecho mucho daño al negocio."',
    'b0cc7b91': '"Hay gente a la que Darius no le cae muy bien, sobre todo a Mantinea, pero conmigo siempre ha sido educado."',
    'f2ba80f4': '"¡Un viejo minero que se aloja en la Casa Attis estuvo aquí la otra noche diciendo que había visto una especie de fantasma!"',
    'cc1dfa29': '"Ese asesinato en la sala del consejo tiene al pueblo revolucionado."',
    '25992e91': '"Nuestra entrega de vino del Viñedo de la Costa Norte se está retrasando: espero no quedarme corto."',
    '358494a7': 'La otra noche hubo aquí un borracho que decía conocer el lugar de la Tumba del Segundo Tirano, y que se lo diría a cualquiera, a cambio de algo, claro.',
    'e030a7ab': 'Es increíble las cosas que se oyen arrastrándose por las alcantarillas en busca de ratas...',
    '38ce13cb': 'He oído que en Catamarca hay un problema, con gente que se pone enferma.',
    '0d6f8778': 'Más vale que tengas cuidado si vas a andar por la parte vieja de la ciudad cuando oscurezca: todos esos callejones oscuros y retorcidos...',
    '5e23a726': 'La Casa Attis está teniendo problemas con su mina de hierro.',
    '576083d1': 'Hay quien susurra que los chicos de Comana tuvieron algo que ver con la muerte de su padre.',
    '3e3e558d': 'Es un poco raro, pero dentro de la Casa Solariega de Comana se huele de verdad el mar.',
    'cea51efc': 'Si llegas a Cademia, quizá podrías ver qué tal está Stentor.  Me preocupó cuando se fue: era un buen cliente.',
    '5a023e01': 'Hace un mes o así pasó por aquí un viajero que decía haber visto una especie de fantasma blanco en el bosque.',
    '3fd8e2e6': 'He oído que la Casa Comana ha hecho inversiones en existencias de vino: ojalá no suba el precio.',
    '69060815': 'Con todo el malestar que hay, parece que nuestro sistema político de fondo está fallando.',
    '4251ab24': 'Dicen que encontraron un montón de esas viejas ruinas abajo, en una ciénaga del sur.',
    '8c232cc9': 'He oído que hay un montón de túneles bajo el Magisterium de Pnyx, que excavaron los magos para guardar sus experimentos fallidos.',
    '3212a6e0': 'El otro día un tipo contaba que una vez vio a un Mago atravesar una pared, y que ni siquiera había una puerta secreta ni nada.',
  },
  '0816': {
    'f0bf2860': 'Indicaciones',
    '8a15900c': '¿Adónde quieres ir?',
  },
  '0817': {
    '51015190': '"Las tareas de un Juez son numerosas: resolver @disputas, presidir el @Consejo, establecer la @popularidad de las Casas, y cosas así."',
    '7262f4f4': '"Somos terceros imparciales que usamos nuestros poderes mágicos para llegar al fondo de las disputas entre ciudadanos."*"Como un ciudadano no puede mentirnos, y no tenemos más lazos políticos ni familiares que con Alaric, somos muy adecuados para esta tarea."',
    '601f0425': '"Cuando hay asuntos de ley de la ciudad, presidimos la reunión del Consejo, y nos aseguramos de que sea justa para todas las Casas presentes."*"También tenemos poder para vetar cualquier ley que no consideremos en el mejor interés de la tierra."*"Claro que una Casa siempre puede apelar a Alaric, pero las pocas veces que ha ocurrido, él siempre nos ha dado la razón."*"Con el debilitamiento de Alaric, sin embargo, este sistema puede tener problemas en el futuro."',
    'd0cba697': '"Es deber del Juez asegurarse de que el poder de voto de las Casas corresponda directamente a la popularidad de cada Casa entre los ciudadanos de la ciudad."*"Normalmente se hace cada año, con elecciones (y como detecto cuándo la gente me miente, hay muy poca posibilidad de fraude)."*"Sin embargo, una Casa puede pedir elecciones extraordinarias, si el Juez considera sólido el motivo, como un cambio en la jefatura de la Casa."',
    '0a86b164': '"Como Mago, no dudo de que Alaric se recuperará y seguirá guiándonos hacia la prosperidad."*"Como Juez, estoy obviamente más cerca de la situación que el resto de los ciudadanos, y estoy preocupado."*"No sé qué haremos si cae: son tiempos peligrosos, sin duda."',
  },
  '0986': { 'fc8d9bf0': '¡Muere!', '6127ccd4': '¡Argh!' },
});
