Object.assign(DELV_TRANSLATION_ES.text, {
  // a drunk in a tavern, and the Second Tyrant's tomb
  '1811': {
    'fd7ec15f': 'Ves a un borracho viejo, sucio y maloliente.',
    '382927a4': '*Parece que ha perdido el conocimiento.',
    'cf3ddfa9': '"Acércate... así, mejor.  ¿Quiere\' saber un secreto?"',
    'd1febd06': '"Tú te lo pierde\'."',
    '1a782ceb': '"¿Has estao alguna ve\' en Cademia?"',
    'dfcde361': '"¿Sabe\' el castillo ese de allí?"',
    '69e0b32d': '"Sí, hombre: donde vivían los Tirano\'."',
    '3edeb771': '"Eso, ese mismo."',
    '7e42c062': '"Lo construyeron los Tiranos, sí."',
    '50c27e6e': '*"¡Pues mi bisabuelo ayudó a construirlo!"*"¿Y sabe\' lo que me contó?"',
    '12368229': '"Ah, pue\' entonce\' nada."',
    '3ec617fc': '"Me contó dónde estaba escondía la tumba del Segundo Tirano."*"¿Quiere\' saberlo?  Te va a costar..."',
    '0c1ed2bd': '"Estás tan pelao como yo: no está bien burlarse de un viejo."',
    '86c92e6a': '¿Cuántos óbolos le das?',
    '810db3f2': '"Allá tú."',
    'b80b1c23': "\"'Dos pasos pasado el mediodía', me dijo.  No sé qué quería decir, pero ahí estaba escondía la entrada.\"",
    'e773d9bc': '*"Como has sío amable con un viejo, tengo algo pa\' ti."*Rebusca entre su ropa mugrienta, tirando trozos de basura de todo tipo.*"¡Aquí está!  Me dio esta llave: ¡dijo que abriría la tumba!"*El viejo te da la llave.',
    'ce5c0739': '*Después el viejo pierde el conocimiento.\n',
    'cd3593d3': '"Pue\' entonce\' nunca vas a saber el secreto."',
  },
  // Areithous, of the Roasted Haunch in Kosha
  '1812': {
    '8a23f9ee': 'Ves a un hombre apuesto pero de aire presumido, con una larga melena suelta.\n*"',
    '2d86b9f5': ': ¡pasa, pasa!"',
    '6defca0a': '"Me llamo Areithous, dueño de este magnífico @establecimiento."',
    'cfa0b487': '"¡Pues El Muslo Asado!  ¡La mejor @carne de toda Cythera!"',
    '57aca59f': '"Llevo este magnífico @establecimiento: ¿te @interesa algo?"',
    '7a4a60ff': '"Sí: ¿te interesa algo de @carne, o solo una @bebida y buena conversación?"',
    'e7af6646': 'Las mejores carnes', '005f8d1c': 'Brocheta', '52455a6a': 'Muslo', 'bc408505': 'Filete',
    '1e331e5b': '"Es todo lo que he deseado siempre: ¡la compañera perfecta!"*"Hemos tenido nuestros problemas, pero esta vez he cambiado."',
    '2e2985d9': '"Pronto Laodice será mi mujer."',
    '738b63ba': '"Stentor era uno de mis mejores clientes: dicen que perdió un poco la cabeza."*"Creo que ahora está en algún lugar de Cademia."',
    'c0c92ab2': '"No acabo de entenderte."',
  },
  // Laodice, Comana's cook
  '1813': {
    '3c274cd5': 'Ves a una joven atractiva, que parece cansada pero contenta.',
    '36a055cb': '"Hola de nuevo, ^',
    '4eddef63': '"Soy Laodice... ¿y tú eres?"',
    'fffbfd44': '"Encantada de conocerte, ^',
    '5d860751': '"Soy la cocinera de la Casa Comana, aunque eso quizá @cambie en el futuro."',
    'e9cbe989': '"Ser cocinera es lo que siempre he querido, y esa es una de las razones por las que Ariethous y yo estamos hechos el uno para el otro."',
    '9c7a3dd5': '"Para eso tendrás que ir a la taberna y hablar con Areithous."',
    '78f5446f': '"Adiós, entonces."',
    '0e4add57': '"Cuando me @case con @Areithous."',
    '9567978e': '"Pues sí, @Areithous y yo nos casamos el verano que viene.  Es lo que siempre he querido."',
    '7117e760': '"Es el hombre de mis sueños."',
    '288e33ca': '"Atreus es un encanto, y mi amigo de más confianza, pero se preocupa demasiado por mí."',
    'c03c8a20': '"Me temo que no te entiendo."',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys, { '1812': { laod: 'laod', sten: 'sten', arei: 'arei' }, '1813': { arei: 'arei', atre: 'atre' } });
Object.assign(DELV_TRANSLATION_ES.keys['*'], { rumo: 'rumo', prob: 'prob', worr: 'preo' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Matron Thuria of House Attis, and the report on the mine
  '1814': {
    'c61e141d': 'Ves a una anciana viuda, de porte noble.*',
    'f75e76d0': '"Soy la matrona Thuria, Anciana de la Casa Attis.  ¿Y tú eres?"',
    '07a8ecec': '"Encantada de conocerte, ^', 'da6007c7': '"Te saludo de nuevo, ^',
    '68d05d11': '"¿Has averiguado algo sobre lo que pasa en la mina?"*',
    '584c7d13': '"Sí, la verdad es que he averiguado mucho."*',
    'bb9d634d': '"¿Algo que quieras contarme?"*',
    '40439731': '"Todavía no conozco todos los detalles, pero hay una especie de ser en las profundidades de la mina."*',
    '199fa043': '"¿Un ser?  ¿Hostil?  ¿Amistoso?  ¿Por qué está ahí?"*',
    'ac67c06a': '"No lo sé con certeza: lo único que sé seguro es que probablemente no quiere hacer daño, y solo desea que lo dejen en paz."*',
    '3d713017': '"Eso me sirve de poco, pero te agradezco el esfuerzo de todos modos."',
    'c03668a5': '"Sí, he estado en la mina, y he visto al supuesto fantasma"*',
    'eecf0643': '"¿Y?"*',
    '7da189d6': '"No sé muy bien qué era.  Pero no parece hostil."*',
    '2a740fdc': '"Bueno, gracias.  Sigue ocupándote de este asunto, si eres tan amable."',
    '31eedea8': '"He hablado con Amphidamas, y he oído su versión de la historia."*"Por ahora, lo más que puedo hacer es confirmar el informe de Atymnius."*',
    'f6d3900a': '"Muy bien, sigue investigando este asunto, por favor."',
    '738ffa6f': '"He hablado con Atymnius, así que he oído el informe de su boca."*',
    '9ea4fe5c': '"Es un comienzo, pero tendrás que ir a la mina para saber más detalles."',
    '6a7c2740': '"Soy la matrona Thuria."',
    '39bf7a7f': '"Soy la Anciana de la Casa @Attis, y con el apoyo de la Casa Strymon seguimos siendo la casa más fuerte de Cademia."',
    'd2a83a46': '"Adiós, ^',
    'e409ea3d': '"La Casa Attis es una casa noble, con la riqueza de nuestra mina de @hierro para sostenernos."',
    '36919200': '"Con el poder que nos dio nuestra mina de hierro subimos al poder en Cademia, y pese a los @rumores de problemas, nuestra posición es sólida."',
    '7b16aa47': '"El joven Malis tiene mucho que aprender, pero un día me sustituirá."',
    'b0fa75c9': '"Estoy muy orgullosa de mi hija Cybele."',
    '099d5b9d': '"Has oído de primera mano los problemas de la mina."',
    'd63821cb': '"Creo que has aceptado investigar esos rumores por nosotros."',
    '63e8f5fb': '"Son habladurías de taberna, nada más: los mineros, que han perdido el juicio."*"Aunque el propio Atymnius me trajo el informe en persona."*"¿Quizá te interesaría investigar más este asunto?"',
    '98f9bb19': '"Atymnius se aloja aquí por ahora: te convendrá hablar con él, y luego tendrás que ir a la mina."*"Está en la ladera occidental de los Montes del Espinazo del Titán.  Tendrás que tomar el camino de Pnyx y luego girar al sur por la costa."*"Habrá un sendero hacia el interior, por el bosque, que te llevará a la mina."*"El capataz es un hombre llamado Amphidamas.  Confío en que sabrás averiguar qué pasa: la historia de Atymnius era confusa, como poco."',
    '35713b3f': '"Muy bien, está claro que tienes cosas que hacer.  Te agradezco que lo pensaras, de todos modos."',
    'cdc6a8cc': '"Tendrás que buscar en otra parte..."',
  },
  // Malis, her son
  '1815': {
    '0aabc6e2': 'Ves a un hombre nervioso, tímido e inseguro."Hola, ', '954c75fb': 'de nuevo, ', '96a8bdf8': 'señora.', 'ee8cfe35': 'señor.',
    'b2a55d06': '  ¿Qué puedo hacer por ti?"',
    'af7eccab': '"Soy Malis, hijo de la matrona Thuria."',
    'a125c396': '"Un día asumiré el gobierno de la Casa Attis, pero de momento aprendo el negocio familiar."',
    '8a838c94': '"Mi querida madre."', '2dd37701': '"La matrona Thuria."', '093350c8': '"Hasta que volvamos a vernos."',
    '2e62486f': '"De eso tendrás que hablar con mi Madre: no tengo nada que decir."',
    '5b166ce6': '"Mi querida hermana: a veces me preocupa..."',
    '3fa7d57f': '"Dice que no debería preocuparme, que al final todo sale bien, pero aun así, así soy yo."',
    'ba8eac7b': '"Lo siento, no puedo ayudarte..."',
  },
  // Cybele, his sister
  '1816': {
    '0dd50979': 'Ves a una joven hermosa', '7d31d374': ' con el rostro marcado por la tensión.',
    '06933112': '"Te saludo de nuevo, ',
    'eaf6775a': '"Soy Cybele, de la Casa Attis."',
    '352d6076': '"Lo que dicen de Opheltius no es verdad, ¡y yo tampoco fui a ver a Halos!"',
    '1b230dad': '"No puedo creer que Opheltius ya no esté."',
    'ad464270': '"Opheltius es un buen amigo de la familia."',
    '1ab10083': '"Nunca fui a ver a Halos, y desde luego no para contarle nada de Opheltius"',
    'e3cc28f1': '"Me da mucha pena lo que pasó, aunque al menos a Halos lo declararon inocente."',
    'a52bc612': '"Aunque nuestras familias no son amigas, es un hombre honorable."',
    '3ba66d63': '"La verdad es que no sé qué haré en el futuro.  Mi hermano Malis asumirá las obligaciones de la Casa, y yo, no sé."',
    'c289d265': '"Mi hermano: a veces es un poco sobreprotector, pero tiene buena intención."',
  },
});
