Object.assign(DELV_TRANSLATION_ES.text, {
  // the iron mine's camp: Amphidamas the foreman, Eurybates, the miners, Atymnius
  '1817': {
    '535fc809': 'Ves a un hombre bajo y fornido, con una sonrisa desagradable.*',
    'b49d7642': '"^', '7ab980ab': ': ¿qué puedo hacer por ti?"',
    'ac8278a0': '"Si vienes buscando trabajo, no contratamos hasta que se resuelvan ciertos @problemas."',
    '83393f4f': '"Soy Amphidamas."',
    '13a6d698': '"Soy el capataz aquí, en la @mina de @hierro."',
    '52dbd349': '"Es un metal bastante interesante, pero demasiado duro para poder forjarlo como el bronce, aunque los Magos deben de conocer algún @truco."',
    '3a728037': '"Claro, si no, ¿cómo crees que se hacen de hierro nuestras monedas?  Un herrero puede hacer con él un arado, pero no una moneda."',
    'cee3791d': '"Esta mina es de la Casa Attis.  Gente bastante decente para trabajar, si es que dan con qué hacer con el @fantasma."',
    '3320de5b': '"¿No has oído la historia del @fantasma?"',
    '99caf912': '"Ya te he dado mi informe: puedes llevárselo a Thuria, o investigar tú más a fondo."',
    '8e80d5d9': '"Thuria te ha enviado a investigar la historia del @fantasma, ¿eh?"',
    'f77eae30': '"La matrona Thuria es una patrona difícil, pero justa."',
    'f07bbfcf': '"Hace cosa de una semana, Atymnius, uno de mis hombres, está excavando un túnel nuevo y descubre una especie de cueva."*"Normalmente eso sería bueno: menos que excavar, ya sabes.  Pero esta cueva no está vacía.  Hay algo dentro."*"Parecía tener más o menos forma de hombre, pero no del todo.  Y parecía brillar con una luz blanquecina, y hablaba una lengua que no habíamos oído nunca."*"Atymnius sale de allí a toda prisa, muerto de miedo, así que yo y un par de hombres más volvemos a echar un vistazo."*"Y en efecto, tenía razón.  Nunca había visto nada igual en mi vida, y espero no volver a verlo."*"Mandé a Atymnius a Cademia para que hablara con Thuria y ver qué dice ella, pero te digo una cosa: hasta que esa cosa no se vaya, no volvemos a entrar."',
  },
  '1818': {
    '2f45aa2e': 'Ves a un joven delgado, de aspecto astuto.*',
    '666ac812': '"Eres nuevo por aquí: permíteme que me presente.  Soy Eurybates."',
    '67401e08': '"¡Buenas!"',
    '6c1289de': '"Soy Eurybates."',
    '773bd424': '"Soy el cocinero y el cazador del campamento."',
    'c8edcb64': '"He tenido trabajos peores; la vida en un campamento minero no es tan mala."',
  },
  '181D': {
    'e5d96871': 'Ves a un minero fornido, pero su rostro delata un horror que lleva en la mente.*',
    'fd96a8b7': '"Déjame en paz: ¡no quiero hablar de eso!"',
    'a175c553': '"Disculpe, señor, pero ¿es usted Atymnius?  Thuria me ha enviado a hablar con usted..."*Te mira de arriba abajo, y se detiene un segundo.*',
    'c937b32f': '"Sí, ese soy yo.  Pero ya le conté mi @historia a ella..."',
    '0d1538b5': '"Ya te he contado lo que sé: ¿qué más puedo hacer por ti?"',
    '63fd1a55': '"Me llamo Atymnius, pero creía que ya te lo había dicho..."',
    '80727816': '"¿Qué?"',
    '1a996b81': '"Era minero allá abajo, en la mina de hierro de Attis: no sé si volveré..."',
    'a3f6e543': '"Ya te lo he dicho, no me gusta pensar en eso..."',
    '383083d7': '"Ya se lo conté a Thuria, pero supongo que podría contarlo una vez más: no me gusta mucho pensar en ello."*',
    'cb965e05': '"El caso es que estaba trabajando en lo hondo, alargando los túneles.  Es un trabajo duro, pero me gusta más que andar removiendo tierra."*"Pues eso, estoy al fondo de los túneles, y de repente noto que la tierra empieza a moverse."*"No hay nada peor que un derrumbe, así que corro hacia los túneles viejos todo lo rápido que puedo, esquivando algunas rocas grandes."*"Pero entonces una me da en la cabeza, y pierdo el sentido: no sé cuánto tiempo, pero se me apagó la antorcha."*"Tuve un sueño extraño, además: algo sobre la pena y la pérdida, solo que más intenso de lo que ningún hombre debería sentir nunca."*"El caso es que vuelvo en mí, y consigo encender una de mis antorchas de repuesto.  Lleva siempre antorchas de repuesto, de las que esperas no necesitar nunca."*"Miro, esperando estar atrapado, pero no: solo unas cuantas rocas grandes movidas en el túnel nuevo."*"No es que siempre se note, ojo, porque un túnel sin acabar puede parecer derrumbado, y eso es normal."*"El caso es que miro a ver cuánto trabajo he perdido, y resulta que no solo estaba bastante bien, sino que hay una abertura."*"Normalmente eso es bastante bueno, porque una bolsa de cueva pequeña puede ahorrarte semanas de excavación."*"Así que justo cuando pienso que ha cambiado mi suerte, que no solo he sobrevivido al derrumbe sino que voy adelantado, bajo por la abertura."*"Y allí lo vi.  Todo blanco y reluciente a la luz de la antorcha, sentado en una roca."*"Nunca había visto nada igual: se vuelve hacia mí, con esos ojos muertos, y dice algo que no entiendo."*"No sabía que los muertos hablaran otra lengua, pero hay muchas cosas que no sé."*"Aquello fue demasiado para mí: ver la agonía en su cara.  Era un alma en pena, ahora lo sé."*"Casi se me cae la antorcha al huir: fue demasiado para mí."*Hunde la cabeza entre las manos y solloza un poco, con los hombros temblando.*"Por favor, dame un minuto para recomponerme..."*',
    '578cf5ae': '"Adiós, y ten cuidado."',
  },
});
