Object.assign(DELV_TRANSLATION_ES.text['*'], {
  '07087d79': 'Poción Amigo del Herrero', 'fffbfd44': '"Encantada de conocerte, ^', '5c30da4a': '"Prefiero no hablar de eso."',
  'b298967f': '"Que te vaya bien."', '372e1d0a': '*"Por favor, ya he dicho demasiado..."',
});
Object.assign(DELV_TRANSLATION_ES.text, {
  // Milcom, the blacksmith of Odemia, once head of House Atussa
  '181E': {
    '441a4e1b': 'Ves a un hombre fuerte y poderoso, de aspecto severo.*',
    '43b7ed4a': '.  ¿Qué te trae por aquí?"',
    'bddef26e': '"Lo siento, pero ¿podrías volver más tarde?  Ahora no es momento de negocios."',
    'f339dd16': '*"Pero por favor, señor, solo será un minuto."*',
    '48df384c': '"Sí, ¿en qué puedo ayudarte?  Espero que el @calor no sea demasiado para ti..."',
    'dbfdd3cd': '"Soy Milcom, técnicamente el jefe de la Casa @Atussa."',
    'cdfd8995': '"Soy un humilde herrero, y muy @contento de serlo."*"¿Quizá hay algo que quieras @comprar?"',
    '6fe2b2d1': '"Mi mujer, Ake, lleva aquí un taller de tejido, y hace un trabajo muy fino."',
    '78a1e6a1': '"Ser herrero es más gratificante que dirigir la Casa @Atussa."',
    '3b5649fc': '"Atussa es una Casa antigua y, a decir verdad, su tiempo ya pasó."',
    'c3b8194e': '"Nicander es ahora la Casa gobernante de Odemia, y que les aproveche."',
    '13ed3877': '"Aunque Atussa tiene poco poder, seguimos siendo aliados de la Casa @Strymon."',
    '556d7de1': '"Adiós, ',
    '3b90e105': '*"Ah, no sé si te servirá de algo o no, pero ¿has oído hablar de un Mago llamado Eioneus?"',
    'a759d3b8': '"Ah, entonces sabrás que ha estado trabajando en mejorar las armas con magia..."',
    '5f750a03': '"Tengo entendido que ha estado trabajando en mejorar las armas con magia."*"Hablé con él hace un par de años, y le conté mis técnicas y cosas así."*"No sé dónde estará ahora, pero quizá valga la pena que lo busques..."',
    '252d0ac4': '"Como herrero, me acostumbro al calor de la fragua, aunque a veces todavía uso un @brebaje refrescante."',
    '7754560c': '"Tengo una provisión de pociones que me permiten aguantar un gran calor durante poco tiempo."*"Me vienen muy bien en la fragua."',
    '40e00796': 'Quizá tenga algunas cosas que te interesen.',
    '0306bb11': 'Peto de metal', '9fd0cdf0': 'Yelmo completo', '194ff0b5': 'Escudo completo',
    '5d49c448': '"Un secuestro no es más que otra señal de los @problemas de la tierra."',
    '157b988f': '"Todos hemos oído rumores sobre Alaric, una @plaga en @Catamarca y disturbios en @Cademia."',
    'c77eeebf': '"Una especie de plaga mortal ha azotado Catamarca, costa abajo: me preocupa nuestro @hijo."',
    '5098dd8e': '"Bueno, hemos oído que la plaga se ha curado, pero aun así..."',
    '1c55ac6d': '"Nuestro hijo Sardis está abajo, en Catamarca."',
    '9f4ff401': '"Lo siento, pero no lo entiendo."',
  },
  // Sardis, their son, in Catamarca; he says "gentle lady" or "good man"
  '181F': {
    '66f38c60': 'Ves a un hombre menudo, vestido de forma impecable.',
    'dae194e0': '"Por favor, ahora no estoy para visitas..."',
    '97ca797f': '"Hola, ', '0002687a': 'gentil dama.', '23ef8336': 'buen hombre.', '320e8bea': ' ¿En qué puedo servirte?"',
    'f891ddb7': '"Hola de nuevo, ', '5bca4288': 'gentil dama."', 'a60b587c': 'buen hombre."',
    'd161bdc4': '"Soy Sardis, hijo de @Ake y de @Milcom, de la Casa @Atussa"',
    '6d0c4f31': '"Oficialmente, represento a la Casa @Attusa en Catamarca."*"En realidad, trabajo más para la Casa @Strymon que para Attusa."',
    '11c37eed': '"Nuestra casa, básicamente, ha caído."',
    '35edddb3': '"Strymon gobierna Catamarca, lo cual es bueno para todos."',
    '43e2a143': '"Ake es mi madre: es tejedora en @Odemia."',
    '6c5cdb85': '"Milcom es mi padre: es el herrero de @Odemia."',
    '613cad14': '"Odemia es nuestro hogar ancestral: la fundó un attusano."*"Ahora la gobierna la Casa @Nicander."',
    '4e417b9b': '"Que les vaya bien: el Anciano Philinus es un hombre honrado, pero su hijo menor..."*"En fin, Ascalon es un idiota.  Al menos heredará Opheltius...."',
    '201e08b3': '"El Anciano Philinus es un hombre honrado."',
    'd68ea5de': '"Ascalon es un idiota."',
    '3355c9cd': '"Opheltius intenta representar a la Casa Nicander en Cademia."',
    'c80866f4': '"Lo siento, en eso no puedo ayudarte."',
  },
  // Ake the weaver, Milcom's wife, and what she knows of the kidnapping
  '1820': {
    '43042423': 'Ves a una mujer menuda y nerviosa.*',
    'f0c836fb': '"Bien, has venido.  Puede que no sea más que un rumor, pero he oído que la Casa Comana estaba detrás del secuestro de Ariadne."*"No puedo decir más, pero busca a Halos, de la Casa Strymon, en Cademia"',
    'e4235abf': '"Si vienes por tela, por favor, ven a verme cuando esté trabajando en mi tienda."',
    'e328211b': '"¿En qué puedo ayudarte?  ¿Quizá algo de tela fina?"',
    '20fd1d8a': '"Me llamo Ake, ¿y tú?"',
    '91baf169': '"Soy tejedora aquí, en Odemia: ¿quieres @comprar algo de tela?"',
    '00baa506': 'La mejor tela', '04503109': 'Tela azul', 'fcf90c70': 'Tela roja', '51b78e10': 'Tela verde',
    '6ec12180': '=',
    '202839e0': '"Lo siento, pero el hilo se lo compro directamente a @Hebe."',
    '5e13802b': '"Mi @marido es el jefe de la Casa @Atussa."',
    '6b6a73d1': '"Milcom, el Herrero."',
    'f268f9ea': '"A mi @marido y a mí nos gusta trabajar por las tardes en el huerto de detrás de casa."',
    '835d6026': '"Atussa era la Casa gobernante aquí, hasta que mi @marido lo dejó todo."',
    'b2498610': 'Mira a su alrededor con nerviosismo...*"Ah, fue terrible, ¿verdad?"',
    'f63d2192': '"Ya sabes lo que pienso de eso..."',
    '55f9483e': '"Me temo que hay algo @oculto en el secuestro de Ariadne, más de lo que parece."',
    'e48df6d2': '"Ya sabes, la Casa Comana..."',
    'abaf821a': 'Mira a su alrededor con nerviosismo...*"Ah, no sé de qué me hablas."',
    '9f9d6712': '"Ahora no puedo hablar de eso: nos vemos en nuestro @huerto cuando oscurezca, espera a que mi marido se haya acostado"',
    '7a0e13ed': '"Entiendo tu reticencia, pero no sé si podré acudir a esa cita."*',
    '111ca272': 'Ake baja la voz hasta un susurro, mirando nerviosa a su alrededor.*"Bueno, puede que no sea más que un rumor, pero he oído que la Casa Comana estaba detrás del secuestro de Ariadne."*"No puedo decir más, pero busca a Halos, de la Casa Strymon, en Cademia"',
  },
});
