  resp: 'resp', elde: 'mayo', merc: 'merc,comer', born: 'naci', neop: 'neop', demo: 'demo', hagg: 'rega', pers: 'labi,pers',
  teac: 'ense,inst', trai: 'entr', inte: 'inte', diff: 'dist', days: 'tiem', stor: 'hist', clie: 'clie', clot: 'tela',
