Object.assign(DELV_TRANSLATION_ES.text, {
  '1821': {
    'd03d1423': '¡Fuera de mi jardín!', 'f545f633': '"¡Fuera de mi jardín!"',
    '8ed8b738': 'Ves a un viejo con cara de cascarrabias y de pocos amigos.*',
    'd0797f5e': '*"Ah, eres tú."',
    '8d905216': '"¿Qué quieres?  ¿No ves que estoy comiendo?"',
    'efdc3a94': '"¡No es asunto tuyo!"',
    'eef3da3b': '"¡Qué juventud tan impertinente: nunca muestra @respeto a sus @mayores!"',
    'bfc996e4': '"¡No tienes ningún respeto!"',
    'b69760f9': '"¡Yo ya era un mercader de éxito antes de que tú nacieras!"',
    'd22bd3d7': '"Bah, no te interesa."',
    'ad0781b1': '"¡Quién te ha dicho mi nombre!"',
    '0810d5c2': '"Mmm, quizá me equivoqué contigo."*"Sí, soy Neoptolemus."',
    '7e6f0573': '"Ya, claro, como que me lo creo."',
    '3760f36c': '"No he oído hablar de ellos en mi vida."',
    'bed65a67': '"Hmmm..."',
    '5a050270': '"Neoptolemus, ¡y muestra un poco de @respeto a tus mayores!"',
    'f4651037': '"De joven, era @mercader."',
    '737e56df': '"Sí, recuerdo que de joven era un mercader próspero."*"Y entonces sí que sabíamos hacer dinero: el @regateo y la @labia son un arte perdido hoy en día."',
    'c0b52cd6': '"Yo era mercader, ¿sabes?  Podría @instruirte en unas cuantas cosas sobre el regateo."',
    'a4186ac5': '"La juventud de hoy no sabe nada del respeto: podría enseñarte a regatear, pero no te iba a @interesar."',
    '88d8db04': '"Yo era mercader, ¿sabes?  Podría @instruirte en unas cuantas cosas sobre la labia."',
    '2f40e1e0': '"Qué insolencia: podría enseñarte a convencer a la gente, pero no te iba a @interesar."',
    '65428b46': '"Has tenido la amabilidad de sentarte a escuchar las historias de un viejo..."',
    '69441fea': '"Si mostraras un poco de @respeto, quizá tendría más ganas de charlar."',
    '39ada165': '"¡Ja!  ¡Qué sabrás tú del respeto!  ¡Si ni siquiera nos han presentado!"',
    '5c995955': '"Entras aquí sin llamar, exigiendo que conteste a tus preguntas tontas: ni una pizca de respeto."*"En mis @tiempos, hacíamos las cosas @distinto."',
    '1bb45fb7': '"Bueno, recuerdo una vez que tuve que ir a @Odemia a comprar @tela para un @cliente."',
    'b688b07e': '"Sí, entonces las cosas eran distintas..."',
    'd41e780d': '"Quién era el cliente no importa: ¡deja de interrumpir mis historias y muestra un poco de respeto!"',
    '2cf9c2b4': '"Sí, tela: ¿tienes la cabeza de piedra o qué?  Un poco de respeto aquí..."',
    '2566c516': '"Odemia siempre fue famosa por su @tela: supongo que allí no había mucho más que hacer."*"Pues eso, iba camino de Odemia, pero antes tenía que conseguir unas @uvas."',
    '58e6b5e9': '"Qué dura tienes la mollera: ya te he dicho que iba a Odemia.  Ahora me has hecho olvidar la historia..."',
    '629ee258': '"Verás, entonces estaba de @moda llevar un racimo de uvas atado al @cinto."',
    '0bf2bdb6': '"Qué sabré yo de moda: soy un viejo.  Deja de hacerme preguntas tontas."',
    'b02f7a4a': '"Por supuesto, entonces todo el mundo llevaba @cinto, y además eran @baratos.  Hoy en día no hay manera de conseguir una @capa por menos de 15 @monedas."',
    'f37564ae': '"¿Me estás llamando tacaño?  ¡Juventud insolente: muestra un poco de respeto a tus mayores!"',
    '2ab5c3fb': '"No estaba hablando de capas, a ver, ¿por dónde iba?  Deja de intentar liarme: ¡soy un viejo!"',
    '1b0423d4': '"Entonces los óbolos no eran tan @elegantes como ahora, pero llevaban dibujos de @abejas."',
    'dc467829': '"¡Qué sabrás tú: no eres más que una criatura insolente que ni siquiera deja a un viejo contarle una historia!"',
    '817453f5': '"Sí, \'Uvas, dos abejas\', decíamos, porque eso era lo que costaban las @uvas."',
    'c58349e5': '"Mmm, uvas... eso me recuerda una historia..."',
    '7f4aa933': '"Eso es: nos atábamos uvas al cinto.  Era la moda, ¿sabes?"*"Mmm, quizá me equivoqué contigo: has tenido la amabilidad de dejar que un viejo te cuente sus historias."*"Has mostrado respeto y todo.  Quizá pueda @instruirte en unas cuantas cosas..."',
    '90e481ec': 'Regateo', '522116c6': 'Labia',
    '4c3b19a2': '¿Qué quieres que te enseñe?',
    'ec3058e0': '=',
    'd9d00ea8': '"No te enseñaría ni a atarte las sandalias..."',
    '1481bb11': '"¿Por qué interrumpes mi historia?"',
    'de7fa4b3': '"¿Qué estás farfullando?"',
  },
});
