Object.assign(DELV_TRANSLATION_ES.text, {
  // Hebe the threadmaker, and Antenor, whom she was to marry
  '1823': {
    '9677eb57': 'Ves a una mujer menuda y apocada.*"¿Sí?  ¿En qué puedo ayudarte?"',
    'efdc1b47': ', una última cosa: si estás en Cademia y te encuentras con un comerciante llamado Antenor, dile que le perdono."',
    'dc5cb40c': '"Me llamo Hebe, ',
    '29dcb67c': '"Es buena persona, pero lo que siento por Antenor es demasiado fuerte como para pensar en otro."',
    'a3d567b3': '"Él y yo íbamos a casarnos."',
    '667954ea': '*"¿Traes noticias de él?"*',
    '51d8fc3a': '"Sí, lo encontré y le di tu mensaje.  Dijo que tiene que perdonarse a sí mismo antes de buscar tu perdón."*Hebe parece decepcionada.*',
    'aaadaf43': '"Lo entiendo.  Gracias por intentarlo."',
    'bb4d6e7a': '"Hilo el @lino para hacer @hilo, que luego le vendo a @Ake."',
    '86f41bfc': '"Es mi mejor clienta.  Mi única clienta, eso sí."',
    'e22f4daa': '"Lo siento, pero le he prometido a @Ake todo lo que pueda hilar."',
    'dd84b49f': '"Lo siento, pero en esto no soy más que una aprendiza; en cambio, Ake seguro que podría enseñarte..."',
    'e326ebb0': '"¿Tienes lino que quieras vender?  No tengo mucho, pero puedo pagarte 10 óbolos por fardo."',
    '4316fcd6': 'Lino',
    'fc5d3909': '"No puedo ayudarte, ',
  },
  '1824': {
    '5e1d9693': 'Ves a un hombre callado e introspectivo.*',
    'badb4a8b': '"Soy Antenor, antes de Odemia"',
    '25263e6e': '"Soy un simple comerciante, que trata en cosas para el hogar."',
    '93950caa': '"Compro a los artesanos de aquí y vendo sobre todo a las casas: seguramente nada que te interese."',
    '438e0ded': '"Eso es parte de mi pasado: prefiero no hablar de ello."',
    '83f29466': '"Todo fue culpa mía, y tengo que afrontarlo yo solo."',
    '58eb7f61': '"Iba a ser mi mujer."',
    '0165586b': '"Me dijo que te dijera que te perdona."*',
    'b05abc65': '"Te agradezco el mensaje, pero tengo que perdonarme a mí mismo antes de poder buscar su perdón."',
    'f0b8f7a7': '"Espero que te guste tu nuevo edificio..."',
    '60dfebb7': '"Sí, ¿te interesa comprar el edificio?"',
    '120ed8f8': '"Represento a la familia del difunto dueño en esta venta.  Si te interesa, cuesta 10.000 óbolos."',
    'e46d9ab7': '"De verdad que no deberías llevar tanto dinero encima, pero en fin, toma..."*Rebusca entre unos papeles, te hace firmar unas cuantas cosas y se queda con tu dinero.*',
    '1514da2c': '"Aquí tienes una llave del sitio; espero que disfrutes de tu nuevo edificio."*Te da la mano y una llave.',
    '084c27eb': '"¡Pero si no tienes 10.000 óbolos!"',
    'e297f2a3': '"Lo entiendo: no hay mucha gente que pueda permitirse una propiedad tan selecta."',
    '35b17936': '"Bueno, seguramente es lo mejor: es bastante caro."',
    '4f68efee': 'No parece entenderte.',
  },
});
