Object.assign(DELV_TRANSLATION_ES.text, {
  // Tlepolemus the fisherman, an old friend of Philinus
  '1837': {
    'de5adcc5': '¡Crito!', 'd441f5d9': 'Excelente', '05024ed0': 'Gracias', 'e02e13e0': 'Tiene buena pinta',
    '42fb1c03': '"¿Sabes?, no hay nada más satisfactorio que @pescar..."',
    'aafb83b7': '"Sí, ¿qué puedo hacer por ti?"',
    '38b40975': '"Tlepolemus."',
    '59c0ce60': '"Sobre todo @pescar, y algo de @caza."',
    '8107dde4': '"Las Casas suben y caen, los tiranos van y vienen, pero el @mar siempre está ahí."*"Y donde está el mar, hay peces.  Y donde hay peces, estoy yo."*"¿Quizá quieras @comprar alguno?"',
    'ca010bfb': '"¿Quieres comprar pescado?"',
    'cf248e1b': 'Pescado fresco',
    'ae511bee': '"Tú te lo pierdes: lo he pescado yo mismo, ¿sabes?"',
    'e69bbfc2': '"Antes cazaba, pero prefiero pescar, sobre todo con todos esos @bandidos y demás gentuza por los bosques."',
    '9438fce7': '"Los he visto sobre todo en los bosques al noroeste del camino entre Odemia y Cademia, pero podrían estar en cualquier parte..."',
    'b83017f1': '"Puede que ahí fuera haya @monstruos, pero hay peces."',
    '02532f6a': '"Monstruos marinos: hunden cualquier barco que se aleje de la orilla..."*"¿Por qué crees que pesco desde la orilla?  Esas historias de monstruos marinos son verdad."',
    '7164c4de': '"Hmm."',
    '421ada01': '"Puede que ahí fuera haya algún @monstruo marino, pero los peces no han secuestrado nunca a nadie."',
    'b4730535': '"Claro que apoyo a la Casa Nicander: hace años iba de caza con el Anciano @Philinus."',
    'a5c5bbde': '"No le guardo rencor; al fin y al cabo, es un hombre ocupado..."',
    '9fe69961': '"Hablé con él, y dijo que sentía haber dejado que los negocios se interpusieran en vuestra amistad."*',
    '3678385b': '"¿De verdad?  Estupendo: quizá debería ir a visitarle y hablar de los viejos tiempos."*"Gracias por tu ayuda: has ayudado a un viejo."',
    '7fa5d43c': '"Antes éramos bastante amigos, pero últimamente nos hemos distanciado: supongo que está demasiado ocupado para tratar con gente como yo."',
    '10a5e4a8': '"Milcom es un buen hombre: siguió a su corazón y se hizo herrero en lugar de cargar con los problemas de una Casa."',
    '9f05edf7': '"Espero que la disfrutaras: yo no le estaba sacando ningún provecho."',
    'c2a639eb': '"Antes tocaba la flauta de Pan, pero lo dejé hace tiempo; ¿te interesaría comprar una vieja?"',
    '7a8f68cf': '"Pásate alguna tarde y veré si la encuentro."',
    '21a923fa': '"Si cambias de idea..."',
    'b871ded9': '=',
    '33d60f50': '"¿Eso es algún tipo de pez?"',
  },
  // Eteocles, who runs the Ratcatchers' Guild, and talks like it
  '1838': {
    'e121b79a': 'Ves a un hombre medio calvo que necesita un afeitado, y quizá una buena noche de sueño.*',
    '9095e768': '"¿No ves que estoy comiendo?"',
    'c5bae1da': '"Pero por favor, señor, solo será un minuto, y seguro que puedo hacer que le merezca la pena..."*',
    '8e77db17': '"¿Qué te trae por aquí?"',
    'cc6506fe': '"Puedes llamarme Eteocles."',
    '65c11f70': '"Llevo el @Gremio de Rateros."',
    'd3bd4e45': '"Prestamos un servicio valioso a la ciudad, librándola de alimañas indeseadas."',
    '93479014': '"Sí, hemos oído hablar de esa cosa.  Sus efectos podrían ser muy útiles pa\' cazar \'ratas\' y tal."*"Pero parece que esa cosa crea adicción, y a la larga es mortal.  Mejor no meterse con ella."',
    '8e87f74e': '"Eres de lo más fisgón, ¿eh?"',
    'fb867430': '"Pero si ya eres miembro del Gremio."',
    '1fc88a55': '"No sé, no podemos dejar entrar en el Gremio a cualquiera."',
    '8b25cdcb': '"Tranquilo, Eteocles: yo respondo por esta persona."*',
    '1d80669e': '"Bueno, si Aethon dice que eres de fiar, a mí me vale."*"Pero primero está lo de la cuota.  Todos los miembros nuevos tienen que pagar una cuota de 50 óbolos."',
    '060b48ed': '"Bueno, ¿qué tal una donación de 40 óbolos?"',
    '9d18e91a': '"Me caes bien, así que esta es mi última oferta: una donación de 35 óbolos.  ¿Vale?"',
    'c5ce732e': '"Mira, 35 sigue siendo mi última oferta: ¿trato hecho?"',
    'dff0b524': '"Una donación de ', '81df3d93': ' óbolos es lo que te va a costar: ¿trato hecho?"',
    '2611a0f2': '"Lo siento: no se fía.  Solo dinero por adelantado."',
    'db39a552': '"¡Bienvenidos al Gremio!  Aquí tienes la llave honoraria de las alcantarillas"',
    '12932711': '*"Tenemos varias ventajas, como el derecho a @comprar ciertos artículos, y @entrenamiento \'especial\'."',
    'e555554a': '"Quizá deberías pensártelo mejor."',
    'c9af9adc': '"Aethon es uno de nuestros miembros con más talento."',
    'faffeef9': '"Lo siento, solo para miembros del Gremio: tienes que @unirte."',
    '514885d4': '"Ya sabes todo lo que tienes que saber."',
    '6ffe8c0a': '"Como miembro del Gremio, podemos enseñarte unas cuantas habilidades útiles."*',
    'd1f5f6f1': 'Abrir cerraduras', '4c1cf36a': 'Juego', 'e18b23ff': 'Detectar y quitar trampas', 'bfbb2deb': 'Robo',
    'd59e3d03': '=',
    'a92a2c08': '"Ni hablar, colega."',
    '73c345cf': '"Adiós."',
    '3e8ba4ab': '"Esto me tiene preocupado: no puedo creer que Halos lo hiciera."*"No tiene ningún sentido."',
    '518288f6': '"Sabía que era inocente: ojalá Berossus encuentre a ese cambiaformas, sea lo que sea."',
    '4c8204fb': '"Pasa, pero es bastante raro."',
    '530c47d5': '"Mmm, a lo mejor lo tiraron a las alcantarillas.  Deberías buscar a @Dryas: es una de mis mejores ratas de alcantarilla."*"Si llegó a las alcantarillas, él lo encontrará."',
    '80962539': '"He oído que nunca encontraron el arma del crimen."',
    '35c5cad4': '"Nunca llegaron a encontrarla, ¿verdad?"',
    'e7e5e7ce': '"Esto no es un sitio para conseguir armas."',
    'f514ade9': 'A Eteocles se le pone cara de desconcierto.*"Pues ahora que lo pienso, no lo he visto desde el asesinato.  Qué raro."',
    'bce07e04': '"Tiene un futuro brillante aquí."',
    '7a088f0d': '"No he oído hablar de ellos en mi vida."',
    'dce24da1': '"Es que no lo veo."',
    '3d0ec2f5': '"Sabía que era inocente."',
    'b177bc30': '"Es un comerciante honrado."',
    '6364a462': '"Ese es un nombre muy molesto en la historia del Gremio, te lo digo yo."*"Cualquiera pensaría que si alguien supiera dónde están sus escondites secretos, seríamos nosotros."*"Pero no es así, y eso es un insulto personal pa\'l Gremio."',
    'fac8680b': '"De ciertas cosas no hablamos con quien no es miembro."',
    'a0326e7b': 'Te mira con cara inexpresiva.',
  },
});
