Object.assign(DELV_TRANSLATION_ES.text, {
  '1839': {
    '6f91a9a4': 'Ves a un hombre llamativo, aunque de aspecto algo taimado.*',
    'f5d488e1': '¿Carne sabrosa?  ¡La he cazado yo mismo!', '45afaf60': 'Brochetas de carne', 'bd1a978d': 'Salchichas', 'cbaf343a': 'Asado',
    '241da125': '"Si buscas buena carne, pásate por mi puesto hacia mediodía."',
    '464b3cd7': '¡Brochetas calientes!',
  },
  '183A': {
    'fcc671f8': 'Ves a un hombre menudo, de aspecto vacilante.*',
    'ea28d5d8': '¿Un poco de fruta fresca?', '69e4ddb9': 'Uvas', '24a4b988': 'Granada',
    '225d0176': '"Por favor: ¡ahora no estoy abierto!"', '46fa9878': '¡Fruta fresca!',
  },
  // Autonous, the minter of Cademia
  '183B': {
    '3bff466e': 'Ves a un hombre poderoso, de aspecto estoico.*"¿Qué te trae por aquí?"',
    'bd9f32d5': '"Autonous."', '905b90ba': '"Soy el acuñador oficial de moneda."',
    'c65a3d39': '"He hecho hasta el último óbolo de los últimos doce años."',
    'f636d5a7': '"Doce años pueden parecerte mucho tiempo, pero cuento con seguir con esto dentro de otros doce."',
    '3648581a': '"Cojo hierro y lo forjo en óbolos."',
    '510557c8': '"Sí, tengo que arreglarlo un día de estos."',
    'ad8f0ecf': '"Me guardo mis opiniones."',
  },
  // Propontis, Elder of House Strymon, and his wife Mantinea
  '183C': {
    'be3d1e30': 'Ves a un hombre mayor que parece delirar.*',
    'fd5d4a3a': '"Mmmf, mmmrp, oooooh."',
    '67940958': 'Ves a un hombre mayor que parece algo débil.*',
    'c0039075': '"¡Ah, es quien nos curó!"',
    'c2620916': '"Disculpa, ¿no eres tú quien encontró la causa de la @plaga?"',
    '58486b98': '"Encantado de conocerte.', '1129b99a': '"Y encima con modestia.', '3d2f2c8b': '  Soy Propontis, Anciano de la Casa Strymon."',
    '81d572da': '*"La Casa Strymon está en @deuda contigo por lo que hiciste por nuestra ciudad."',
    '5960b83a': '"¡Adiós!"',
    '02f56cfd': '"Propontis, Anciano de la Casa Strymon, Casa gobernante de Catamarca."',
    '2c7ec5e1': '"Gobernar Catamarca es un trabajo a tiempo completo."',
    'bad5972a': '"¿Verdad que es una ciudad preciosa, sobre todo ahora que la @plaga se ha ido?"',
    '147f2412': '"La Casa Strymon está en deuda contigo.  Quizá podamos servirte en el futuro."',
    'b71b5d50': '"Halos es mi hermano menor.  Representa nuestros asuntos en @Cademia."',
    '9f4e2709': '"A mi hermano Halos le encantan las intrigas de Cademia, pero yo prefiero la vida tranquila de Catamarca."',
    '894d5f10': '"Mantinea es mi bella esposa: ¡llevamos 28 años casados!"',
    'cdba6d89': '"Aunque ya ha pasado, me preocupa que perdamos el apoyo popular."*"Pero ¿qué podíamos haber hecho?  ¿Cómo íbamos a saberlo?"*"¡Lástima que ese granuja de @Darius no cayera enfermo!"',
    '5888f629': '"Mi @esposa cree que trabajo demasiado, pero te juro que me mantiene joven."',
    '0b629315': '"Dice representar a la Casa @Comana aquí, en Catamarca, pero no me fío de él."',
    '836fce66': '"No hay que fiarse de la Casa Comana, si son ciertos los rumores que me llegan de @Halos."*"Quizá deberías buscarlo tú en persona, en Cademia."',
    'da7bf631': '"Sardis es un buen chico: Ake y Milcom lo educaron bien."',
    'b06b7740': '"Tendrás que buscar en otra parte."',
  },
  '183D': {
    '2c2b0c06': 'Ves a una mujer mayor y angustiada.*"¡No debe morir!"',
    '9c8a9d43': 'Ves a una mujer mayor y digna.',
    '4518f8cb': '"Soy la dama Mantinea, esposa de Propontis."',
    '76f65053': '"Ayudo a mi marido a gobernar Catamarca."',
    '54cd6af4': '"Propontis la contrajo al principio: es un milagro que sobreviviera."',
    'e95eac4b': '"Comparto la desconfianza de mi marido hacia la Casa Comana, sobre todo hacia @Darius."',
    'caec1049': '"Hay algo en él... no sé.  Y las @amistades que frecuenta..."',
    '14171131': '"Hay quien lo ha visto rondar en plena noche."*"Hace poco incluso lo vi reunirse con unos rufianes, aunque no pude oír lo que decían."',
    '2ffeda12': '"No acabo de seguirte..."',
    '7e9d04b0': '"Mi marido, Propontis, estuvo muy enfermo por la plaga, pero se recuperará bien, si descansara."*"Pero siempre parece estar @ocupado con algo."',
    '9b384e38': '"Llevar la Casa Strymon es un trabajo duro, sobre todo vigilando a Casas como @Nicander y @Comana."',
    '2ba9dec1': '"Halos es el hermano menor de Propontis: vive en Cademia, y tiene muchos recursos."',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys, { '183B': { mirr: 'espej', year: 'ano' }, '183C': { halo: 'halo', wife: 'espo,muje' }, '183D': { halo: 'halo', husb: 'mari,espo' } });
Object.assign(DELV_TRANSLATION_ES.keys['*'], { inno: 'inoc', poli: 'poli,asun', sent: 'envi', help: 'ayud' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Halos of House Strymon, in the Cademia jail and out of it
  '183E': {
    '2ee81b2b': '*"Pero ahora no es buen momento para hablar: por favor, pásate por mi despacho en horario de trabajo."*"Entonces podremos hablar con más libertad."',
    '1485aaa9': '*"Así que has venido hasta aquí para hablar de los @asuntos de la ciudad, ¿eh?"',
    'e54b68dc': ', ¡tienes que @ayudarme!  ¡Soy @inocente!"',
    'affc0795': '"El difunto Halos, si no puedes @ayudarme."',
    '055d0b0a': '"Tienes que demostrar que soy @inocente, aunque parece poco probable."',
    'a5e06592': '"Hasta que se demuestre mi inocencia, soy un prisionero."',
    'ca367803': '"Le he contado a @Berossus mi @historia, y dice que digo la verdad, pero él también me vio matar a @Opheltius, ¡y soy inocente!"',
    'a4d81e26': '"Él es el Juez, pero no sé cómo va a llegar a la verdad de este asunto."',
    '865f09b1': '"Nunca he tenido aprecio a @Opheltius, ni a nadie de la Casa @Nicander, ya puestos, pero no tengo ningún motivo real para matarlo."',
    '08cff5be': '"Soy amigo de la Casa @Attis, y la quiero como a una hija, eso es cierto, y juro que fue ella quien entró en mi tienda."',
    'd9e4e3e2': '"La Casa Strymon y la Casa Nicander nunca se han llevado bien, pero eso es política normal."',
    '8d81e0ba': '"La Casa Strymon y la Casa Attis no son aliadas en realidad: simplemente no estamos de acuerdo con su alianza con Nicander."*"Extraoficialmente, los considero amigos míos, pero ahora, quién sabe."',
    'e6feb537': '"Como le dije a @Berossus, estaba en mi tienda trabajando cuando entró @Cybele."*"Es lo último que recuerdo, hasta que desperté, en mi tienda, zarandeado por los guardias, y ahora estoy aquí dentro."*"Ya no sé qué pensar: claro, es posible que si @Cybele me hubiera dicho que Opheltius la había violado, me hubiera vuelto loco de furia."*"Hasta podría haberme enfadado lo bastante como para matarlo, pero ¿cómo podría haber borrado todo ese recuerdo?"*"Berossus sabe que digo la verdad: me puso a prueba.  Pero también me vio matar a Opheltius."*"Y Cybele dijo que nunca vino a mi tienda, y menos aún que me contara que Opheltius le hubiera hecho nada."*"Sencillamente, no lo entiendo."*',
    'ce558975': '"No te preocupes, viejo amigo.  ¡Llegaremos al fondo de esto!"*',
    'a70fb60b': '"Gracias, Aethon, eso significa mucho para mí ahora mismo."*',
    '5c5c1b63': '"Quizá deberíamos ver si alguien del Gremio sabe algo: quizá alguien haya encontrado el arma del crimen."*',
    'c51c8b6b': '"Excelente idea: bien podría demostrar mi inocencia."',
    'd6db0397': '"Quizá si apareciera el arma del crimen, podría demostrar mi inocencia."',
    'f396ea7e': '"Encontrar el arma del crimen puede ser la única manera de salvarme."',
    'c098f3ef': '"¡Por favor, descubre la verdad de lo que pasó!"',
    '050e598f': '"¿Podemos ceñirnos al problema que tenemos entre manos?"',
    '6a733a5b': '"Ah, ¿qué puedo hacer por ti?  ¿Hablar de los @asuntos de la ciudad?"',
    '8e2a1fba': '"Ahora mismo estoy muy ocupado, ¿podrías volver más tarde?"',
    '4138fba0': '*"Pero por favor, señor, esto es importante..."*',
    'f64fe9fd': '"Soy Halos"',
    '93f31bbe': '*"Déjame adivinar: te envía un amigo de un amigo..."',
    '8086f721': '"¿Quién te envía?"',
    '0e943861': '"Tengo muchos amigos, y muchos enemigos."',
    '0c8806cc': '"Desde luego no me llevo bien con la Casa Comana, pero ¿quién sí?"',
    'ac77a518': '"Represento los intereses de la Casa Strymon en Cademia."',
    '303bebfd': '"Por eso estoy en deuda contigo.  Aun así, la idea de un cambiaformas: nunca lo habría creído."',
    '07755b0a': '"No he oído nada de ninguno..."',
    '4ddc33ee': '"Sí, ya lo sé, te envía la dama Ake."',
    'a66815ea': '"¿Te envía la dama Ake?  Pues haberlo dicho antes..."',
    'bd01cfeb': '"Sí, ya lo sé, te envía mi hermano Propontis."',
    '29d2c10b': '"¿Te envía mi hermano Propontis?  Pues haberlo dicho antes..."',
    '24379083': '"Propontis es mi hermano mayor, en Catamarca."',
    'c706fbe5': '"Creo que te equivocas."',
    '71762b64': '"¿De qué nota se trata?"*Le enseñas a Halos la nota que encontraste en Eudoxus.*"Interesante, pero demuestra muy poco: ni siquiera dice a quién iba dirigida, salvo \'D\'."*"Aun así, esto es de lo más interesante: deja que me la quede y que investigue un poco..."*Halos se queda con la nota.',
    'efef1013': '"La política de Cademia es complicada, pero esta es la historia:"*"La Casa Attis ha perdido el apoyo popular, y hace poco Comana la ha superado por muy poco."*"Sin embargo, Attis, sumada a Strymon y a Nicander, pesa más que Comana."*"Claro que Strymon y Nicander no se llevan bien."*"Attis y Nicander, en cambio, son lo bastante aliadas como para impedir que Comana tome el control absoluto."',
    '7a6938ac': '*"Eso podría ayudar a explicar el secuestro de Nicander..."',
    '5ffe34f9': '"La política es un negocio sucio."',
    'dbe89ff5': '"No tengo pruebas, pero si me preguntas, están metidos en todo este sórdido asesinato."*"Ha sacado a Nicander de Cademia, ha debilitado a Attis, y casi ha agrandado la división entre la Casa Strymon y ellos."*"Quizá solo sea paranoia mía, pero conozco la política, y la Casa Comana habría salido ganando de todos modos si no hubieras encontrado a Dryas."',
    'a4ec5a99': '"Tengo motivos para creer que están metidos en el @secuestro de Ariadne."',
    '2470f222': '"Bien, esto es lo que he podido averiguar hasta ahora; ojo, todavía no puedo demostrar nada..."*"El bandido que secuestró a Ariadne de Odemia lo contrató la Casa Comana."*"Sus motivos no están claros, pero el rescate podría haber arruinado a la Casa Nicander."*"Derribar a Nicander dejaría Odemia libre para una nueva Casa gobernante."*"Y lo que es más importante, Nicander no tendría ningún poder aquí, en Cademia."',
    'c8e84133': '"Interesante: Mantinea me contó que vio a Darius hablando con unos rufianes, como ella los llamó."*',
    'd9e732fa': '"Eso parece confirmar la historia, ¿verdad?"*',
    'b2987729': '"Pero ¿no podemos hacer nada al respecto?"*',
    'fb9febf5': '"No, todavía no de manera formal.  Necesitamos pruebas definitivas antes de poder abrir una investigación formal."*"Aun así, quizá deberías hablar con @Berossus, nuestro Juez."*"Mejor todavía, busca a un amigo mío, @Aethon: quizá le interese unirse a ti en tu misión."',
    '47dd68e5': '"En eso no puedo ayudarte."',
    '547f1a0a': '"Aethon es muy astuto: se sabe que incluso acepta trabajos de @ratero."',
    '85f50e5f': '"He oído hablar de él: es mi oficio saber esas cosas."',
    '492a8808': '"En eso no puedo ayudarte."',
  },
});
