Object.assign(DELV_TRANSLATION_ES.text['*'], {
  '2ff671a9': '"Protejo a los ciudadanos de Catamarca."', '225d0176': '"Por favor: ¡ahora no estoy abierto!"',
  'b363f193': 'Manto', '3b4f789a': 'Capa', '6d980fdb': 'Daga', '9ee1c0bb': 'Hacha', 'c26c5edc': 'Espada corta',
  'eb82b1e9': 'Rodela', '2dce6a78': 'Escudo ligero', 'd6085f40': 'Casco', 'd8cb838b': 'Arco',
});
Object.assign(DELV_TRANSLATION_ES.text, {
  '1840': {
    '0ba00713': 'Ves a un hombre mayor, enjuto y fibroso.',
    '94c3886f': '*"¡Eh!  ¡Cuidado: tienes que tener más cuidado!"',
    'e1b8e99b': '"Soy Oeneus."', 'a043546e': '"¿Sí?  ¿Qué puedo hacer por ti?"',
    '41578096': '"Soy arquero y flechero.  ¿Te interesaría @comprar algo de mi trabajo?"',
    'db28955f': '¡Arcos y flechas hechos a mano!', '459b9d83': 'Flechas (12)',
    'bea8b034': '"Gracias..."',
  },
  // Periphas the baker
  '1841': {
    'b818fde7': 'Ves a un hombre neurótico, al parecer cubierto de harina.*',
    '89c07983': '"¿Te interesa pan recién hecho?  ¿Solo 3 óbolos?"',
    '70ca3772': 'Pan recién hecho', '18e89e7a': 'Hogaza de pan',
    '5f0f78fd': '"Quizá en otro momento, ¡pero ahora mismo está recién hecho!"',
    '75341c5a': '"En realidad, vengo a recoger un saco de harina para Apis."*',
    '19832356': '"Sí, claro: aquí tienes."*Te da un saco de harina',
    'e15517a9': '¡Pan recién hecho!',
  },
  '1842': {
    'b920b5ba': 'Ves a una mujer ruidosa, pero de aspecto agradable.*',
    '350b4ad5': '"¿Uno de los mejores quesos del mundo?  ¡Solo 6 óbolos!"',
    '3d28116a': 'Queso fino',
    'a6ab4b36': '"Quizá en otro momento: ¡no sabes lo que te pierdes!"',
    '91133911': '¡Queso fino!',
  },
  '1843': {
    'a2541147': 'Ves a un hombre menudo y reservado.*"Sí, ¿qué puedo hacer por ti?"',
    'd00c24be': '"Soy Hypsenor."',
    'be84fc49': '"Soy sastre: convierto la @tela en ropa sencilla.  ¿Quizá te interesaría @comprar algo?"',
    '3471da2a': '"Casi siempre la consigo aquí, aunque a veces me llega un envío de @Ake, de Odemia."',
    '34289aeb': '"Hace un trabajo muy bueno, aunque no hay mucha demanda de un material de su calidad."',
    '7b2dc412': 'Ropa bien confeccionada',
    '38b5c77c': '"Quizá deberías buscar en otra parte."',
  },
  // Thoas the blacksmith, and his son Dymas, who dreamt of the hero
  '1844': {
    '6cbb2882': 'Ves a un tipo fuerte, de aspecto amistoso, con una voz grave y retumbante.*"',
    '20b615bc': '"Me llamo Thoas, porque así me pusieron mis padres."',
    '211ceb82': '"Espero que el joven Dymas no te haya estado molestando.  Es un niño muy extravertido."',
    'e6400e3f': '"Lo siento, pero prefiero no hablar de eso..."',
    'da72b515': '"Está claro que no tienes muchas luces: estoy cubierto de sudor, trabajando junto a una fragua, ¿y no sabes a qué me dedico?"',
    'e4ef027e': '"Podría decirse que soy el mejor herrero de Cademia."',
    'c18ed55c': '*"Hago una gran variedad de artículos: ¿quizá quieras @comprar alguno?"',
    'c02e51a5': '¿El mejor trabajo en metal?',
    '0799b8ad': '"Adiós.  Vuelve cuando quieras."',
    '693bf43b': 'Te mira como si intentara decidir si te estás haciendo el listo o no.\n',
  },
  '1845': {
    '3299a683': 'Ves a un niño pequeño y extravertido.',
    'ea8d4a7f': '"Hola otra vez."',
    '518e0780': '"Hola.  Me llamo Dymas, ¿y tú?"',
    '602f873c': '"Encantado de verte @otra vez, ^',
    '0ae908f2': '"Ya te lo he dicho: me llamo Dymas."',
    '2fd40983': '"Oh, soy demasiado pequeño para trabajar, aunque a veces ayudo a mi @padre..."',
    '2c6716b7': '"Thoas el herrero es mi padre."',
    '605a564d': '"No me acuerdo de mi madre: mi padre dice que murió cuando nací."',
    'a356d37c': '"Ya te había visto una vez, pero fue en una @pesadilla, o eso creo..."',
    '51717e56': '"En la pesadilla estaba jugando cerca del agua, y salió de ella un monstruo."*"Luego pareció derretirse y convertirse en una persona, muy pulcra y ordenada."*"Le oí decir algo como \'¡No me detendrás!\', pero no me hablaba a mí."*"Le hablaba a un hombre de aspecto gracioso, con joroba, que estaba a mi lado."*"El hombre de aspecto gracioso dice: \'¡Yo no, pero ',
    'e92df9e1': 'ella', '5c3ae3b6': 'él',
    'ff1a6f50': ' sí!\'"*"Y entonces el aire como que brilla y apareces de repente: así es como te he reconocido."*"Y entonces me desperté: fue un poco raro."',
    '3b638475': '"¡Ahora te estás burlando de mí!  Eso no está nada bien..."',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys['*'], { immu: 'inmu', soot: 'sort,conj', spel: 'conj,hech', pris: 'pris,pres', ther: 'ther', saca: 'saca' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Sacas, the Judge of Odemia, and the kidnapping. "What can I do for you
  // this " + the program's word for the part of the day + "?": that word is
  // to be the whole greeting in Spanish, so the greeting comes first and the
  // question after it, in the '?"' this resource has once.
  '1846': {
    '0bf5e85d': '"Así que eres quien Alaric dijo que vendría: ',
    '76d33e07': 'aunque esperaba algo mejor."*"',
    '334cb72f': '¡y encima has rescatado a la dama Ariadne!"*"Eligió bien.  ',
    'c7fd3475': 'Me llamo Sacas: soy la Jueza de Odemia."',
    'a23890e2': 'Secuestro',
    '530f0e6c': '"¿Has sacado algo útil del prisionero?"',
    'a33ed766': '"Dice que trabajaba para un \'grupo\' de gente más poderosa que Nicander."*',
    '61410617': '"Mmm, podría referirse a otra Casa.  Tanto @Comana como @Strymon son bastante poderosas..."*"O quizá se refiera a otra cosa: ¿quizá a alguna organización secreta?"*"En cualquier caso, lo has hecho bien: yo no conseguí sacarle nada, lo cual es raro, teniendo en cuenta..."*',
    '93c34227': '"¿Teniendo en cuenta?"*',
    'f9ada42e': '"Bueno, como Jueza, tengo el poder de desentrañar secretos como este por medios místicos..."*"Era como si fuera inmune a mis conjuros de la verdad.  De lo más raro."*Mira a su alrededor un momento, como si consultara con su conciencia.*"Seguramente no debería contarte esto, porque podría causar muchísimos problemas si se sabe..."*"Pero cuando lo capturamos, llevaba un frasco de un líquido plateado al que llamaba \'kesh\'."*"Creemos que puede tener que ver con la inmunidad, pero no estamos seguros.  Lo único que sabemos es que es peligroso."*"Las investigaciones han mostrado que crea adicción, y que a la larga probablemente es mortal; aparte de eso, no sabemos mucho."*"Si pudiéramos averiguar de dónde viene, o siquiera de qué está hecho, podría ser una pista importante."',
    'b69ca4e1': '"Yo ya he visto esa cosa."*',
    '64b956e8': '"¿De verdad?  ¿Dónde?  ¿Cuándo?"*',
    '1c34431d': '"Había en un cuerpo que encontré aplastado en un túnel de la Sala del Rey de la Tierra."*"No sé quién era: ¡podría haber sido un espía!"*"También encontré más en el propio jefe de los bandidos."',
    'f38ca1fd': '"Había en un cuerpo que encontré aplastado en un túnel de la Sala del Rey de la Tierra."*"No sé quién era: ¡podría haber sido un espía!"',
    '66bf8072': '"Encontré algo en el propio jefe de la banda."',
    'b72f4bec': '"¿Un espía?  ¿En la Sala del Rey de la Tierra?  Es inaudito.  Haré que Lindus lo investigue de inmediato."',
    '0527b920': '"No me sorprende, pero me pregunto de dónde lo sacaría.  Gracias por la información, de todos modos."',
    '19eccd9c': '"¿Y qué has averiguado?"',
    '8a781f68': '"Ya veo; quizá te sobrestimé..."',
    'a3baca22': '"Mmm, esperaba que encontraras algo"*"Quizá deberías preguntarle concretamente por el secuestro: quizá se le escape algo..."',
    'd907cc49': '"Hablar con el prisionero sería útil..."',
    '420f7943': '"', '0dfa1ec4': ', ¿qué puedo hacer por ti?"',
    '3b3a1026': '"Me llamo Sacas, ¿recuerdas?"',
    'd6611e97': '"De momento, soy la @Jueza de Odemia."',
    '4936fc15': '"Bueno, ser Jueza tiene sus ventajas, y muchos @deberes; investigar @delitos no es lo mío."',
    '6e7c11c0': '"Como el secuestro de Ariadne.', 'b72926b4': '  Tú tanto como yo.', 'afddb3bf': '  Quizá tú descubras algo.',
    '6083e880': '"Ese secuestro me tiene preocupada: el @prisionero que capturamos parece @inmune a mis @sortilegios de la verdad."',
    '01443061': '"Como Jueza, tengo el poder de desentrañar secretos por medios místicos."',
    'c40bef17': '"No sabemos nada más de lo que ya te he contado."*"¿Has descubierto algo más?"*',
    '1c24f1b2': '"Sí.  Había una banda de bandidos cerca de la Gran Ciénaga con una gran reserva."*',
    'b9f57233': '"No me extrañaría que esa fuera su base.  Si pudiéramos averiguar quién se la suministraba..."',
    '68eea06d': '"Pero hay más..."*',
    'd827a4fc': '"Bajo Kosha hay una gruta, con cajas llenas de esa cosa."',
    'cd3e0cdc': '*"Hasta la he fabricado yo, con un báculo extraño y huevos de arpía."',
    'c4d68934': '"Vaya, fascinante.  Parece que la Casa Comana era la fuente del kesh."*"Aunque, por desgracia, fabricar kesh no era ilegal según ninguna ley vigente."*"Y por desgracia, por los efectos del kesh, no podemos vincular legalmente a la Casa Comana con ningún acto de los bandidos."*"Tenemos que destruir esta cosa, como sea..."',
    '52235e9c': '"No, señora, pero estaré atento..."*',
    '9f8e1d67': '"Bueno, de acuerdo, sigue con ello, entonces."',
    '86c4b1f2': '"La verdad es que no sabemos cómo podría interferir el kesh con nuestros conjuros, pero es una posibilidad clara."',
    'cbd88475': '"Sigo sin entender cómo podían fallar mis conjuros."',
    'de4c86f3': '"Es extraño que pueda resistir los conjuros, y seguro que no va a hablar con @Thersites."*"¿Quizá podrías ayudar?  Seguro que sabe que ',
    '249e6a55': 'no ', 'ed471ff3': 'rescataste a Ariadne: ¿quizá se le escape algo si hablas con él?"',
    'ed54c46b': '"¿Thersites?"*', '8e1cf98a': '"¿Sí, señora?"*',
    '78f5ead6': '"¿Podrías darle una llave del calabozo a ', '6247b91b': '', '935e6950': 'esta noble persona?"*',
    'd3c8e2c8': '"A sus órdenes."*',
    '0988a02e': '"Mira a ver qué averiguas, y vuelve a informarme."',
    '5d3dbb8f': '"¡Excelente!  Dile a @Thersites que te dé la llave del @calabozo, y mira a ver qué encuentras; luego vuelve a informarme."',
    '817182c8': '*"Quizá también te convenga preguntar por el pueblo, a ver si alguien más sabe algo del secuestro."',
    '25f51f4b': '"Lo entiendo: tienes cosas que hacer.  Pero si cambias de idea..."',
    '0fd8d9d6': '"Thersites es el Capitán de la Guardia: lo encontrarás o en sus aposentos de la torre sudoeste, o recorriendo el pueblo."',
    '2c24e11c': '"Supongo que te has enterado: ha muerto.  Seguramente deberías pedirle los detalles a Thersites."',
    '81ff333e': '"Tenemos en el calabozo a uno de los secuestradores de Ariadne."',
    '2d9ea8db': '*"Para llegar tendrás que pasar por los aposentos de @Thersites hasta la muralla: está en la esquina sudeste del pueblo..."',
    'a1b8981f': '"Recuerda que Thersites puede darte la llave de la prisión"',
    '6c67f761': '"Gracias otra vez por tu ayuda..."',
    '566bca5e': '"La Casa Comana es una Casa relativamente advenediza.  Empezaron en el pueblecito de Kosha."*"Hace unos tres años murió Canachus, el Anciano de la Casa, y Myus tomó el poder, y ahora intentan hacerse con el control de Cademia"',
    'e6267235': '"Strymon es una de las Casas más antiguas.  Tiene la envidiable posición del poder en Catamarca: es la principal rival de Nicander."',
    '4af4c7f5': '"Nicander es la Casa gobernante aquí, en Odemia.  El Anciano Philinus es bastante agradable, y ya conoces a su mujer, Ariadne."*"Su hijo menor, Ascalon, bueno, digamos que me alegro de que herede su hermano mayor, Opheltius."',
    'f617f372': '"Si me preguntas, ¡es un mocoso mimado y corto de luces, eso es lo que es!"*',
    '94772acd': '"Por favor, Peirithous, sé educado."*',
    '8fc96f2c': '"Muy bien, señora.  Perdón por interrumpir."*',
    'e298eddd': '"Lo siento: en eso no puedo ayudarte."',
    '905a2ef8': '"Vuelve más tarde, por favor"',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys['*'], { free: 'libr,mago', mast: 'maes', key: 'llav', lock: 'cerr', spri: 'mana,fuen', wate: 'agua', sapp: 'zafi', meto: 'meto', poly: 'poly', lind: 'lind' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Metopes, the Judge of Catamarca, and the plague
  '1847': {
    '9d9a476a': '"No sé qué has hecho, pero todo el mundo dice que de repente se siente mejor."*',
    'b87a81b7': '"Bueno, encontré un extraño cristal verde luminoso en el manantial subterráneo."*"Al cogerlo, me invadió un malestar que luego se fue tan de repente como vino."*',
    '162e8780': '"Mmm, curioso.  Recuerdo vagamente haber oído hablar de un cristal verde luminoso en mis tiempos en el Magisterium."*"Sí, ahora me acuerdo: se encontró en las ruinas de las afueras de Pnyx, el mismo sitio donde, según la leyenda, los @Metecos se aparecieron a mis antepasados."*"Yo lo llevaría a Pnyx para enseñárselo al director Lindus.  Quizá tenga más pistas sobre su origen y su poder."*',
    'a307c679': '"También había unos extraños monstruos con tentáculos que parecían proteger el manantial."*',
    '1e02d42c': '"¿Con forma de barril?  ¿Con tentáculos en lo alto?"*',
    '7b14bfdd': '"Sí, esos mismos."*',
    '7cc455d4': '"Había oído hablar de ellos, ¡pero no me imaginaba que pudiera haberlos en una cueva justo debajo de mi cama!"*"Se llaman pólipos.  Creo que de algún modo están emparentados con los monstruos marinos que hay frente a la costa."*',
    '032e4fee': '"Ah, debes de ser quien envió Alaric para investigar el asunto."*"Bueno, te diré que esta @plaga nos tiene a todos desconcertados.  Casi todo el mundo la ha cogido en mayor o menor medida"',
    'add1b2ba': '*"Yo he tenido suerte: todavía puedo valerme.  Otros han muerto."*"Por favor, echa un vistazo: estoy a tu disposición."',
    'e771085f': '"Hola otra vez.  ', 'e0db3dc3': '¿Has avanzado algo con la plaga?"', '682430ad': '¿Qué te trae por aquí?"',
    '16823533': '"Oh, ¿se me olvidó decírtelo?  Me llamo Metopes."',
    '6674420a': '"Soy el @Juez de @Catamarca."',
    '546350bd': '"Polydamas es el fiel mayordomo de la Ciudadela."',
    '200900fa': '"Lindus es el Director del Magisterium.  Aprendí mucho de él."',
    '842b7e0f': '"La Casa Strymon es ahora la Casa gobernante de Catamarca', '5b4b40f4': ', pero la plaga está desgastando su popularidad, por decirlo suavemente."',
    '481fe8e0': '"Un juez es un mago que cumple un @deber cívico resolviendo disputas y cosas así."*"Algún día quizá vuelva a @Pnyx para hacerme @Mago Libre, pero me gusta ser Juez."',
    '8e3f4e00': '"Catamarca era una tranquila villa de recreo, famosa por su @agua, hasta que empezó la @plaga."',
    'f67ec915': '"Catamarca vuelve a ser una tranquila villa de recreo, ahora que se ha resuelto lo de la plaga"',
    '6acaceed': '"Hacerme Mago Libre es el siguiente paso si quiero llegar a @Maestro, pero no sé si estoy preparado para eso."*"Sobre todo la parte de tener que vivir como un ermitaño..."',
    'c1b5c23c': '"Ser Maestro es un sueño que no sé si tengo..."',
    '72bbf991': '"Pnyx es la sede del Magisterium, donde se forman todos los magos."',
    'a2438612': '"Todo empezó hace cosa de un mes.  Creímos que era solo una gripe, porque esos eran los primeros síntomas."*"Por desgracia, todo el que la coge no hace más que empeorar."*"Ha muerto bastante gente."',
    '27380e59': '"Sigo sin saber qué tenía que ver ese cristal ni cómo funcionaba, pero funcionó."',
    'd69270a3': '"Bueno, cuando empecé en este trabajo me dieron una llave ceremonial de la @Ciudadela.  Creo que está en un cajón de mi escritorio..."',
    '31f7c6db': '"Catamarca es famosa por la calidad de su agua, que viene de un manantial bajo la ciudad"',
    '16d6f7f5': '"Adiós"',
    '0c0fecb2': '"La Ciudadela es esta fortaleza, que en tiempos se construyó con fines militares."',
    '80224f59': '"Los Metecos son una raza legendaria de criaturas que supuestamente vivían aquí antes que nosotros."*"Claro que he visto las ruinas de las afueras de Pnyx, y no hay rastro de sus constructores."*"Quizá, después de todo, haya algo de verdad en las viejas leyendas..."',
    '1ead5243': '"He oído hablar de los Libros de Zafiro, pero nunca los he visto: supongo que el bibliotecario Selinus sabrá más..."',
    'c73f0148': '"Mmm, me temo que en eso no puedo ayudarte."',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys['*'], { sten: 'sten', pela: 'pela', cybe: 'cybe', halo: 'halo', ophe: 'ophe', bero: 'bero' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Berossus, the Judge of Cademia, and the hearing of Dryas
  '1848': {
    'd1c16cdd': '"Te escucho."*',
    '670cabf0': '"Stentor asegura haber visto a Pelagon en Cademia justo antes del asesinato de Opheltius."*',
    '69cf7958': '"¡Ya basta!  ¡No voy a quedarme de brazos cruzados mientras un borracho calumnia a un criado de confianza!"*',
    '4b51f26d': '"¡Ya está bien, Naxos!"',
    'db54d77c': '"Muy interesante.  ¿De verdad vio a Pelagon, o fue solo su locura?"',
    '64ff499b': '*"Si Stentor estuviera en su sano juicio, sería otra cosa, pero por desgracia..."',
    '5b47ce0d': 'Ves a un hombre mayor en baja forma, que parece faltarle el aliento.*',
    '008e1dac': '"¿Vienes a hablarme del @asesinato de @Opheltius?"',
    'c584a37c': '"Sí, Señoría, y he traído un testigo."*',
    'ae89e463': '"¿Un testigo?  ¿Ese golfillo de ahí?"*',
    'bbc6f047': '"Sí, Señoría.  Soy Dryas: trabajo para el Gremio de Rateros, y vi algo que demuestra que Halos es inocente."*',
    'b3c6686a': '"Mmm, muy interesante.  Continúa."*',
    'b1b062c2': '"Señoría, con todos los respetos, pero no es más que un niño.  ¿De verdad puede fiarse de su testimonio?  ¡Es una rata de alcantarilla del Gremio de Rateros!"*',
    'a71566bb': '"Naxos, ¿dudas de mi juicio o de mis capacidades?  La Verdad no conoce edad ni oficio.  Lo escucharemos."*',
    '2f2ca145': '"Sí, Señoría.  Lo siento."*',
    '34e0bcbe': '"Continúa, por favor."*',
    '30c26fdc': '"Bueno, iba a ver a Halos por asuntos del Gremio, cuando vi a Cybele entrar en su tienda: ella no me vio."*"La vi mover la mano y Halos se desplomó, como si se hubiera desmayado o algo así."*"Puede parecer difícil de creer, pero luego Cybele como que vaciló y de repente era Halso."*"Había dos allí.  El Halos falso sale entonces de la tienda: supongo que para ir a matar a Opheltius."*',
    '2ea9eea5': '"¡Eso es increíble!"*',
    '2c815a3e': '"¡Naxos!  ¡Ya basta!"*',
    'adabb6a3': '"Bien, jovencito, dices la Verdad, al menos hasta donde la conoces.  Te dejas algunos detalles menores que no vienen al caso, pero dices la verdad."*"Nunca había visto nada igual, pero, como todas las partes implicadas han dicho la verdad, tenemos dos opciones."*"O alguien miente, lo cual va contra la esencia misma de nuestro sistema judicial, y es muy inquietante."*"O, igual de inquietante, algo con el poder de cambiar de forma mató a Opheltius e intentó incriminar a Halos."*"Por todas nuestras leyes y nuestro honor, debemos dictaminar que se da el segundo caso.  Halos debe quedar libre."*',
    '7dd83e81': '"¡Un cambiaformas!  ¡Eso es ridículo!"*',
    '933a094d': '"No, Naxos, no es ridículo, sino muy inquietante.  Aun así, ese es mi fallo."*',
    '71fe22f6': '"Gracias, jovencito.  Con tu testimonio, Halos queda libre."*',
    'd5ef0f09': '"Sí, y ahora volveré al Gremio."',
    '1bf2a031': '"Te daría las gracias por resolver este asunto, pero en verdad el resultado me preocupa sobremanera."*"Un cambiaformas: ¿es un solo ser, o quizá toda una raza que camina sin que la conozcamos entre nosotros?"*',
    '142788e1': '"Stentor, antiguo mayordomo de Itanos, asegura que algo tomó la forma de su antiguo amigo, Pelagon."*',
    'a3a2ffb7': '"¡Ese borracho!  Conozco a Pelagon de toda la vida, ¡y no es ningún cambiaformas!  Por favor, Señoría, ¡ya basta!"*',
    '9b915791': '"Bueno, Naxos, te concedo que parece traído por los pelos, como poco."*"Quizá deberías buscar a Stentor y ver si se puede averiguar algo más de este asunto."',
    '06d8fca5': '"Había oído que era una especie de locura o de borrachera.  Sea como sea, sin embargo..."*"Quizá valga la pena buscar a ese Stentor, y ver si puedes averiguar algo más de este asunto."',
    '21f3a2ff': '*"Parece bastante improbable que los desvaríos de un loco tengan algo que ver con la situación actual."*"Aun así, hay que investigar todas las pistas.  Tengo las manos llenas con lo que está pasando: ¿hablarías tú con Stentor?"*',
    '10e6da7b': '"En realidad, ya lo he hecho, mi señor.  Y no se va a creer lo que me contó."*',
    '498f8f53': '"Por supuesto, mi señor."*',
    '894b54d5': '"Bien: vuelve a informarme cuando sepas más..."',
    'caddfe1e': '"¿Has hablado con ese Stentor?"*',
    'ba0895f0': '"Sí, mi señor.  Y no se va a creer lo que me contó."*',
    '46b2e87e': '"Soy Berossus."',
    '547d9948': '"Sí, ¿decías?"',
    '01c3c21e': '"Me ha tocado el desafortunado trabajo de intentar ser el @Juez de Cademia."',
    'f9ea0cb1': '"Ser el Juez no solía ser un problema, pese a nuestros muchos @deberes, pero últimamente..."',
    '4dcccddf': '"Este crimen me desconcierta: con mis propios ojos vi a @Halos matar a @Opheltius."*"Irrumpió en el Consejo gritando que Opheltius había violado a @Cybele."*"Lo siguiente que sé es que apuñala a Opheltius y consigue escapar en medio de la confusión."*"Opheltius murió, pese a mis intentos de curarlo."*"Encontramos a @Halos en su despacho, al parecer dormido."*"Pero cuando lo interrogué, no recordaba nada de eso, y el Conjuro de la Verdad dice que es sincero."*"Tampoco encontramos nunca el @arma del crimen, así que con eso no podemos hacer nada."*"Y para colmo, Cybele está bien: nunca fue a contarle nada, y desde luego Opheltius no la violó."*"No me imagino a Cybele haciendo nada para incriminar o dañar a la Casa Nicander: son aliados."*"Y en cuanto a Halos, es un viejo amigo de su familia.  No tiene ningún sentido."*"Todos lo vimos matar a Opheltius, pero toda mi formación también me dice que dice la verdad."*"¿No puedo fiarme de mis propios ojos?  ¿No puedo fiarme de mi formación?  Es una situación sin salida."',
    'd97ef1ca': '"Lo siento."',
    '4e2dd07f': '"Creo que era el mayordomo de Itanos: ahora vive en algún lugar de Cademia."*"Es una historia triste, pero son cosas que pasan cuando uno bebe demasiado."',
    '6a829f32': '"No sé qué pensar de él: puede que esté loco, pero puede que haya dado con algo."*"Aun así, Pelagon está por encima de toda sospecha."',
    '95f590a0': '"Creo que es el mayordomo de la Casa Comana."',
    '3fd4e132': '"Bueno, digan lo que digan las afirmaciones de Stentor, sigue estando por encima de toda sospecha."',
    'e673eb35': '"Puede que Halos sea un poco pícaro, pero no es de los que asesinan."',
    '7e73297d': '"Quizá si encontráramos el arma del crimen, podría discernirse algo de verdad."',
    '7f7ab2be': '"Lo siento: no entiendo mucho de armas."',
    '875d09a3': '"Cybele es una buena chica.  Cuesta creer que esté metida en esto de algún modo."',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys['*'], { righ: 'bien,raro', wron: 'mal', wisd: 'sabi', cana: 'cana', itan: 'itan', idom: 'idom', prus: 'prus' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Itanos, the Judge of Kosha
  '1849': {
    'b91b436b': 'Ves a un hombre desordenado.',
    '18b11bee': '"Soy Itanos."', '7070dece': '"¿Sí?  Soy Itanos."',
    '201ba8f3': '"Soy el Juez de Kosha, para lo poco que sirve."*"No han hecho falta mis @servicios desde que murió @Canachus hace tres años."',
    '17729a80': '"El Mago Libre Idomeneus estuvo aquí hace un par de meses: dijo que iba a seguir el mar."*"Tenía una teoría extraña sobre el tiempo y el mar; no la recuerdo exactamente."*"Se fue hacia el sur, diciendo algo de \'donde la tierra se encuentra con el mar\'."',
    '377275e5': '"Canachus era un buen hombre, y sus hijos parecen haber heredado ese rasgo, pero algo..."*"No sé, supongo que estoy divagando.  El caso es que Canachus murió hace tres años."*"Lo investigué, y pareció de causas naturales.  Aun así, algo no acababa de estar @bien."',
    '8b061100': '"En apariencia, las cosas nunca han ido mejor en Kosha, pero..."*"No sé, algo no parece estar bien, como una especie de fachada hueca."*"Quizá @Stentor hizo bien en irse, y @Prusa..."',
    '5c8876c6': '"@Stentor era mi mayordomo.  Dejó Kosha y se fue a Cademia hace unos cuatro años."*"Dijo algo de que temía a la muerte; nunca logré sacarle una respuesta clara."*"Qué extraño, teniendo en cuenta mi formación.  Era como si un miedo profundo y primitivo se hubiera adueñado de su alma."*"Si alguna vez llegas a Cademia, deberías preguntárselo tú, y decirle que le deseo lo mejor."',
    '77737cdb': '*"Llevo tiempo queriendo ir a verle, pero nunca encuentro el momento."*"Se dejó una de sus redes de pesca: ¿podrías llevársela de mi parte?"',
    'b66c2a52': '"Excelente: aquí tienes.  Gracias."',
    '37a0ddb6': '"Bueno, ya lo haré un día de estos; seguro que de todos modos se ha comprado una nueva."',
    'fdae1a0b': '"Prusa era una Maga Libre que vivía aquí, en Kosha: estaba bien tener aquí a otra Maga."*"El caso es que estudiaba las visiones, la adivinación y una especie de \'visión verdadera\', como ella la llamaba."*"Todavía recuerdo cuando me despertó aquella noche.  Fue poco después de que Stentor se fuera a Cademia, y entró de golpe."*"Por sus ojos supe que algo iba mal, muy mal.  Repetía lo mismo una y otra vez."*"Algo de que el mar venía a por ella; no tenía mucho sentido.  El caso es que entonces dejó Kosha."*"Lo último que supe es que vivía en algún lugar cerca del nacimiento del río Styx, al noroeste de aquí."*"Dicen que ha perdido el contacto con la realidad, pero la gente va a buscarla de vez en cuando por una especie de sabiduría divina o algo así."*"Quizá deberías buscarla..."',
    '163020a5': '"Me avergüenza reconocer que me llevé uno de los Libros de Zafiro de la Sabiduría de la Biblioteca de Pnyx."*"Te lo daré para que lo devuelvas si me prometes no decírselo a Selinus..."*',
    '35c44e5c': 'Rebusca un minuto en la librería de al lado.*"¡Ah!  Aquí está.  Mmm, \'El Libro de Zafiro de la Misericordia\'.  Nunca le saqué mucho, pero aquí tienes."*Te da el libro.',
    '9fb9aab6': '"Pásate esta tarde, cuando esté trabajando en mi estudio: veré si puedo encontrártelo..."',
    '81675b27': '"Lo siento, solo tenía ese libro: no sé dónde están los demás..."',
    '086d936e': '"Quizá podría investigarlo..."',
  },
});
// The spells' names as the menus and the scrolls give them.
Object.assign(DELV_TRANSLATION_ES.text['*'], {
  'eeb09d5d': 'Curación', '2fa62ca8': 'Sueño', '4d6ae227': 'Miedo', 'df93f197': 'Arenga', 'cb3dfb4d': 'Flecha mística',
  'edff205d': 'Parálisis', '80f45ccb': 'Confusión', '9f9ee23a': 'Nutriente', 'bd4fd7ec': '"Cuando quieras."',
});
Object.assign(DELV_TRANSLATION_ES.keys['*'], { head: 'naci', ruin: 'ruin', swam: 'cien,mari', khal: 'khal', lari: 'lari', glow: 'lumi,bril', crol: 'crol', timo: 'timo' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Timon, the Freemage who studies the Seldane, and a companion
  '184A': {
    '7f76945a': '¿Qué conjuro lanzo?',
    'ca2b041d': '"Es una especie de cristal triangular luminoso.',
    '48de724d': '"Es una especie de cristal triangular luminoso, hecho a todas luces de varias piezas unidas para formar algo más poderoso.',
    'f38b77b6': '"Parece un fragmento de un objeto mayor.',
    'de334ffa': '  Su naturaleza exacta es un misterio para mí, pero debe de tener algo que ver con los Metecos."',
    '01e64b04': ' se usa para hacer ',
    '00f75ab1': '"Yo diría que es ',
    '24b18311': '"Disculpa, pero si tienes un minuto: te estarás preguntando por qué le mentí a mi hermana ahí atrás..."*',
    '6a007800': '"Sí, me extrañó un poco."*',
    '8c2d56dc': '"Tenía muchas ganas de contarle lo que hemos estado haciendo, ',
    '8a3c7a07': 'sobre todo lo de conocer a un Seldane de verdad', '9eea4416': 'con lo del cristal y todo',
    '9210ffbc': ', pero es mejor esperar a que estemos todos a salvo."*"Es mi hermana, al fin y al cabo, y no querría meterla en nada peligroso."*"Más que eso, ya que al fin y al cabo es evidente que sabe arreglárselas en esta ciénaga y todo, está su ayudante, Joppa."*"Nunca me ha caído bien: me da mala espina, y sencillamente no me fío de él."*"Espero que lo entiendas, aunque puede que Larisa no me perdone tan fácilmente."',
    '2d30e762': '"Por favor, estoy muy ocupado y no estoy de humor para hablar con gente que no conozco.  Vete."',
    '63f7bc09': '"Ah, ¡debes de ser la persona que envió Lindus!  Soy Timon"',
    '75b3e4bf': '"Qué raro, me dijeron que tendrías un @cristal verde luminoso"*"Quizá no seas a quien esperaba..."',
    'b1c80554': '"¿Puedo ver el cristal verde luminoso?"*',
    '23b0c456': '"Sí, supongo..."*',
    'b85e7e50': '"Mmm, sí, desde luego.  De lo más interesante.  Se parece mucho al que encontré yo, solo que más pequeño."*"¿De dónde lo has sacado?"*',
    '79ade25d': '"Estaba en un manantial bajo la Ciudadela de Catamarca.  Creo que tenía que ver con una enfermedad como una plaga que había azotado la ciudad."*',
    '4663f219': '"Vaya, qué fascinante.  Este lo encontré enterrado en las ruinas de aquí.  Quizá haya alguna relación."*"Mmm...."*"Bueno, toma, deja que te los dé.  Quizá tú puedas avanzar algo."',
    'f2072a8e': '"¿Qué puedo hacer por ti?"',
    '4f952490': '"Soy Timon, un @Mago Libre."',
    'ac0c1ea6': '"Soy un Mago Libre, alguien que pasa el tiempo aprendiendo para prepararse para llegar a @Maestro."',
    'b87ebc7f': '"¡Sí, es un honor acompañarte en tus aventuras!"',
    '2aea49ac': '"Bueno, como Mago Libre, debería pasar el tiempo aprendiendo, pero a decir verdad, y Lindus puede confirmarlo, sin duda aprenderé mucho yendo contigo."*"Tengo la sensación de que al menos podrás desentrañar para qué sirven los cristales, lo cual me interesa muchísimo."*"¡Será un honor unirme a tu misión!"',
    'bfb17b90': '"Muy bien, si crees que es lo mejor, pero creo que todavía puedo aprender mucho, y serte de mucha ayuda..."',
    '1052f1d6': '"No hace falta ser grosero."',
    'b7d83178': '"Algún día espero llegar a Maestro, y mis investigaciones sobre el @Meteco son mi especialidad."',
    '36c9ef95': '"Bueno, la verdad es que ese es un tema interesante.  Mi campo de investigación, ¿sabes?"*"\'Meteco\' es en realidad un nombre que les hemos puesto nosotros: ellos se llaman a sí mismos @Seldane."*"Hay quien dice que son un mito, o que se extinguieron, pero ninguna de las dos cosas es cierta, ¿sabes?"*',
    '5b1346dc': '"Claro que eso ya lo sabéis todos, los hemos conocido, ¿verdad?..."',
    'bdf88edd': '"Me gustaría mucho encontrarlos algún día, y hablar con ellos.  De lo más fascinante."*"El caso es que hay al menos dos grupos de @ruinas hechas por ellos.  He estado estudiando lo que yo llamo \'@Nacimiento\'"',
    'fa3f28b1': '"\'Nacimiento\' es el nombre que doy a las ruinas seldane del nacimiento del río Tirynth"',
    '044bbb2d': '"Bueno, están las ruinas del \'@Nacimiento\', y un grupo recién descubierto en la Ciénaga de @Khalkis"',
    'c11f9abc': '"@Larisa encontró un grupo de ruinas en la Ciénaga de Khalkis, al oeste de @Kosha"',
    '86033028': '"Larisa es exploradora.  Además es mi hermana, por cierto, lo cual hace bastante irónico que encontrara unas ruinas seldane."',
    '9e12c3a4': '"Kosha es mi ciudad natal.  Era una ciudad agradable hasta que la Casa @Comana subió al poder."',
    '56ea5c3e': '"La Casa Comana... hay algo en esos tres hermanos que me inquieta."*"Eran una Casa menor hasta que murió su padre, y entonces @Myus, @Naxos y @Darius tomaron el control."',
    'e3e25f7c': '"Myus es el jefe de la Casa Comana, por ser el hermano mayor.  Gobierna @Kosha."',
    'f96e97fc': '"Naxos es el mediano.  Lo último que supe es que andaba causando problemas en Cademia."',
    '572e475e': '"Darius es el menor.  Vive en Catamarca: ¿quizá lo conoces?"',
    '7e82a073': '"Está claro que son mágicos, pero para qué sirven, no lo sé."',
    'e2fab0d9': '"No sé mucho de eso; quizá pueda investigarlo."',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys, { '184A': { myus: 'myus', naxo: 'naxo', dari: 'dari' } });
Object.assign(DELV_TRANSLATION_ES.keys['*'], { succ: 'logr,exit', tune: 'tona,melo,cancion' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Prusa, the Freemage driven mad by a vision of the sea
  '184B': {
    '17050cfe': 'Ves a una anciana de pelo revuelto, con la locura en los ojos.*',
    '960f6bed': '"Sí, ¿vienes a aprender?  ¿Quizá a enseñar?  Pero el mundo que te enviaron a alcanzar ya no tiene futuro."*',
    '72db7164': '"Hay dos enemigos: la Tierra y el Mar.  El Mar nos destruiría, la Tierra nos dejaría ahogarnos."',
    '385b1157': '"Los poderes de los elementos pueden manifestarse en seres de poder: esos seres caminan entre nosotros, sin que se les vea."',
    '991ff2ba': '"Verde y luminosa, es una herramienta que puede doblegar y sostener: imponer poderes, y también enderezar."',
    '7db1654d': '"El Lazo de la Tierra deriva de los Poderes de la Tierra, pero está más allá de los poderes de un mortal."',
    'a1a5ed4d': '"El Mar me llama, la Tierra me llama.  Entre esos dos extremos me veo arrastrada."',
    '5c2a55f1': '"¿Por qué nos trajeron aquí?  ¿Para ser peones, para hacer avanzar a un bando o al otro?  ¿O para quedar fuera del juego, quizá incluso para acabarlo?"',
    '51d282e9': '"¿Has oído hablar de una palabra que nos impida equivocarnos?  El momento es ahora."*',
    '7e972253': '"La verdad no es absoluta, pues, como la belleza, está en los ojos de quien mira."',
    '149243cf': '"El aceite y el vino no se mezclan con facilidad, y se separan si no se les une."',
    'bee11c4b': '"Los que no son humanos no tienen los valores de los humanos."',
    'a518dab8': '"Para un roble poderoso, un solo insecto no existe."',
    '4fc0ba8c': '"Aceptar como iguales lo que es cierto y lo que es falso: ese es el mayor de los dones."',
    '56adf5ff': '"Hay luchas eternas, pero quienes tienen gran determinación y voluntad pueden romper el ciclo."',
    '4a57bd01': '*"Tengo algo para ti que quizá te ayude a entender."*Te entrega un libro encuadernado en azul, y por un segundo parece que la locura se desvanece.\n',
    '69f65e5a': '"Llevaré tu pluma blanca, llevaré tu bandera blanca."',
    '0b88cc16': '"¡Qué quieres de mí!"',
    'cf514b6d': '"¿Qué permitimos?  ¿Qué consentimos?"',
    'b8dfa273': '"No tiene por qué ser así."',
    'a82e7438': '"Él lo sabe, ¿sabes?"',
    '4969358d': '"Así todas las cosas se presentan mediante sombras."',
    '03f5855d': '"Un actor cómico más tras una máscara trágica."',
    'd9371000': '"¿Adónde vamos desde aquí?"',
    '088bd6cb': '"Lo que antes era esquivo me llama ahora."*"Tienes que irte de aquí: no es seguro.  Los horrores que han visto mis ojos."*"Hay un terror, una guerra en marcha, y apenas nos damos cuenta.  Pero somos peones, y morimos en esta guerra."*"Los bandos de la guerra nos usan, abusan de nosotros.  Sufrimos.  Solo Alaric puede salvarnos: sacarnos de la lucha."*"Hay que curarlo.  Tienes que salvarlo, salvarnos, salvarte."',
  },
  // Master Bryaxis, who makes locks that open to a tune
  '184C': {
    'c0f5e0b9': 'Ves a un anciano de aspecto bondadoso, con una expresión serena.*',
    '7fbdf20a': '"Ah, me alegro de volver a verte, ',
    '26abca1d': '"Soy Bryaxis, ¿y tú?"',
    '578ee562': '"Encantado de conocerte, ^',
    '98aeecc8': '"Soy un Maestro Mago: investigo la conexión entre el @canto y la magia."',
    'bc3398a2': '"Soy el Maestro Bryaxis."',
    'eff16304': '"La música es magia, o al menos eso digo yo."*"Ahora en serio, he estado trabajando en integrar la música en la magia, aunque de momento solo he tenido un @logro."',
    'c73bd426': '"Es un conjuro especial que reconoce la música.  Fue casi por accidente, pero resulta útil combinado con algo como una cerradura."*"Básicamente, permite crear una @cerradura que se abre tocando una melodía concreta."*"Había algunos problemas, eso sí.  El mayor era que había que tocar la melodía exacta con un instrumento concreto."*"Aun así, pese a esos problemas, conseguí @vender unas cuantas."',
    '94ff9173': '"Parece una cerradura normal, salvo que hay que tocar una @tonada concreta para abrirla."',
    'c2503acc': '"Puede ser cualquier cosa de unas pocas notas: algo sencillo, quizá la canción favorita de uno."',
    'd8f3e2bb': '"Hace años que no hago ninguna.  La última se la vendí a Myus, de la Casa Kosha, que iba a regalársela a su difunto padre."*"Hasta conseguí que mi amigo, el famoso bardo @Demodocus, codificara la melodía que la abre."',
    '328ee5f9': '"¡Vuelve a pasarte más tarde, por favor!"',
    '5dfe6c90': '"Demodocus es uno de mis mejores amigos, y un maestro de la lira."',
    'e71e0981': '*"Acaba de irse de Cademia; creo que iba a Kosha."',
    '37a8b280': '"Quizá lo de maestro es demasiado, buen amigo."*',
    'f42f32ae': '*"De hecho, ahora mismo está en la ciudad."',
    '8500b644': '"Quizá otra persona pueda ayudarte en eso."',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys, { '184C': { musi: 'cant,musi', brya: 'brya', lock: 'cerr' } });
Object.assign(DELV_TRANSLATION_ES.keys['*'], { exil: 'dest,exil', foun: 'fund', semi: 'semi', abyd: 'abyd', tava: 'tava', anis: 'anis' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Anisa, Master Historian, and what she learns of the Sapphire Books
  '184D': {
    '9d15d07b': 'Ves a una mujer de mediana edad, que parece absorta en sus pensamientos.',
    'b53e919e': '"¡Ah!  Debes de ser quien convocó Alaric.  Sí, cambiarás la historia."*"Esto, claro, me importa muchísimo, porque la historia es mi campo, mi pasión."',
    '9c9a53d0': '"Saludos de nuevo a quien ha de cambiar la historia."',
    '5f00e1f1': '"Soy Anisa, Maestra Historiadora."',
    '8bb30536': '"Soy Maestra, en el campo de la Historia."',
    'ce5817ff': '"He estudiado todo lo que he podido encontrar: ¿quizá tengas alguna pregunta que yo pueda responder?"',
    'b8f5806c': '"Pregúntame lo que quieras."',
    'a1ccfe09': '"Bueno, si tienes alguna pregunta sobre historia, no tienes más que hacerla."',
    'f9fc5cc5': '"Los Tiranos fueron nuestros primeros gobernantes.  Su poder absoluto los corrompió."*"Los Magos fueron @desterrados por el Primer Tirano en el 152."*"Fue durante el gobierno del Tercer Tirano cuando apareció Alaric, en el 216.  Acabó con su gobierno."*"No fue hasta el 219 cuando se estableció nuestro sistema de gobierno actual, con el regreso de los Magos."',
    '2ad1eb75': '"El Primer Tirano de Cademia temía los poderes desconocidos de los Magos, así que los desterró en el 152."*"Aunque algunos encontraron refugio en Odemia, la mayoría huyó hacia el oeste, al otro lado de las montañas, y fundó Pnyx."',
    'caa1aa84': '"La ciudad de Pnyx la fundaron los Magos desterrados en el 153, y allí establecieron el Magisterium."',
    '78f3ff20': '"Cademia es nuestra ciudad más antigua, por eso vivo aquí.  Se fundó tras nuestra llegada desde @Thera."',
    '76e1ab37': '"Ese sí que es un nombre antiguo.  Nuestro hogar original era la isla de Thera, antes de que fuera destruida."',
    '1dbb6f8b': '"Catamarca se fundó en el 113 como retiro del primer Tirano.  Un acantilado fácil de defender con una buena fuente de agua."*"Desde entonces, Catamarca es famosa por su agua."',
    '9a1e3ba2': '"Odemia se fundó 5 años después de nuestra llegada desde @Thera, pero durante un año no fue más que un campamento de caza permanente."',
    'c1781017': '"Kosha es un asentamiento más reciente, fundado por la Casa Comana en el 303."',
    '0982b5b2': '"Las Casas descienden de los seis primeros líderes poderosos que ayudaron a unir la sociedad tras la destrucción de los Tiranos."',
    '587f6990': '"El fundador, Nicander, era en origen el jefe de un grupo de cazadores."',
    '7c2fe00f': '"La fundadora, Dodona, era en origen posadera aquí, en Cademia."',
    '35c3fc59': '"El fundador, Strymon, no era más que un simple granjero, hasta que actuó para ayudar a unir nuestra sociedad tras la destrucción de los Tiranos."',
    'e1376cb2': '"El fundador, Atusa, era en origen el jefe de un grupo de artesanos."',
    '05b5341a': '"El fundador, Attis, era en origen un paje de la corte de los Tiranos, a quien su ingenio llevó al poder."',
    '42f5ccd3': '"El fundador, Comana, era en origen un poderoso mercader."',
    '42a777c0': '"Seguramente ya has oído la historia básica de boca de otros Magos."*"Básicamente, el primer gólem lo creó en el 663 D.T. un mago cuyo nombre se ha perdido en la historia."*"No fue hasta unos veinte años después cuando se descubrió el problema básico que tenían."*"Incluso hacia el 700 D.T. todavía se creaban gólems."*"Hacia el 720 D.T., sin embargo, estaban prohibidos, y empezó un intento de destruir los gólems \'salvajes\' que quedaban."*"El más famoso de esos intentos fue el de @Semius, que desapareció aquí, en Cademia, en el 742 D.T."',
    '4c5b35fe': '"Semius, que se hacía llamar \'Cazador de Gólems\', desaparece aquí, en Cademia, en el 742 D.T."*"Según la leyenda, encontró uno de los talleres secretos del Mago @Machaon, y el gólem que había allí lo derrotó."*"Aunque también puede que simplemente resbalara en las alcantarillas y se rompiera el cuello: ya sabes cómo se cuentan las historias."*"Si no recuerdo mal, el predecesor del juez Metopes en Catamarca era un gran aficionado a Semius."*"Quizá todavía puedas encontrar algunos de sus viejos libros en Catamarca."',
    '9ad94ce2': '"Volveremos a vernos..."',
    'a07e738b': '"En el 184, unos colonos de Pnyx intentaron fundar una segunda comunidad, favorable a los Magos, costa abajo al sur de Pnyx."*"Todo fue bien hasta el 192, cuando se cortó toda comunicación con ella."*"Cuando se envió una expedición, descubrieron que todo el mundo había desaparecido del asentamiento, pero sin rastro de violencia."*"Desde entonces ha quedado a merced de los elementos, y hay quien dice que está encantado.  Nadie sabe qué les pasó a sus habitantes."',
    'c736ef01': '"Creo que Tavara era el alcalde del desdichado asentamiento de @Abydos."',
    '65787aae': '"Lo siento, pero ya te he contado todo lo que averigüé sobre dónde están..."',
    '4b083fd8': '"¿Has averiguado quién es la madre de Alaric?"',
    '90cd1555': '"Creo que te equivocas; por favor, cumple tu promesa..."',
    '5f4322c6': '"Sí, se llamaba Chrysothemis, y murió en el 201 en Catamarca."*',
    '881ff7d5': '"Mmm, fascinante.  Tendré que investigarlo más a fondo cuando tenga más tiempo..."*"Bien, esto es lo que he averiguado sobre los Libros de Zafiro de la Sabiduría."*"Nadie sabe muy bien quién los escribió, salvo que se remontan a los primeros tiempos del Magisterium, si no antes."*"Son diez, pero seguro que eso ya lo has oído."*"El caso es que el Libro de Zafiro del Poder estaba en posesión del Mago @Machaon, que vivía aquí, en Cademia."*"Eso, sin embargo, fue hace unos 200 años, y no está claro dónde vivía, aunque probablemente fuera en la esquina noroeste del Laberinto."*"El Libro de Zafiro de la Sabiduría se le dio a Tavara para ayudarle a dirigir la colonia de Abydos, pero todos sabemos lo que pasó allí..."*"El Libro de Zafiro del Esplendor se mencionó por última vez en posesión de un Juez de Catamarca olvidado hace mucho."*"Esto no te va a gustar, pero se decía que el Libro de Zafiro de la Victoria pertenecía a un antepasado de la Casa Nicander."*"Por desgracia, según cuenta la historia, un día lo tiró al mar frente a Odemia."*"El Libro de Zafiro del Fundamento es la historia más extraña de todas."*"Se dice que hace casi 750 años se lo cambiaron a una especie de Espíritu de la Tierra a cambio de algún tipo de conocimiento."*"El de la Belleza parece haberse perdido por completo."',
    'd7f1f876': '"Bueno, vuelve cuando lo averigües..."',
    '6e29ed9f': '"He oído hablar de los Libros de Zafiro del Conocimiento, pero no tengo ni idea de dónde están..."*"Estaría dispuesta a investigarlos un poco, si a cambio haces tú una tarea para mí: ¿te interesa?"',
    'a6650adf': '"¡Excelente!  He estado investigando sobre Alaric y he averiguado cosas interesantes."*"Aunque no recuerda haber conocido nunca a su padre, se crió con su madre en Catamarca."*"Por desgracia, no tengo ni idea de cuándo fue exactamente, ni de cómo se llamaba ella."*"Como fue en el 216 cuando se presentó ante el Tercer Tirano para destruirlo, sabemos que fue antes de esa fecha."*"Aparte de eso, no sabemos mucho más.  Tengo entendido, sin embargo, que tienes una relación cercana con él."*"Quizá puedas aclararme este asunto; a cambio, me esforzaré por averiguar lo que pueda sobre los Libros de Zafiro para ti."',
    'fbe271cd': '"Muy bien, pero si cambias de idea, dímelo..."',
    '17ba0368': '"El Mago Machaon vivía aquí, en Cademia, hace unos 200 años."*"Tenía varios talleres y bibliotecas secretos.  Nadie en la ciudad sabía realmente dónde vivía."*"Probablemente todavía quedan cámaras ocultas suyas por descubrir a día de hoy."',
    'd41a36b5': '"Sí, conozco las Profecías de Neleneus: creo que tengo un ejemplar de una de ellas entre mis libros."*"Como historiadora, es bastante fácil relacionar la primera profecía con la caída de los Tiranos."*"Por desgracia, en la tercera no hay gran cosa útil, al menos que yo vea."*"Y la segunda se ha perdido en el tiempo."',
    'd44552c3': '"Lo siento: no conozco eso."',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys, { '184D': { ther: 'ther', hous: 'casa' } });
Object.assign(DELV_TRANSLATION_ES.keys['*'], { heal: 'cura,sana', regi: 'regi', egg: 'huev', pher: 'pher' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Pheres, who teaches the Healing Arts, and the harpy egg
  '184E': {
    'a8039974': 'Ves a un hombre de aspecto pacífico, con un brillo interior.*',
    '4c0c70a0': '"...y así, aplicando presión, digamos... clase, ¿me disculpáis un momento?"*',
    'a03a2665': '"¡Ah, excelente!  ¡Has encontrado un huevo de arpía!  Te lo agradezco muchísimo..."*',
    'f72282b9': '"Si no te importa, estoy en plena clase."*',
    '0857de19': '"Soy Pheres, profesor de las Artes @Curativas."',
    'c20b5f48': '"@Instruyo a los estudiantes en las Artes @Curativas, y no hay nada más noble."',
    '948688c0': '"La curación consiste en reparar los daños del cuerpo."',
    'c6e4700d': '"Te falta la comprensión básica de la magia necesaria."',
    'b0643946': '"Ya dominas lo básico; no creo que entendieras mucho más."',
    'ed19fa3d': '"Puedo darte lo básico, lo suficiente para ser de ayuda.  No tienes tiempo para un estudio detallado, ya me entiendes."*"La Magia Curativa consiste en reparar los daños sufridos por un ser vivo volviendo a armonizar la zona afectada con el resto del cuerpo."*"Eso es para casos sencillos, como heridas simples y cosas así.  Las situaciones más complejas no son tan sencillas."*"Una herida grave, por ejemplo, tiene demasiado daño para poder armonizarse fácilmente con el cuerpo sano."*"Se podría o bien dar pequeños pasos para reparar el daño, por fases, o aplicar un patrón externo de armonización."*"Así, un conjuro de curación superior requiere comprender a fondo un conjuro de curación básico."',
    '21e32558': '"Necesitas algo más de experiencia antes de poder aprender magia curativa."',
    '96b21224': '"Lo siento, pero primero tienes que @registrarte."',
    'bed7f81a': '"Ve en armonía."',
    'edff53c8': '"No lo olvides: prometiste conseguirme un huevo de arpía..."',
    'fd584733': '"Me doy cuenta de que tienes tus propias tareas, pero ¿podrías hacerme un favor mientras exploras?"',
    '838d6727': '"Excelente.  ¿Conoces las arpías?"',
    'a803b1b2': '"Excelente.  ',
    '2841a104': '"Son esas extrañas criaturas voladoras, no muy comunes, pero bastante peligrosas."*"',
    'bc617c79': 'En mis estudios necesito examinar en detalle un huevo de esa criatura."*"Si encuentras uno, ¿podrías traérmelo, por favor?  Te lo agradecería..."',
    '3e3e99a4': '"Lo entiendo, pero si cambias de idea, vuelve a verme, por favor."',
    'b886e753': '"Bueno, se rumorea que los huevos de arpía pueden guardarse durante años y luego eclosionar en esas viles criaturas."*"Es como si los huevos de arpía pudieran resistir el paso del tiempo sin que les afecte."*"Si se pudiera extraer alguna esencia, quizá permitiría ralentizar el cuerpo, evitando los estragos del tiempo."*"Es solo una teoría, ojo."',
    'c6ed5e7c': '"Soy muy consciente del estado de Alaric, pero sus problemas están muy por encima de mis habilidades."*"Está más allá del patrón de armonía de referencia de los humanos normales: no sabría ni por dónde empezar a ayudarle."',
    '6897e834': '"Lo siento, pero eso queda fuera de mi campo."',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys, { '184E': { trai: 'inst,entr', teac: 'inst,ense' } });
Object.assign(DELV_TRANSLATION_ES.keys['*'], { pala: 'pala' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Charax the Alchemist, the timeflux, and the sour wine
  '184F': {
    '5b2e9490': 'Ves a un joven nervioso y desaliñado.*',
    '1244720d': '"¡Ah, has encontrado el libro sobre el flujo temporal!"*Charax te coge el libro.*',
    '51f1d70f': '"Mmm, déjame estudiarlo un tiempo; ¿por qué no vuelves dentro de un par de días?"*"Puede que este asunto parezca trivial, pero podría haber mucho relacionado con él que aún está por desenterrar."*Charax se da la vuelta, hojeando el libro.',
    '3844176a': '"Estoy avanzando, pero despacio, y no funciona del todo como esperaba."*"En realidad es fascinante: hay propiedades de campo subyacentes del Mar, del Tiempo y del Cambio."*"Y como la Alquimia se basa en el Cambio, bueno, te puedes imaginar que esto es de lo más fascinante."*"Dame algo más de tiempo con esto: tengo que agradecerte que me hayas planteado una cuestión tan fascinante..."',
    '355a9a86': '"¿Has dado ya con el reactivo de polaridad de Tierra?"*',
    '48dc1165': '"He avanzado algo, pero más bien descartando posibilidades."*',
    '44362e00': '"Me dio esta seta la jefa de los Seldane, y pensé que quizá fuera lo que buscabas."*Le das a Charax las esporas que te dio Sabinate.\n',
    '22a1463a': '*"Mmm, setas, de la tierra, sí: eso podría servir.  Muy bien, veamos qué sale de esto..."',
    'e8145513': 'Charax carga el destilador con la seta y el alga.\n*',
    'c9331a80': 'Charax pone una cara de lo más desconcertada.\n*"Algo va mal: no está destilando nada; parece haber capturado la esencia, pero..."*"Quizá no tengo fuerza suficiente, no lo sé.  Está cargado del todo, desde luego, pero parece casi atascado, o bloqueado."*"Es como si no tuviera que hacer una poción en absoluto, sino más bien un sistema neutralizador."*"Apuesto a que si se usara sobre algo, podría eliminar la esencia de polaridad de Mar y neutralizarla con la polaridad de Tierra."*"Por desgracia, eso no ayudará al vino: un destilador no se puede mover sin derramarlo."*',
    '166b5b6a': '"Todavía estoy trabajando en el reactivo de polaridad de Tierra: vuelve más tarde."',
    '72e29322': '"Tengo que estudiar lo que ha pasado con el destilador: por favor, déjame un tiempo a solas."',
    'faf3d151': '"¿Ha habido suerte encontrando el alga rara de las profundidades?"*',
    '83b22b32': '"He avanzado, y tengo una posible solución, aunque quizá no funcione."*"Consiste en extraer la polaridad basada en el Mar, lo que debería revertir los cambios basados en el flujo temporal."*"Sin embargo, necesito un poco de alga rara de las profundidades del mar, y algo más que vuelva a imponer la polaridad de Tierra, pero con eso aún no lo tengo claro."',
    'f641c7e4': '*"Quizá podrías intentar buscarla mientras sigo investigando...  Vuelve cuando la encuentres, gracias."',
    '6c5e028a': 'Levantas el alga que encontraste.*"¿Un alga como esta?"',
    'a14e9aa0': ' levanta el alga que encontraste.*"¿Servirá esto?"',
    '6fc4ab6e': '"¡Excelente!  Parece perfecta.  Gracias."*Charax coge el alga',
    '3ecd2f32': '*"Ahora solo tengo que resolver lo del reactivo de polaridad de Tierra..."',
    '9d0468c5': '"No, todavía no."*',
    'e676150b': '"Bueno, vuelve cuando hayas avanzado."',
    '6307550b': '"Sabes que no me gustan las interrupciones, pero ¿qué puedo hacer por ti?"',
    '0c633d4c': '"Mira: estoy muy ocupado, y de todos modos no entenderías lo que hago, así que ¡vete!"',
    '4cf45274': '"¿Eres Charax?"*', 'fc1910b3': '"Sí, lo soy, ¿por qué?"*',
    '853e33af': '"Palaestra me dijo que te encontraría aquí."*',
    'f6edad58': '"Demuéstralo: ¿sabes alquimia?"*',
    '2cb9f5a4': '"Sí: ¡me la enseñó la propia Palaestra!"*',
    'bf9a0840': '"Mmm, muy bien, sé breve: ¿qué puedo hacer por ti?"',
    'ccb1cd03': '"No, no sé."*',
    '43909bd4': '"Entonces no lo entenderías: por favor, déjame en paz."',
    '658af5f2': '"Soy Charax... ¿no decías que ya lo sabías?"',
    'df77951f': '"Soy un Mago Libre, y estudio la @Alquimia."',
    '57bf1a42': '"La Alquimia es el arte de hacer pociones... pero ¿no decías que te había enseñado @Palaestra?"',
    '6714205d': '"No le tengo más que respeto: ¡menuda profesora!"',
    'cf54c439': '"No me tomes por grosero, pero por favor, déjame solo con mis estudios."',
    '4eb14392': '"Pues sí, hago vino: a veces cuesta conseguirlo aquí fuera."*"Mi favorito es el Tinto de la Costa Norte, pero el mío se deja beber."',
    'a58d9e5c': '"¿No te has enterado?  Algo salió mal y todas sus existencias se estropearon, ¡y el mosto también!"*',
    '1313f2dc': '"¡No!  ¡No puede ser!  ¿Alguna idea de qué pasó?"*',
    '262c0d90': '"La verdad es que no: esperaba que tú pudieras ayudar."*',
    'c1b87bf7': '"No: una vez que el vino se agria, no hay forma de invertir el proceso."*',
    '31a7d832': '"Pero ¿qué podría causarlo?"*',
    '26569aa9': '"El tiempo es lo único que conozco que agria el vino."*"Pero el mosto no puede agriarse sin convertirse antes en vino, y eso también lleva tiempo."*',
    '6e8d7e7a': '"¿Y la magia o la alquimia?"*',
    'cba58e72': '"Está claro que no aprendiste mucho de Palaestra."*"Supongo que algún tipo de conjuro podría haber alterado el flujo temporal..."*"Aunque no conozco a nadie, aparte de Alaric, que pudiera aspirar a conseguir algo así."*"Aunque recuerdo haber visto una vez un libro sobre eso en el Magisterium."*"Quizá deberías ir a preguntarle a Selinus: conoce todos los libros del Magisterium."*"Si consigues encontrarlo y me lo traes, veré qué puedo averiguar..."',
    '87fb68f0': '"No puedo ayudarte: por favor, deja de hacerme perder el tiempo."',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys['*'], { spy: 'espi', ciph: 'cifr,manu' });
Object.assign(DELV_TRANSLATION_ES.text['*'], { '4078ad2a': 'Poder', '2047d1a2': 'Conjuros' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Lindus, Headmaster of the Magisterium
  '1850': {
    'db7db8e2': '"Te doy la bienvenida.  Alaric dijo que vendrías tarde o temprano.  Soy Lindus, Director del Magisterium."',
    '4dcd72f7': '"Te doy de nuevo la bienvenida."',
    'c769bb9c': '"Vienes a aprender los Caminos del Mago, ¿no?"',
    '9157a3e0': '=',
    'dd18c806': '*"La posesión más preciada de un Mago es su grimorio, así que tengo el orgullo de entregarte el tuyo..."*"Ya puedes usarlo para aprender conjuros (úsalo con el pergamino)"*',
    '2faf290f': '"Muy bien, veo que tienes asuntos más urgentes."',
    'f909c2de': '"Soy Lindus, Director del Magisterium"',
    'eb7cc99f': '"Soy el Director del Magisterium, el trabajo más ingrato que haya existido."',
    '805bb7c7': '"Los Metecos son una raza de seres místicos que habitan este mundo."*',
    '98211bd4': '"La persona con quien hablar es @Timon"',
    'ddb03347': '"¿Has dado ya con @Timon?  Creo que está en las ruinas del nordeste..."',
    '31d1d6b5': '"Como sabes, Timon los ha estado estudiando."',
    '750e56e4': '"Aunque nunca los he visto, existen, desde luego, digan lo que digan otros."',
    '4558a926': '"Mmm, he oído ese nombre antes, pero no recuerdo muy bien dónde..."',
    '86fb5372': '"Mmm, sí, es un cristal interesante.  Es igual que el que encontró @Timon."*',
    'f49120c3': '"Te sugeriría que fueras a hablar con él; quizá pueda arrojar algo de luz sobre el tema."*"Ahora está trabajando en las @ruinas al nordeste de aquí."',
    'cd32f7a0': '"Si te @registraras, me encargaría de que sacara tiempo de sus muchos estudios para hablar contigo."',
    '9ad5675b': '"No sé de qué me hablas."',
    '890704af': '"@Timon sabe más de eso que yo; habla con él."',
    'bc7d2cfe': '"Ha estado estudiando las @ruinas de los Metecos y un artefacto que encontró, muy parecido a ese @cristal verde luminoso que llevas."*',
    '4073278c': '"Quizá deberías hablar con él, y ver qué sabe."',
    'fff63465': '"Ha estado estudiando las @ruinas de los Metecos."',
    '9ffdfb81': '"¿Todavía no has dado con él?  Seguramente está en las @ruinas del nordeste."',
    '28f89783': '"Todos estamos muy orgullosos de su trabajo."',
    'd08cef24': '"Es uno de nuestros Magos Libres, dedicado a la investigación."',
    '6f6f0091': '"Ah, sí, así que has oído hablar de Eioneus.  Es un Mago Libre que investiga cómo mejorar las armas con magia."*"Bien mirado, podría resultarte muy útil.  Quizá te convenga buscarlo."*"Hace tiempo que no lo veo, pero por lo que recuerdo de su trabajo, necesita una fuente de lava."*"Hay un par de ellas, desde el volcán de Fin de la Tierra hasta varias cuevas de las montañas."*"Su hermana menor, Semele, es estudiante aquí: quizá te convenga hablar con ella."',
    'a0fa2cbd': '"Hay unas ruinas al nordeste: sigue el río Tirynth corriente arriba y no tienes pérdida."',
    '17bd9ac5': '"Mi puerta siempre está abierta para un estudiante."',
    '42f1168f': '"Vuelve, por favor: hay entrenamiento que podemos darte y que te ayudará en tus pruebas."',
    '0da9e8dd': '"No sé de qué me hablas."',
    '49ce97f2': '"Sacas está a cargo de investigar eso.  Deberías ir a Odemia e informarle directamente a ella."',
    '3971141e': '"Sí, me he enterado.  Un espía que usaba ese asqueroso kesh: esto no augura nada bueno."',
    'a9e3f40b': '"Nuestros poderes mágicos detectarían fácilmente a los espías metidos en cualquier asunto de estado."',
    '5667b8ff': '"El Manuscrito Cifrado es uno de nuestros mayores secretos.  Hay una traducción en la Sala del Octavo Grado."*"En cuanto a qué significa, y sus implicaciones, ni siquiera yo sé mucho más de lo que puede leerse allí."*"Te ruego que no hables de esto con nadie..."',
    'ae7d2e9b': '"Obviamente, como Director, estoy más cerca de Alaric que nadie, salvo quizá su servicio personal."*"En público, debo presentar una fachada unida de \'todo va a salir bien\', pero en privado estoy muy preocupado."*"Intentamos hacer planes para cualquier eventualidad, pero la cosa pinta mal, vaya como vaya."',
    '1d4b58fd': '"A decir verdad, no me fío de él: sé que Alaric recurre a menudo a él en busca de consejo, pero aun así me da una sensación rara."',
    '3b88f985': '"Seguro que has oído los rumores, sobre tesoros o experimentos fallidos, pero bueno, no son exactamente ciertos."*"Los túneles bajo Pnyx se usaban de almacén, pero por desgracia hay un gólem suelto en ellos."*"Simplemente mantenemos a la gente fuera, por su propia seguridad.  Nada más siniestro que eso."*"Nadie ha bajado allí desde hace siglos; por lo menos no desde que me nombraron Director."*"Los secretos de cómo bajar allí están bien guardados: no queremos que les pase ningún accidente a los estudiantes demasiado curiosos."',
    '4317ea8f': '"Me temo que no sé de qué me hablas."',
  },
});
