Object.assign(DELV_TRANSLATION_ES.keys['*'], { mom: 'mami,mama', momm: 'mami,mama', dad: 'papi,papa', dadd: 'papi,papa', aban: 'aban', jopp: 'jopp', save: 'salv' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Niobe, Paris and Helen's daughter, who dreamt of the hero
  '1859': {
    '930693a9': 'Ves a una niña tímida, de largo pelo rubio y grandes ojos azules.',
    '913028ef': '"Mi mamá me dijo que no hablara con desconocidos."',
    '6a207a07': '"No pasa nada, Niobe."',
    '9a3721df': '"¡Te reconozco de mi @pesadilla!"',
    '7733cc53': '"No molestes a ', '6f023d15': 'esta señora tan amable', 'e9a2ff6f': 'este señor tan amable', '7d1d2031': ' con tus tonterías."',
    '2af6a8cf': '"Me llamo Niobe."',
    '2b66ea95': '"Qué tonto: solo soy una niña pequeña, aunque a veces ayudo a mi @mami en la \'@Sala de Estudio\'."',
    '4804ef08': '"A la Sala de Estudio viene mucha gente simpática."',
    '86ae337d': '"Los mayores llaman a mi mami Helen."',
    'a9a3edbb': '"Mi papi se llama Paris."',
    '2fbabb9a': '"Soñé que estaba jugando en la playa, cerca del agua.  Mi mami no me deja hacer eso, y por eso sé que era un sueño."*"Entonces vino una ola grande, y cuando se retiró había una persona tumbada allí."*"Me acerqué a ',
    'f4b48d8c': 'ella', '0bd2c6d5': 'él',
    'e3b450d6': ' y vi que eras tú."*"Oí un ruido detrás de mí, pero no había nada."*"Cuando me volví otra vez, ya no era una persona, sino un pez grande que se fue nadando."*"Fue un sueño muy raro."',
    'd5b543e3': '"¡Ven a jugar otra vez algún día!"',
    'df06806f': '"No sé; a lo mejor lo sabe algún mayor."',
  },
  // Larisa the explorer, Timon's sister, at the swamp ruins
  '185A': {
    'c71cbef5': '"¡Timon!  ¡Qué alegría volver a verte!  ¿Qué tal los estudios?  ¿Qué te trae a estas ciénagas?"*',
    'eb1e27d3': '"Ah, Larisa, yo también me alegro de volver a verte.  Mis estudios me han llevado a una gran aventura, no muy distinta de la tuya aquí."*"Todo muy interesante, pero tendremos que dejar los detalles para otra ocasión.  Deja que te presente a mi amistad, ^',
    '0a2aea08': '"Encantada de conocerte, ',
    '3b35a2f8': '.  Toda persona amiga de Timon es amiga mía.  ¿Qué te trae a esta ciénaga?"*',
    'dd664606': '"Bueno, estamos investigando sobre las ruinas seldane, como sabes, y estas ruinas podrían ser clave para entenderlas."*',
    '0b04001a': '"Bueno, la verdad es que aquí no hay gran cosa, salvo un edificio cuyas puertas se niegan a abrirse.  Por lo demás, nada especial."*"Supongo que eso no es del todo cierto, ya que estas ruinas están en un estado excelente, y son la primera prueba que relaciona esos pilones con los Seldane."*"A decir verdad, estaba a punto de irme y volver a Kosha para dar mi informe a Myus: ya voy con retraso."*',
    'ca96d3a2': '"¿Te importaría que echáramos un vistazo por aquí?"*',
    'c78a3c3a': '"En absoluto.  Adelante; quizá nos veamos en Kosha..."',
    '22158005': '"Lo siento, pero aquí no se permite la entrada a gente de fuera: te pediría que te fueras."',
    'c1060dbe': '"Lo siento, pero tengo que terminar aquí y volver a Kosha, y tengo un poco de prisa."',
    'b67dcc06': '"Pues Larisa, qué cosas tienes."',
    'b2638505': '"Soy exploradora, por mucho que a mi hermano mayor le cueste admitirlo."',
    'bcc6a884': '"Mi hermano Timon, claro."',
    '424f9bff': '"Estoy muy orgullosa de él."',
    'abc7f89a': '"Quizá volvamos a vernos en Kosha."',
    'e4b37efb': '"La raza seldane está casi con toda seguridad extinta."',
    '68b358a6': '"Estas ruinas fueron en tiempos una poderosa ciudad seldane, por lo que he podido averiguar.  Pero algo hizo que fuera @abandonada."',
    '54b2e73a': '"Pudo ser un desastre natural, o algún tipo de conflicto, pero algo expulsó a los Seldane de esta ciudad."',
    'e0ba931e': '"Joppa puede parecer un poco gruñón, pero es muy de fiar."',
    '9586a2b7': '"Lo siento, ¿podrías repetirlo?"',
  },
  // Joppa, her assistant, Myus's man
  '185B': {
    'b9edb9df': 'Ves a un hombre de mediana edad, de cara ancha y ojos estrechos, con una boca ancha y labios finos.*',
    '28dfab8c': '"Vaya, Timon, me alegro de volver a verte.  ¿Quién es tu amistad?"*',
    'aba124fa': '"Joppa.  Permíteme presentarte a ^',
    'ee62c72f': '"Encantado, desde luego."',
    '83cf11e6': '"¿Quién eres tú, que andas merodeando por aquí?"',
    '964d1c2f': '"Mmm, ya, claro."',
    '856fc6e5': '"Ya te lo he dicho: me llamo Joppa."',
    '9a4308bc': '"Ayudo a la señora Larisa, y la protejo en estas @ruinas."',
    'dd365837': '"El señor Myus me encargó ayudarla y protegerla."',
    '391d0aec': '"Sí, lo que tú digas."',
    '069955cc': '"El señor Myus es un buen gobernante, y además muy buena persona."',
    '3beb36a0': '"Mira a tu alrededor: ¿estás ciego o qué?"',
    '9c348520': 'Te mira como si fueras idiota.',
  },
  '185C': { '08f150e9': 'Ves a un rufián de aspecto sucio.\n*"Si supieras lo que te conviene, seguirías tu camino...."' },
  // Eumelus, a drunk in Catamarca who never drinks the water
  '185D': {
    '4e99af44': 'Ves a un borracho viejo y maloliente\n*"¿Tienes algo suelto?"',
    '181340a8': '"Gracias, ', '85d31c9b': 'encantadora señora.', 'a48dc0e5': 'amable señor.', 'ccd8c21d': '  Que la @plaga nunca te alcance."',
    '33c8d02b': '"Soy Eumelus, aunque suelo responder a \'Eh, tú\'"',
    '2135796d': '"Una vez tuve trabajo, pero mi debilidad por la bebida me destruyó, o quizá sirvió para @salvarme."',
    'ce5b828a': '"Todavía no he pillado la @plaga, y lo único que me pone malo es el @vino"',
    '30cdd101': '"¡Bah!  Nunca la pruebo.  No te puedes fiar de ella como del @vino."',
    '2e6524bc': '"Era el @agua lo que ponía mala a la gente, ¿verdad?..."',
    '0a8a372b': '"Demasiado vino puede ponerte malo, pero la plaga nunca te la pega, o al menos a mí no."',
    '351b34ba': '"Si me preguntas, y me has preguntado, es el @agua lo que pone mala a la gente.  Eumelus solo bebe @vino, nada de @agua."',
    '02db574b': '"Tenía razón con lo del agua, ¿a que sí?"',
    '710311ad': '"¿Me quieres invitar a una ronda?  Ja, es broma..."',
    '9e6cf7d2': '"O yo estoy muy borracho o tú estás muy sobrio"',
    '394d5ec2': '"Ojalá te pille la plaga..."',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys, { '1859': { mom: 'mami,mama', moth: 'mami,madr', fath: 'papi,padr' }, '185A': { brot: 'herm' } });
Object.assign(DELV_TRANSLATION_ES.keys['*'], { mist: 'erro', grou: 'grup', peop: 'gent', reas: 'razo', peir: 'peir', eudo: 'eudo' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Antiphus, the bandit in the Odemia jail
  '185E': {
    'e1cbee19': 'Ves a un bandido con una mueca de desprecio.',
    '27586848': '"¿Vuelves para burlarte de mí?"',
    '1c1f6f79': '"Oooh, tú debes de ser la gran figura heroica que no logró rescatar a Ariadne."',
    '039c8706': '"Así que eres quien rescató a Ariadne: has cometido un gran @error."',
    'fdb122a4': '"No es que sea asunto tuyo, pero puedes llamarme Antiphus."',
    '81f96dd6': '"No vuelvas."',
    '887782ca': '"Eres idiota, ¿verdad?"',
    '045d3410': '"Hasta intentar meterse con nuestro grupo de @gente fue un error."',
    '4b8c76bd': '"Te crees muy importante porque rescataste a Ariadne, pero te has cruzado con el grupo de @gente equivocado."',
    '8801966a': '"Digamos que son más poderosos que esos necios de Nicander."',
    '323541c2': '"Alaric es un viejo necio chocho, cuya época ya pasó."',
    'dac25d3e': '"Qué cosa tan buena, ¿verdad?"',
    '8df9753b': '"Sí, seguí a Eudoxus, y es todo lo que voy a decir."',
    '0e3ea8b1': '"Deja de parlotear y déjame en paz."',
  },
  // Polydamas, majordomo of the Citadel of Catamarca
  '185F': {
    '8661ddb0': 'Ves a un anciano que apenas puede moverse.',
    '5cbf1f9e': '  Un ataque de tos le sacude el cuerpo.', '650b4f66': '  Pese a ello, parece lleno de vida.',
    'a03b592a': '"Acércate un poco: mis ojos ya no son lo que eran."*',
    '852e9a2a': '"¿Te conozco?  Creo que no.  Me llamo Polydamas.  ¿Y tú eres?"',
    '73245d7d': '"Eres quien detuvo la plaga, ¿verdad?..."',
    '2b0dc4fa': '"Sí, te reconozco, aunque mi cabeza ya no es lo que era..."',
    'b34abeb9': '"¿Eh?  ¿Podrías hablar un poco más alto?"',
    'f500d583': '"¿Ya lo has olvidado?  A mí también me pasa.  Me llamo Polydamas."',
    '41c20d14': '"Metopes es el Juez de Catamarca.  Es el tercer Juez al que sirvo."',
    '95eff9ef': '"Soy el mayordomo de la @Ciudadela.  Un título muy elegante, pero soy cocinero, portero, lo que haga falta."',
    '82a169ae': '"Me está consumiendo, y probablemente me matará antes de no mucho.  Hasta el amo está desconcertado sin saber cómo curarla..."',
    '83d7d4f1': '"La cosa se puso bastante fea, ¿verdad?"',
    '7e130900': '"La Ciudadela de Catamarca la construyó hace unos 700 años el Segundo @Tirano de Cademia."*"Era a la vez residencia de verano y puesto militar."*"Se construyó en este pedazo de roca porque domina tanto la ciudad como el océano.  Supongo que también tendrían otras @razones."',
    '75932faf': '"Pues el @agua, claro."',
    'da368776': '"Catamarca tiene la mejor agua del mundo, que brota de un manantial bajo este mismo pedazo de roca."',
    'ea2f69b6': '"Los Tiranos de Cademia fueron una familia gobernante de corta vida en el este de Cythera, hasta que Alaric puso fin a esa tontería."',
    'bd59e296': '"Espero que lo encontraras..."',
    'b549c219': '"¿Sabes?, qué curioso que lo menciones.  Mi predecesor, cuando empecé en este trabajo, me dio este libro."*"Dijo que lo había dejado un Mago años atrás, y que parecía importante, así que me pidió que cuidara de él."*"Todavía lo tengo; creo que está debajo de mi cama, en mis aposentos: puedes buscarlo allí si quieres..."',
    '6dea7b31': '"Ojalá volvamos a vernos, pero la plaga está acabando conmigo..."',
    '28107dc7': '"Cuídate."',
    'a31ca5a6': '"¿Eh?  ¿Qué has dicho?"',
  },
  // Peirithous, Sacas's majordomo
  '1860': {
    '1edb8199': 'Ves a un hombre de mediana edad y gesto adusto.*"',
    'c188329d': '"Me llamo Peirithous."',
    '90b936a4': '"Soy el mayordomo de la jueza Sacas."',
    'eadda9fa': '"Muy bien: tengo trabajo que hacer."',
    'c6eefeab': '"La jueza Sacas es una persona honorable."',
    '0ea043a2': '"Lo siento, pero no me corresponde a mí chismorrear sobre eso."',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys, { '185F': { cook: 'coci' } });
Object.assign(DELV_TRANSLATION_ES.keys['*'], { miss: 'proy', awfu: 'horr', eteo: 'eteo', mele: 'mele', rats: 'rata', poda: 'poda', bali: 'bali' });
Object.assign(DELV_TRANSLATION_ES.text['*'], { 'b7567daa': '"No sé de qué me hablas."', 'fe280e48': '"No lo entiendo."', '92443e96': '"Tengo miedo, pero tenemos que ayudar a Halos."', '1800216e': '"Lo entiendo: todavía es demasiado peligroso.  Estaré bien aquí hasta que creas que no hay peligro."' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Aethon, a ratcatcher and a thief, and a companion
  '1861': {
    '59aa47e5': 'Qué lento vas, abuelo', '5561a9f7': 'Sin ganzúas...',
    '75030be0': 'Ves a un hombre bajo, con cara de rata y una sonrisa traviesa.*',
    'b9376889': '"Aethon: tan bueno como cualquier otro."',
    '78e99cfd': '"Hasta luego..."',
    'cb7d95d0': '"Estoy entre un trabajo y otro, así que hago cosas como trabajos de @ratero."',
    '8368f856': '"Cazar ratas es un servicio muy útil, aunque no está bien pagado."',
    '9d8eb9d8': '"Asquerosas alimañas de seis patas."',
    'ee9317ba': '"Soy muy fan suyo: es muy bueno."',
    'f39ce5f2': '"Es una vieja gloria."*',
    'ab0fd5c6': '"Debería enseñarte respeto a golpes, pero es una causa perdida."*',
    '4d302012': '"Inténtalo, abuelo..."',
    '84c844e6': '"Que no se entere, pero le respeto de verdad."',
    '95fd4991': '"¡No puedo creer que sea culpable de asesinato!"',
    '3d0ec2f5': '"Sabía que era inocente."',
    '80ff0b5f': '"Digamos que hemos hecho negocios antes, y no me refiero a cazar ratas."',
    '2917bda9': '"Un comerciante de Strymon, según tengo entendido."',
    'f78187f3': '"Pero si ya vamos de aventuras juntos."',
    '58c65398': '"Toda persona amiga de Halos es amiga mía"',
    '4263eaf5': '"Lo siento, pero tengo ratas que cazar."',
    '5186b72d': '"He oído hablar de eso, pero no mucho más: yo preguntaría al maestro del Gremio, Eteocles."',
    '80e35327': '"Eteocles es el jefe del Gremio de Rateros."',
    'd54d9ab4': '"El Gremio de Rateros es una sociedad honorable."',
    'e2b3e2cd': '"Soy muy partidario de usar proyectiles en combate: ¿quieres aprender unos cuantos trucos?"',
    'fea4b2da': '=',
    '0df4bd66': '"Bueno, si cambias de idea, no tienes más que preguntarme por los @proyectiles."',
    '1e727dc6': '"Muy bien, como quieras."',
    '3120c073': '"Quizá ya es hora de que cace unas cuantas ratas por mi cuenta..."',
    '76b8bed1': '"La Casa Comana no sirve ni para barrer estiércol."',
    '7fe7a23f': '"He hecho negocios con ellos antes..."',
    '96ddfb06': '"Puedo investigarlo..."',
  },
  // Dryas, a boy of the Ratcatchers' Guild, and the witness Halos needs
  '1862': {
    '51433b6f': 'Ves a un niño pequeño y mugriento, de unos 12 años.',
    '05e1f928': '"¿Ya no hay peligro?  ¿Puedes llevarme ante Berossus?"',
    'd3adfcb9': '"¡Lo vi!  ¡Fue horrible!"',
    '5bd1543b': '"¡Buenas, colega!"',
    '6d96353e': '"¿Qué miras?"',
    'b0c9c359': '"Me llamo Dryas."', '265a8543': '"Ese es mi nombre."', 'c8d6a4b6': '"Adiós"',
    'f31b2964': '"Un comerciante honrado, según dicen."',
    '472c0c06': '"Dice la verdad: ¡es inocente!"',
    'f8e8e484': '"Halos es inocente: ¡fue esa cosa @horrible!"',
    'e87ecbc6': '"Al menos demostramos que Halos es inocente."',
    '4da8c045': '"Si ya me estás llevando ante Berossus."',
    'e9834ea0': '"Tengo que volver al trabajo."',
    'ecb86ea0': '"No creo."',
    'a9ad508b': '"Todo fue horrible, y ahora un cambiaformas.  Aquí las cosas van de mal en peor."',
    'c4682262': '"Lo vi yo mismo: fui a ver si Halos necesitaba algún trabajo cuando pasó."*"Estaba a punto de pasar por el pasadizo secreto cuando oí abrirse su puerta, así que me eché atrás."*"Pero pude mirar, y vi entrar a Cybele, de la Casa Attis."*"Lo siguiente que sé es que mueve la mano y él se desploma en el suelo."*"Y entonces se puso peor: de repente Cybele parece vacilar, toda rara, y lo siguiente que sé..."*"Bueno, pues había dos.  Dos Halos allí, y el falso sale por la puerta."*"Me dio tanto miedo, fuera lo que fuera aquello, que salí corriendo y me escondí aquí, en las alcantarillas."*"No fue hasta más tarde cuando conseguí, eh, \'oír por casualidad\' una conversación en la que hablaban del asesinato."*"Sabía que Halos no lo había hecho: fue esa cosa que cambia de forma."*"Quería contárselo a alguien, pero tenía demasiado miedo: ¿cómo iba a saber de quién fiarme?  Así que me escondí."',
    '4849efec': '*"¿Me protegerás?  ¿Al menos hasta que pueda contarle mi historia a Berossus?"',
    '9a34c06c': '"¡No!  ¡El cambiaformas me atrapará!"',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys, { '1862': { drya: 'drya', halo: 'halo' } });
Object.assign(DELV_TRANSLATION_ES.keys['*'], { gate: 'puer', anti: 'anti' });
Object.assign(DELV_TRANSLATION_ES.text['*'], { '4635bec4': '"El miembro de la banda de Eudoxus que capturamos está en nuestro calabozo, en espera de justicia."', '5dc96e78': 'Gracias', '387f5c57': 'Maza' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // the gate guard of Odemia
  '1864': {
    'c6faab0a': '¡Saludos a quien salvó a Ariadne!',
    'c1fbc826': '"¡Alto!  ¿Quién va?"',
    '413f5c57': '"Bueno, lo siento, pero Odemia está en estado de emergencia desde que secuestraron a la dama @Ariadne."',
    'e8fbf34a': '*"No se permite la entrada a nadie de fuera."',
    'c2f7d992': '"Ariadne es la esposa de @Philinus, jefe de la Casa @Nicander"*"La ha secuestrado el bandido @Eudoxus"',
    'f1ff9eda': '"Philinus es el jefe de la Casa @Nicander."',
    '53d08d95': '"Nicander es la Casa gobernante de Odemia."',
    '06c75cd1': '"Eudoxus es un villano asqueroso que ha secuestrado a Ariadne.  Dicen que tiene un campamento en los bosques del sudoeste."*"¡Ojalá se me permitiera llevarlo ante la justicia!"*"Al menos @capturamos a uno de su banda."',
    '4d741c64': '"Protejo Odemia."',
    '526613f7': '"Que te vaya bien.  Quizá tú puedas rescatar a Ariadne."',
    '3edc4f38': '"¿Te has enterado?  ¡Han encontrado muerto al bandido prisionero!"',
    'bad9ca65': '"Triste noticia, sí."',
    'd8948abd': '"¡Saludos a quien salvó a nuestra hermosa dama Ariadne!"',
    '058f630f': '"¡Dama Ariadne!  ¡Estáis a salvo!"*"Gracias de corazón por salvar a Ariadne.  ¡Por favor, entra en Odemia como nuestro huésped!"',
    'a9dee54b': '"¡No!  ¡No puede ser!  ¿Qué ha pasado?"*',
    '235270ed': '"Murió en combate con los bandidos."*',
    'c6ee5d2d': '"Al menos lo intentaste.  Es una triste noticia: deberías llevarle el cuerpo a Philinus"',
    'd3ff84cc': '"Como bien sabes, Odemia está en estado de emergencia hasta que devuelvan a Ariadne."',
    'cec35397': '"Nadie sabe qué pasó.  Simplemente lo encontraron muerto."',
    '437b40fb': '"Vigilo la @puerta de Odemia."',
    '7f8f83c9': '"Por supuesto.  Es lo menos que puedo hacer."',
  },
  // Thersites, Captain of the Guard in Odemia, and his lost ring
  '1865': {
    'a10d60a0': '¡Posadero!',
    '77507d2e': 'Ves a un hombre de aspecto bondadoso y honorable.',
    '9440526f': '"Encantado de conocerte: soy Thersites, como ya sabes, el Capitán de la Guardia"',
    'af57cccc': '"Por fin nos conocemos: soy Thersites, el Capitán de la Guardia aquí, en Odemia."',
    'ab98ea43': '"Es una pena lo que le pasó a Ariadne."',
    'f4b39bd1': '"Me alivia mucho que rescataran a Ariadne."',
    'c3a76798': '"¿Encontraste el anillo?"*',
    'bb8d8a1a': '"Sí, de hecho, sí.  Aquí tienes..."*Le das el anillo a Thersites.  Lo examina con cara de alivio.*',
    'f3ee79cc': '"Muchísimas gracias por esto..."*',
    '7084a84f': '"Sí, es cierto, Antiphus ha muerto."',
    '1528507c': '"Bueno, ¿qué te trae por aquí esta vez?"',
    '5dffdfa7': '"Soy Thersites."',
    '03d115a4': '"Ser Capitán de la Guardia es muy honorable, e intento hacer todo lo posible por estar a la altura del puesto."',
    '8e7fe8ae': '"Si no es mucha molestia, me preguntaba si podrías hacerme un favor."*"Bueno, me da un poco de vergüenza, pero hace poco perdí una reliquia familiar."*"Como Sacas parece fiarse de ti, si por casualidad la encuentras mientras investigas, te agradecería que me la devolvieras..."*"Es un anillo con la inscripción \'Para Hapede, con amor\'"',
    '303422e1': '"Eh, ¿te refieres a este anillo?"*Le das a Thersites el anillo que encontraste.  Lo examina con cara de alivio.*',
    '69e2a1dc': '"Muchísimas gracias por esto: es increíble..."*',
    '9021de00': '"Vuelve a visitarme."',
    'e1e3d081': '"Aunque he entrenado a mis hombres para usar la maza, yo prefiero el hacha, porque hace más daño."*',
    '78b96f5e': '=',
    '782ed72f': '"¡Los prisioneros que están a mi cargo no mueren así!  Mi honor lo exige, pero esto..."*"Seguramente no te has enterado, pero no es solo que muriera, sino cómo, y eso no lo entiendo."*"Murió ahogado.  Claro, el mar está justo al lado del calabozo, pero estaba bien encerrado: no había forma de entrar ni de salir."*"Era como si lo hubieran tirado al mar y luego lo hubieran sacado: hasta tenía la ropa mojada de agua de mar."',
    'c62e2ca7': '"Sí, tenemos en el calabozo a un prisionero de la banda de Eudoxus."',
    'c9d6fa47': '"Ya te di la llave: ¡no me digas que la has perdido!"',
    '3a5c95b1': '"¿Te envía Sacas a por la llave?  Muy bien, supongo que está en su derecho; ojalá puedas averiguar más que ella"',
    'fc25c84c': '"Ya no hace falta, ahora que ha muerto."',
    '604e25c2': '"¿No habías hablado ya con el prisionero?"',
    '5d3a31cc': '"Lo siento, pero las llaves de la ciudad son responsabilidad mía"',
    '75816b91': '"No puedo decir que @Antiphus no mereciera la muerte, pero solo tras un juicio como es debido."',
    '482cb2f3': '"Un asunto feo, ese.  Tenlo por seguro: ¡@Antiphus pagará!"',
    'd6a302a6': '"Con Antiphus y el resto de los bandidos muertos, me gustaría cerrar el caso, pero no puedo."',
    '51538d8a': '"Antiphus no ha dicho gran cosa útil sobre quién estaba detrás de todo esto en último término."',
    '19d780cc': '*"El instinto me dice que aquí hay algo más que un simple secuestro de unos bandidos."*"Si pudiéramos averiguar de dónde sale ese kesh, quizá averiguaríamos quién está detrás: no augura nada bueno."',
    '0f998291': 'Thersites mira un instante a Sacas, que asiente.',
    '99febdbb': '"No debería hablar, pero Sacas se fía de ti, así que..."',
    '5874ff1d': '*"Ese kesh es una cosa muy mala, por lo que tengo entendido, y supone una gran amenaza para todo el reino."*"Si la justicia de los magos falla, sin duda habrá caos en la tierra."*"Quien esté detrás de todo esto debe de estar loco: ¡destruiría toda nuestra sociedad por el poder!"',
    'b4e97a9f': '"Quizá otra persona pueda ayudarte."',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys, { '1864': { aria: 'aria', phil: 'phil' } });
Object.assign(DELV_TRANSLATION_ES.keys['*'], { cont: 'cont', must: 'most', morn: 'aman', bree: 'bris', orde: 'pedi', goat: 'cabr', chil: 'hijo,nino', pelo: 'pelo', alcm: 'alcm', bris: 'bris' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Glaucus of the North Shore Vineyard, whose wine turned sour
  '1866': {
    '0e6d3e91': 'Ves a un hombre agotado y hundido, con la mirada perdida.*',
    'c59509ca': '"Arruinado.  Estoy arruinado."',
    'f5468cc8': '"Soy Glaucus."',
    '89077ade': '"No puedo contratar nada de mis existencias, porque todas se han @perdido."',
    '7afba14b': '"Llevo la @finca del Viñedo de la Costa Norte: antes hacía el mejor @vino de Cythera"',
    'fdf4f0cd': '"Antes hacía el mejor de Cythera, pero todas mis existencias se han @perdido."*"Supongo que este año los beneficios se los lleva @Borus."',
    '9f95244b': '"Borus lleva el Viñedo del Sur: está entre Cademia y Kosha."*"Puede que seamos rivales, pero nos llevamos bastante bien."*"Espero que lo que pasó aquí no pase también allí: ¡sería una catástrofe!"',
    '383ff8e3': '"La cosecha de este año tiene buena pinta, pero no sé si podré hacer @vino..."',
    '3fcf77ee': '"No lo entiendo, pero todas mis existencias se han puesto @agrias, y también el @mosto de este año."',
    'ef2e01bc': '"El mosto es vino que fermenta: pasa la primera fermentación en grandes cubas."*"Luego el vino se pasa a urnas pequeñas mientras envejece."',
    '9b026c89': '"Agrio como el vinagre.  Ahora no vale un pimiento."*"No sé qué pasó: el vino puede agriarse, pero ¿el mosto?  Eso no pasa nunca."*"Un día, bien; al @amanecer siguiente, agrio.  Como por @magia."',
    'b1bc008a': '"Siempre lo recordaré: el olor del vino agriado..."*"Y, claro, el aire salado de una brisa de la costa."*"Mis uvas parecen crecerse con ese aire del mar, aunque parezca mentira."',
    '35514d83': '"Ahora que lo dices, no recuerdo tanto una brisa como el olor, pero no puedo estar seguro."*"Claro que la brisa del mar suele entrar de noche."',
    '53587a00': '"No tiene ningún sentido: el Magisterium es uno de mis mejores clientes."*"No les tengo más que respeto a los Magos, pero ¿qué otra cosa podría explicarlo?"',
  },
  // Borus and Briseis of the Southland Vineyard
  '1867': {
    '9f7e1c05': 'Ves a un hombre rechoncho, de cara redonda',
    '0fb685f5': '"¡Ah, me alegro de volver a verte!"',
    'c04e5515': '"Soy Borus, el Vinatero."',
    '11072651': '"No estoy sordo, ¿sabes?"',
    '6da3fe6f': '"Llevo el Viñedo del Sur."',
    '75167300': '"No es verdad.  Tú harás el vino, pero quien lleva esto soy yo."*',
    '52155e1b': '"Ah, sí.  Como señala mi mujer, yo solo soy el vinatero: ella se ocupa de todos los detalles."',
    'bb880662': '"El Viñedo del Sur hace el mejor vino que hay."',
    '858dd02f': '"Es una verdadera pena lo que pasó.  Solo espero que no pase aquí."*"Avísanos si descubres algo."',
    '731800d6': '"Glaucus es un buen hombre, pero su vino es de segunda, si me preguntas."',
    '316472f3': '"¿Entonces no te has enterado?"*',
    '56eebb48': '"¿Enterado de qué?"*',
    'a7dc829e': '"Todas sus existencias, incluido el mosto de este año, se han agriado."*',
    '31317437': '"¿Has oído eso, Bri?"*',
    '05757554': '"Claro que lo he oído: estoy aquí mismo.  ¿Han averiguado cómo pasó?"',
    '219856df': '"¡Eso es imposible!  ¿Cómo pasó?"',
    'f1b3b461': '"No, todavía nada."*',
    '8389ec24': '"Espero de verdad que, sea lo que sea, no se extienda: ¡sería un desastre!"*"La próxima vez que lo veas, dile que si puedo ayudar en algo, que me lo diga."*"Y tennos al tanto si averiguas algo, ¿quieres?"',
    '0c8e6b24': '"Mi encantadora Briseis y yo somos socios."',
    '7d1e46ab': '"¡Cuídate', '61423611': ', y cuéntanos si averiguas algo',
    '3946c173': '"Lo siento, tendrás que preguntar a otra persona."',
  },
  '1868': {
    '23468dfc': 'Ves a una mujer rechoncha, de cara redonda.',
    '98eca080': '"¡Ah, qué bien verte de nuevo!"',
    '2e593fa1': '"Te doy la bienvenida al Viñedo del Sur"',
    '2cd075b7': '"Soy Briseis."',
    '2646b16c': '"Con mi marido, Borus, llevo el Viñedo del Sur."*"En realidad, la mayor parte la llevo yo, y él se centra en el vino."',
    '1d916394': '"Borus es un maestro vinatero, y además un buen marido."',
    '91ce10b7': '"Me entristeció tu noticia; ojalá a nosotros no nos pase nada, sobre todo con el gran @pedido."',
    '3c671281': '"Glaucus es un buen hombre, pero no le llega a Borus a la suela del zapato haciendo vino."',
    '1124a430': '"No puedo contratar nada de mis existencias, porque la Casa Comana lo ha encargado todo."',
    'cecedca0': '"La Casa Comana nos ha encargado hace poco casi todas nuestras existencias disponibles, lo cual es estupendo para nosotros."',
    '1ca3a61e': '*"Claro que, con los problemas que ha tenido Glaucus, puede que resulte una especulación muy astuta."',
    'efc6e4fc': '"De eso tendrás que hablar con Borus: él es el vinatero."',
    '1dd0a675': '"Cuídate, ', 'b78f0bf9': 'jovencita."', '4401dae3': 'jovencito."',
    'b8623914': '"Lo siento; quizá Borus pueda ayudarte."',
  },
  // Pelops, a flax farmer
  '1869': {
    '0b65d31a': 'Ves a un hombre pobre pero de aspecto satisfecho.\n*"',
    '38b68bd5': '"Soy Pelops.  ', 'd5373af8': 'Ya nos conocemos."', '14ed4ed9': '¿Y tú cómo te llamas?"',
    'b40195ce': '"Encantado de conocerte."',
    'b8f8b4ec': '"Soy granjero: sobre todo cultivo @lino.  Mi @mujer se ocupa de las @cabras."',
    'aa79bc25': '"De eso tendrás que hablar con Alcmena..."',
    '4d5b8738': '"El lino es una planta cuyas fibras se usan para hacer hilo y, con él, tela."*"¿Te interesa comprar un fardo?  Solo cuesta 7 óbolos el fardo."',
    '933e4bda': '"Bueno, si cambias de idea, dímelo..."',
    'f4e4b739': '"Mi mujer, Alcmena, es todo un partido."',
    '3e58b3e6': '"Nuestro hijo Asteropaeus es un niño callado, pero la vida en la granja es solitaria."',
    '41eda470': '"Lo siento, mis conocimientos no van mucho más allá de esta granja."',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys, { '1866': { ruin: 'perd,ruin', viny: 'finc,vine' }, '1868': { boru: 'boru' } });
Object.assign(DELV_TRANSLATION_ES.keys['*'], { farm: 'gran', butt: 'mant', chee: 'ques', milk: 'lech', drun: 'borr' });
Object.assign(DELV_TRANSLATION_ES.text['*'], { 'b40195ce': '"Encantado de conocerte."' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Alcmena, Pelops's wife, and their son
  '186A': {
    '2eda3504': 'Ves a una mujer pobre pero de aspecto satisfecho."',
    '358806bd': '"Soy Alcmena', 'd2424b0b': ': ¿no te acuerdas?"', 'a67d39d2': '.  ¿Y tú eres?"',
    'b40195ce': '"Encantada de conocerte."',
    '31246a5b': '"Buena suerte, y ten cuidado."',
    '3ac5a836': '"El trabajo de una granjera nunca se acaba, pero yo me ocupo de las @cabras."',
    '43e4c8fd': '"Mi @marido hace la mayor parte del trabajo de la granja, aunque nuestro @hijo ayuda cuando puede."',
    'aeb62cbe': '"Mi marido, @Pelops, hace el trabajo pesado de la granja, como cosechar el @lino."',
    'ff8ba2f9': '"De eso tendrás que preguntarle a él."',
    '1d5233f6': '"Puede que no tengamos mucho, pero Pelops y yo nos tenemos el uno al otro."',
    '09608424': '"Asteropaeus es un buen chico, pero algo tímido."',
    '30b62a57': '"Hago @mantequilla y @queso con la @leche de cabra."',
    '5eee3cff': '"Ordeñar cabras es bastante sencillo, la verdad: pruébalo; debería haber un cubo vacío fuera, junto a los corrales."',
    '0a8f3a8a': '"Hacer mantequilla es solo cuestión de batir la leche de cabra: coge un cubo de leche de cabra y bátela en la mantequera."',
    'a5d92364': '"Hacer queso lleva bastante tiempo; ¿quizá quieras comprar un poco?  ¿Solo 4 óbolos?"',
    'dd4e1032': '"Quizá en otra ocasión."',
    '40d8b4b0': '"Somos gente sencilla, y de eso no sabemos mucho..."',
  },
  '186B': { '7eaa851f': 'Ves a un niño pequeño muy tímido, que se aparta cuando intentas hablarle.' },
  // Stentor, once Itanos's majordomo, who saw Pelagon die
  '186C': {
    '83e694d7': 'Ves a un hombre de ojos desorbitados, que parece mayor de lo que debería.*',
    'c71b34f4': '"¡He visto a Pelagon!  ¡Aquí, en Cademia!"*',
    'df1b3977': '"Más despacio, tranquilo.  Cuéntame qué pasó."*',
    '3037c1b5': '"Doblé una esquina, y allí estaba: Pelagon, o lo que sea.  Al menos él no me vio."*',
    '8dbafbad': '"¿Cuándo fue eso?"*',
    '988dbf59': '"Hace nada, el otro día; pues ahora que lo pienso, fue poco antes de que asesinaran a Opheltius."*"¿No crees que haya alguna relación?"',
    '1b8a4363': '"¿Qué quieres?"',
    'd3c86fe3': '"Soy Stentor."', '8b511ae7': '"Sí, ese soy yo."',
    'e39a2296': '"Antes era el mayordomo del juez Itanos, en Kosha.  Ahora hago trabajillos."',
    '4ade8a75': '"Sí, lo he conocido.  Te manda recuerdos."*',
    '9eefbb44': '"Era un buen hombre, pero tenía que irme de @Kosha."',
    '4926a6d9': '"También dijo que te habías olvidado esta red."*Le das la red a Stentor.*',
    '2e55cadd': '"Muchísimas gracias: era mi red favorita, pero no me veía capaz de volver allí a por ella."',
    'dc4fad9b': '"Supongo que te lo contó Itanos, pero no podía quedarme allí, no después de lo que le pasó a @Pelagon."',
    '8876a4ab': '"No me gusta hablar de eso."',
    '9d9cfc5a': '"Antes trabajaba para el juez Itanos.  Un hombre muy honorable."',
    'e57fc290': '"Como trabajaba para un Mago, me mantenía al margen de la política, pero Canachus era un hombre ambicioso, aunque honorable."*"Fue una pena que muriera."',
    '337ce17e': '"Sí, reconozco que se sabe que le doy al vino de vez en cuando..."*"¡Pero sé lo que vi!"',
    'ed0f033e': '"Sé que lo vi.  Es imposible que me equivocara.  Era Pelagon, seguro."',
    '3e4005a1': '"Pelagon y yo éramos buenos amigos.  Sigue siendo el mayordomo de la Casa Comana."*"Lo único, y sé que no me vas a creer, es que lleva muerto más de cuatro años."*',
    '4787e5dc': '"¿Muerto?"*',
    '93a932e0': '"Sí.  Muerto.  Lo vi morir.  Estábamos pescando una tarde cuando, de la nada, ¡zas!"*"Un tentáculo de Scylla salió del agua, agarró a Pelagon y lo arrastró al fondo."*"No pude hacer nada.  Luchó contra él, pero no sirvió de nada."*"Hubo unas burbujas y luego sangre, y eso fue todo: ni cuerpo ni nada."*"Así que volví corriendo al pueblo a contarle a la gente lo que había pasado.  Se lo conté a Itanos, y luego fui a contárselo a Canachus."*"Cuando llegué a la Sala de Canachus, allí estaba él, o lo que fuera aquello."*"Estaba ahí sentado como si no hubiera pasado nada.  ¡Pero sé que lo vi morir!"*Stentor hunde la cabeza entre las manos y se estremece.*"No sé qué tomó la forma de Pelagon; lo único que sé es que aquello no era Pelagon."*"No pude soportarlo más, así que volví a ver a Itanos y le dije que tenía que irme."*"Aquí sigo desde entonces."',
    'e97063d5': '"Era un buen amigo mío de Kosha."',
    '4dacad2c': '"No sé."',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys, { '186A': { husb: 'mari,espo', son: 'hijo' } });
Object.assign(DELV_TRANSLATION_ES.keys['*'], { bard: 'bard', song: 'canc,escuch', parr: 'loro', lute: 'laud', lyre: 'lira', comb: 'comb', emes: 'emes', thie: 'robo,ladr', gamb: 'jueg,apue', trap: 'tram', bare: 'mano', neop: 'neop', trav: 'viaj', orga: 'orga', ente: 'divi', tlep: 'tlep', axe: 'hach', mace: 'maza' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Demodocus the Bard, who knows who teaches what
  '186D': {
    'fea73f23': 'Ves a un hombre jovial, de pelo rizado y cada vez más escaso.',
    '5528a45c': '"¡Ah!  Tú debes de ser quien acaba de llegar.  He oído rumores de que Alaric te había convocado..."*"Si son ciertos los @rumores que oigo, no has llegado demasiado pronto.  Hay muchas cosas que van mal, y Alaric parece incapaz de hacerles frente."*"Oh, perdona, permíteme que me presente.  Soy Demodocus, el Bardo."',
    '246abec6': '"¡Ah!  Tú debes de ser esa gran figura heroica', 'a6e99921': '',
    '06debb26': ' de la que tanto he oído hablar!"*"Soy Demodocus, el Bardo: encantado de conocerte."',
    'b0c7a908': '"Qué bien volver a encontrarnos.  Pasan cosas @raras en la tierra..."',
    'bca670df': '"Qué bien volver a encontrarnos.  Quizá me cuentes tu historia..."',
    '56ab9a17': '"Soy Demodocus: quizá hayas oído hablar de mí."',
    'ef67e68c': '"Hago leyendas de las locuras del hombre, y @divierto a la gente con baladas y fábulas."',
    'bd421b26': '"He oído que la mina de hierro de la Casa Attis está encantada: ¡eso sí que es raro!"*"¿Quizá deberías ir a hacerle una visita a la matrona Thuria en Cademia?"',
    '510d7094': '"Vivimos tiempos raros, eso seguro."',
    '18fe650c': '"Aunque no he estado allí últimamente, un amigo me contó que algo va muy mal en @Catamarca."*"La gente se está poniendo enferma, e incluso ha muerto alguno.  Puede que sea solo un rumor, pero el instinto me dice que ahí podría empezar una gran historia."',
    '5aceeab9': '"Hay rumores por todas partes, pero en mi experiencia casi siempre son falsos."',
    '4b983355': '"Bueno, aunque seguro que te esperan grandes historias que vivir, yo tengo compromisos para actuar."*"Seguro que volveremos a vernos, de todos modos."',
    'da8e88e5': '"Lo siento, pero aprender a componer canciones lleva años: tendrás que buscar en otra parte."*"Si hay algo en concreto que te gustaría estudiar, quizá sepa a quién preguntar..."',
    'a5c36ed4': '"Soy Demodocus, es cierto."',
    '7f9999d8': '"¿Loros?  Me temo que estás confundido: demasiado tiempo al sol."',
    'c77b116b': '"La Casa Comana no ha sido la misma desde que murió el viejo @Canachus."',
    'f51274cc': '"No voy a Kosha tanto como cuando gobernaba el viejo @Canachus."',
    '9e5ee550': '"Canachus era un buen hombre, mejor que todos sus hijos juntos.  Y además era muy admirador mío."*"Recuerdo su canción mía favorita: era así..."',
    '321e25d2': 'Toca las notas PHJMD.*"Claro que eso es con esta lira: para tocarla bien, hace falta una flauta de Pan."*"Por desgracia, ya nadie hace flautas de Pan que den todas esas notas, aunque quizá alguien todavía tenga una por ahí."',
    '26fc60fa': '"Deberías preguntar por ahí: quizá algún Anciano de alguna Casa todavía tenga una vieja por ahí tirada."',
    '7f4b3e6f': '"Soy un maestro de la flauta de Pan, es cierto."',
    '9534ed6a': '"Bah, esos laúdes modernos: no suenan bien."',
    '50e4a5e3': '"La lira es mi instrumento preferido: ligera, y aun así versátil, con un sonido pleno."',
    'bb4b6f4d': '"¿Te vas a alguna aventura?  Bueno, algún día tendrás que contármelas todas para que haga una balada..."',
    'cb897890': '"Oh, pues sí, viajo a menudo de ciudad en ciudad, tocando en las @posadas para deleite de los clientes, y a veces tengo el honor de actuar para el Rey de la Tierra."*"Últimamente vengo a tocar para el Rey de la Tierra más a menudo, para levantar el ánimo de @Alaric."',
    'b0a65dcd': '"La mejor gente no suele frecuentarlas, pero la mayoría es bastante decente, y las charlas ociosas a menudo son muy informativas."*"Esta vida me va bien, pese a tanto @viajar."',
    '64a6dd3b': '"Paso mucho tiempo viajando, y te daré este consejo: viaja de noche solo con los ojos bien abiertos y la espada desenvainada."*"Hay @bandidos por ahí, campando a sus anchas por la tierra, ahora que el poder de @Alaric para detenerlos se ha debilitado."',
    'f35ceb16': '"Mala gente.  Cythera era una tierra pacífica..."*"No sé qué hay detrás de su aparición, si son solo buitres que se dan un festín con la tierra en decadencia, o un complot más @organizado."',
    '3f967802': '"No lo sé con certeza, pero desde luego es posible que haya fuerzas ocultas en juego..."*"...o podría ser solo otra especie de @plaga que se abate sobre la tierra."',
    '7804d935': '"Bueno, hay @rumores..."',
    '6b9e9f57': '"La plaga de Catamarca fue de lo más extraña, ¿no?"',
    'b6c72436': '"Por desgracia, Alaric no está bien, y la @tierra no está bien con él."*"Hago lo que puedo para que se sienta mejor con mis artes del canto, pero quizá tú puedas hacer @mucho más..."',
    'aa7efd66': '"Cythera fue en tiempos una tierra orgullosa, con pocos @delitos y hermosos pueblos prósperos, desde la poderosa @Cademia hasta el pintoresco pueblo de Odemia"',
    'ee2180b6': '"Con los @bandidos rondando por ahí, hay mucha fechoría en marcha, pero la gente honrada de los pueblos no aprueba esos robos y saqueos."',
    'd5a7203e': '"Alaric se ha ido debilitando, y aún se agotó más al convocarte aquí."*"Mucho depende de ti.  Espero cantar tu historia algún día."',
    'ecb7b58d': '"Los metecos son seres míticos de los que no sé mucho más que su nombre, pero esas cosas son lo mejor para una canción."*"¿Te gustaría @escucharla?"',
    '79fb187d': '"Ah, quieres oír una canción, entonces... bueno, allá vamos..."*Demodocus empieza a cantar, pero las palabras parecen escapársete.*En su lugar, se te llena la mente de imágenes de la Tierra y del Mar, y de la batalla constante entre esos dos elementos.',
    '654cd9e7': '"Ake, en Odemia, es una maestra tejedora."',
    'c8aabd24': '"El viejo Hadrian ha entrenado a muchos guerreros."',
    '85e71171': '"Aunque muchos posaderos saben cocinar, ninguno se puede comparar con Emesa, la cocinera de Alaric."',
    'a22e5904': '"Quien quiera aprender el arte de la magia debe tener el visto bueno del director Lindus, en el Magisterium de Pnyx."',
    '2cf80fdf': '"Nadie sabe de pesca como el viejo Tlepolemus: las costas de Odemia son ricas en peces, y él se sabe todos los trucos."',
    '70b573cc': '"Thersites, jefe de la Guardia de Odemia, es el maestro del Hacha, aunque entrena a sus hombres en el uso de la Maza."',
    'c409184e': '"El Gremio de Rateros de Cademia alberga muchos conocimientos poco sociables, y ahí lo dejo."',
    '3b06b644': '"El viejo Meleager es muy astuto: sabe muchas cosas sobre sobrevivir y no perder la cabeza."',
    'ec91f6f0': '"Muchos tenderos saben convencer a sus clientes de que se desprendan de sus óbolos, pero ninguno era tan bueno como Neoptolemus."*"Aunque ahora está un poco loco, y cuenta las historias más aburridas que he oído nunca, ¡y eso es mucho decir!"',
    'dde359a0': '"Creo que una vez escribí una canción sobre eso, pero ahora no son más que ecos del pasado."',
  },
});
Object.assign(DELV_TRANSLATION_ES.keys, { '186D': { inns: 'posa', stra: 'raro,rara', more: 'much,mas', cana: 'cana', hadr: 'hadr', ake: 'ake', lind: 'lind' } });
Object.assign(DELV_TRANSLATION_ES.text['*'], {
  'eaeb07d5': 'Ves a un estudiante estresado.\n*', 'd855c92a': 'Ves a una estudiante estresada.\n*',
  'b8761e22': '"Soy estudiante: espero estudiar curación."', '8500d5ec': '"Es mi mejor amigo."',
});
// the students of the Magisterium
Object.assign(DELV_TRANSLATION_ES.text, {
  '186E': { '37f09570': '"Me llamo Thrasymedes."' },
  '186F': { '048b1c3e': '"Me llamo Protesilaus."' },
  '1870': { '3147b69b': '"Me llamo Menelaus."', 'f3ff818f': '"Soy estudiante: me especializo en alquimia."' },
  '1871': { '7a3151cd': '"Me llamo Lycaon."', '2f0b014c': '"Soy estudiante: todavía no he decidido qué quiero estudiar."' },
  '1872': { '8b86d7c7': '"Me llamo Peleus."', 'e2ed6c93': '"Soy estudiante: espero estudiar magia rúnica."' },
  '1873': { '7ecf9de2': '"Me llamo Peisander."', 'c2b3e126': '"Solo soy un estudiante: todo esto me supera un poco."' },
  '1874': { 'ad986fbc': '"Me llamo Danae."', '8fb8d271': '"Soy estudiante, y me especializo en curación."' },
  '1875': {
    '27ec5d32': '"Me llamo Semele."',
    'a4589a96': '"Eioneus es mi hermano mayor: estamos muy orgullosos de él, con su trabajo en las armas mágicas."*"Hace tiempo que no sé nada de él, pero la última vez me dijo que había encontrado una cueva en las montañas que llevaba a un campo de lava."*"Dijo que estaba justo al sudoeste de donde se juntan los dos afluentes del río Styx."*"Si lo ves, dile que le mando saludos."',
    '00d81e57': '"Soy estudiante: espero llegar a ser investigadora."',
  },
  '1876': { '120aa05e': '"Me llamo Alcyone."', 'c6b8d300': '"Soy estudiante."' },
  '1877': { '2062ef44': '"Me llamo Clytemnestra."', '3433dfc0': '"Soy estudiante: me he estado especializando en Magia Rúnica."' },
});
Object.assign(DELV_TRANSLATION_ES.keys['*'], { thra: 'thra', prot: 'prot', mene: 'mene', lyca: 'lyca', pele: 'pele', peis: 'peis', dana: 'dana', seme: 'seme', alcy: 'alcy', clyt: 'clyt', eion: 'eion' });
Object.assign(DELV_TRANSLATION_ES.keys['*'], { heir: 'here', esse: 'esen', form: 'form,camb', corr: 'corr', maay: 'maay', seld: 'seld', jhia: 'jhia' });
Object.assign(DELV_TRANSLATION_ES.text, {
  // Sabinate, heir of the Seldane, who says "we"
  '1878': {
    '471f63b2': '"¡Es asombroso!  ¡Es un Seldane vivo!  ¡Nunca pensé que llegaría a conocer a uno!"*',
    '39ef3e85': '"¡Llevas la @esencia de la corrupción!  ¡Cuidado!"*',
    '4c937b88': '"No: tus caminos no son puros.  Tu misma presencia nos ofende.  Vete."',
    '3120b144': '"Como nos has ayudado, así te ayudamos.  Mucho hay que saber de los @males de Alaric."',
    '2e8aa512': '"A su debido tiempo has venido a nosotros.  Somos Sabinate, heredera de los @Seldane."',
    'ce870a96': '"Somos Sabinate, heredera de los @Seldane."',
    'e182a768': '"No tenemos hijo."',
    '820ab17a': '"Esta es nuestra tierra.  Como son sus @males, así son los nuestros."',
    '40049432': '"El lazo de la tierra es el lazo de los Seldane.  Como la tierra es inmortal, así lo son los Seldane."*"La sangre de los mortales corre por las venas de Alaric.  La sangre mortal es demasiado fina para el lazo de la tierra."*"Como el agua que corre deprisa arrastra la tierra, lo mismo hará el lazo de la tierra."*"Alaric no puede resistir: Alaric solo puede ser arrastrado."*"Como se endereza el arroyo para que el agua fluya, así debe ser con Alaric."*"Pero solo todo el poder de la @Crolna puede lograrlo."*"Solo con todo el poder puede Alaric mantener el lazo de la tierra sin ser arrastrado."*"Una última cosa: recuérdala bien.  Caminar de nuevo, los muertos no pueden."',
    '3fbe479e': '"Los males de tu Alaric marchan con los nuestros.  Quizá nuestra @ayuda sea tu ayuda."',
    '4898ae1a': '"Nuestra Enemiga es la Corrupción.  Como nosotros, pero no nosotros, como el Mar lo es para la Tierra."*"Para ellos no sois más que herramientas.  Para nosotros, esto importa poco; para vosotros, mucho."*"No te fíes de tus sentidos, pues ellos cambian de forma con la facilidad con que tú cambias de ropa."*"Cuidado con los muertos que caminan: por eso los conocerás a ellos y a sus aliados."',
    '38ef0730': '"Ese conocimiento está más allá de ti."',
    'dd5b671a': '"La esencia de la corrupción mancha la Crolna.  No la uses, no sea que arriesgues destruir todo aquello por lo que has luchado."*"La Crolna debe ser purificada.  Esto no podemos hacerlo nosotros: debe hacerlo un humano, que no esté ligado a la tierra."*',
    'a74241e6': '"Te hemos dado las esporas de la tierra: más no podemos ayudar."',
    'ec5656a8': '"Para eliminar el poder del Mar, solo podemos ayudar algo, quizá."*"Toma esto, esporas de la Tierra.  Si puedes romper la mancha, ellas la neutralizarán."*Sabinate te da una seta de forma extraña.\n',
    '807e38fb': '"Como fluye el Mar, así fluye la forma de los del Mar.  Cambiante, y aun así del Mar."',
    'fe650a4d': '"El poder es la Crolna.  Nuestro @Enemigo la volvió contra nosotros para nuestra caída."*"Todo el poder de la Crolna resolverá tus problemas, o causará tu caída."*"Peligroso es el poder.  Así es en la Crolna."',
    'fb954dc8': '"Tú nos ayudarás, nosotros te ayudaremos.  Libera Maayti de la corrupción."',
    '9b73d5a0': '"¿Nos ayudarías, para así poder ayudarte a ti?"',
    'e9fa18e3': '"Entonces el fracaso será sin duda tuyo."',
    '0909c480': '"Durante 120 eternidades nuestra fue @Maayti, ciudad de la Verdad, hasta que nuestro enemigo nos expulsó."*"Un fragmento de @Crolna, como el que llevas, pero mayor, se volvió hacia el mal, y convivir con la corrupción no pudimos."*"Lo sellamos dentro, para que la corrupción no se extendiera.  Las puertas se sellaron con dos llaves."*"Por tu mano has eliminado la corrupción de una parte de la Crolna.  Querríamos que hicieras lo mismo."*"Necesitas aprender nuestra lengua; haremos que así sea."*Los ojos de Sabinate parecen atravesarte el cráneo, y luego el efecto desaparece.*',
    'd3205081': '"Para abrir las puertas, también necesitas las dos llaves.  Aquí tienes la llave del poste izquierdo."*Sabinate te da un medio disco de aspecto extraño.',
    'c3c8bad1': '*"Cuando dejamos Maayti, el que era nuestro hijo recibió la otra."*"El que era nuestro hijo ya no es uno de nosotros, y está cerrado para nosotros."*"Ya no vemos a ese: tendrás que usar tus propios ojos para encontrarlo."*',
    '83311e37': '"Que el viento de la Verdad esté de tu parte."',
    '2fac1fa1': '"Lo que llamas el Libro de Zafiro del Fundamento está con nosotros."*"La que es Unhayt tiene su posesión."',
    '73deb195': '"¿Cuál es entonces tu condición?"',
  },
});
