  '1A0D': { '1bc7eec6': 'Soporiferidad', 'f8092343': 'Este conjuro sume al objetivo en un sueño profundo.\n' },
  '1A0E': { '9202e654': 'Aterrorización', '7b459987': 'Este conjuro infunde un miedo instantáneo al objetivo.\n' },
