/* ---- rooms: what is seen on looking at one, and what a companion says ---- */

// Each is its own room's, and several rooms share one; they are kept with
// what is the same everywhere, as none of them means two things.
Object.assign(DELV_TRANSLATION_ES.text['*'], {
  '4306726c': 'Lo más interesante de esta sala es el suelo de ónice negro con un triángulo luminoso en el centro, rodeado por un banco alto.\n',
  '53aac789': 'Esta habitación parece bastante espartana, pero la cama tiene pinta de ser cómoda.\n',
  'd3263f64': 'La biblioteca huele a libros y pergaminos mohosos.  Estanterías llenas de libros, papeles y pergaminos cubren las paredes.\n',
  '64e1c41c': 'Con sus columnas y su trono, un aire de poder y de orden llena la sala.\n',
  'ab035596': 'El olor a pan recién hecho llena la cocina, igual que el calor del fogón.\n',
  '386fc7ae': 'Esta habitación abarrotada da a la vez una sensación de desorden absoluto y de orden completo.\n',
  'dce53389': 'Estás en un cuartel, con varias filas de camas.\n',
  '872c72b6': 'Esta habitación pequeña está repleta de víveres.\n',
  'bf374b41': 'Una sola mesa grande domina esta sala, con varias sillas alrededor.\n',
  '47c0b94f': 'Esta habitación es un dormitorio grande y limpio, con alfombra en el suelo y un escritorio pequeño en el centro.\n',
  '28da4808': 'Está claro que esto es una especie de sala de investigación privada, con las paredes cubiertas por una estantería y un banco con más libros.\n',
  '21cb36c3': 'Esta zona te transmite una sensación de poder, algo que casi se puede saborear en el aire.  Los dos estanques parecen llenos de un agua que casi chispea de energía.\n',
  'ac59b37c': 'Domina esta sala un estanque central, cuya agua parece girar en el sentido de las agujas del reloj, aunque no se ve de dónde viene la corriente.\n',
  'cf993e04': 'De repente, la tierra empieza a temblar, y se oye un estruendo al sur de ti.\n',
  '31b301d2': '¡Qué ha sido eso!',
  '0eafa03f': 'Se desconoce la finalidad original de esta sala, pero parece que un terremoto derrumbó su esquina nordeste y dejó paso a una especie de cueva.  Ahora se usa de almacén.\n',
  'dfc03725': 'Parece que esta zona era una especie de zona de entrenamiento, pero un derrumbe reciente ha hundido parte de las paredes.\n',
  '9d8ad2c2': '¡Vaya!  ¡Mira qué destrozos!',
  'f410ee33': 'El centro de esta sala es un gran abismo, cruzado por un solo puente estrecho.  El abismo parece no tener fondo, y en él se ven una especie de estrellas.\n',
  '7f833a90': 'Has encontrado una especie de túnel secreto junto a la pared de la Sala del Rey de la Tierra.\n',
  '3f942d23': '¡Un pasadizo secreto!',
  '887d911b': 'Este es el cuartel de la guardia del pueblo.  La sala está llena de catres.\n',
  '77caae64': 'Estás en la casa de la Casa Nicander.  Es pequeña, pero limpia y bien ordenada.\n',
  '78d79aad': 'Estás en la casa particular de alguien que debe de ser pescador, porque se nota un leve olor a pescado y a mar.\n',
  '5b307f5a': 'Ves una sala desnuda, con el olor acre del vino viejo en el aire.\n',
  '564b5361': 'Es una pequeña tienda de hilo, con una cama para su dueña en un rincón.  El aire huele a lino, y hay una rueca y fardos de lino en un rincón.\n',
  '32827b20': 'Ves una tienda que pertenece a una tejedora, y lo que más destaca en la sala son dos telares.\n',
  'a9d37458': 'El suelo de tierra de la zona, junto con el calor de la fragua cercana, hacen el ambiente sucio, polvoriento y caluroso.\n',
  'b4fcdf8e': 'La casa está sorprendentemente limpia y fresca, sobre todo teniendo en cuenta la fragua que hay justo fuera.\n',
  '907b9957': 'La sala está oscura y algo húmeda, por la cercanía de la orilla del mar.  En la pared norte hay dos puertas de celda cerradas con llave y con barrotes.\n',
  'adbc2278': '¡No me metáis ahí!',
  'f2b9a5b2': 'Es la cocina de la fortaleza del pueblo, con su fogón y sus utensilios.  En el lado sur de la sala hay una cama y efectos personales.\n',
  'ca7ea7bf': 'Domina la sala una gran mesa central rodeada de sillas.  Es evidente que las decisiones más importantes sobre el pueblo de Odemia se toman en esta sala.\n',
  'ac333d60': 'Estos son los aposentos privados de Sacas.  En el centro de la sala hay una mesita, con un cubierto puesto.\n',
  '0777b8bf': 'Estás en una sala alfombrada que sin duda pertenece a un mago.  La pared norte está cubierta de libros, con un escritorio en la este y un banco en la oeste.\n',
  'cd89391d': 'Esta sala está oscura y seca, y se usa para almacenar diversos bienes, probablemente por si hay alguna emergencia en el pueblo.\n',
  '4ccb149a': 'Esta gran taberna huele a buena comida y a vino rancio, algo que una buena limpieza seguramente arreglaría.\n',
  'd100272d': 'Es un dormitorio común, pequeño y abarrotado, con varias camas.\n',
  'cd701bfc': 'La cocina está bien ordenada y limpia, a diferencia de la taberna de fuera.  El calor de un asado al fuego se suma al del fogón, y hace un calor casi insoportable.\n',
  'e8eeac31': 'Esta sala es espartana y extremadamente limpia y ordenada: está claro que son los aposentos de un militar.\n',
  'ef7446de': 'Es una granja abandonada, al parecer vacía desde hace tiempo.  En el centro de la sala quedan los restos de una hoguera, y hay telarañas en los rincones.\n',
  '3dc4afae': 'Esta habitación más pequeña de la granja abandonada quizá se usó de almacén, aunque a estas alturas es difícil saberlo.\n',
  'f5403e68': 'Esta habitación diminuta de la granja se distingue por la trampilla de su esquina noroeste.\n',
  '3e716d31': 'Estás en una sala de tierra húmeda y de techo bajo.  Salvo por la luz de la trampilla de arriba, está completamente a oscuras.\n',
  '8b0990e7': '¡Mira!  ¡Un camino al NO!',
  '3904d172': 'Esta zona está sembrada de lápidas y tumbas, algunas claramente muy recientes, otras antiguas.\n',
  '145581ea': 'Estás en el gran salón común de una taberna.  De la cocina llega el olor de la comida recién hecha, y también el del vino.\n',
  '4202c8f1': 'Estás en la gran cocina de la posada.  Un asado se hace al fuego vivo en el lado norte, y en un rincón hay una cama, a todas luces del dueño.\n',
  'd3698666': 'Un pasillo estrecho y oscuro sale del salón común de la taberna y lleva a una serie de habitaciones privadas pequeñas.\n',
  'c1eef77f': 'Estás en una pequeña sala de reuniones del pueblo.  Pero, a juzgar por la capa de polvo que lo cubre todo, aquí no ha habido ninguna reunión hace tiempo.\n',
  '921867bc': 'Estás en una especie de tiendecita, quizá la casa de un mercader o de un comerciante.\n',
  '6ed259d7': 'Estás en un pequeño patio.  En el centro hay una fuente que borbotea, y la pared norte tiene ventanas que dan al patio.\n',
  '86503b13': 'Esta sala está limpia y ordenada, y tiene un aspecto muy profesional.\n',
  '1d3448e5': 'Estás en un comedor sencillo pero formal.  Las ventanas de la pared sur dan al patio y a su fuente.\n',
  '12a6879a': 'Estás en una cocina pequeña.  Está sucia y desordenada, con olor a carne pasada.  Es como si la usara alguien con poca experiencia en la cocina.\n',
  'ef971c14': 'Este dormitorio pequeño parece vacío y abandonado.  Todo está cubierto por una fina capa de polvo, y un olor a moho y a cerrado llena la habitación.\n',
  '775c3e37': 'La habitación es espartana y sencilla, pero aun así parece que alguien lleva bastante tiempo viviendo en ella.\n',
  '6ef87072': 'Estás en una sala central, con puertas y arcos en todas direcciones.  Lo principal de la sala, además de los ricos dibujos del suelo de mármol, es una fuente sencilla con su estanque.\n',
  'e6046c1a': 'Está claro que esta es la estancia principal de la fortaleza, que sirve a la vez de despacho privado y de dormitorio.\n',
  '0f2c6fb9': 'Es un pequeño vestidor privado.  Una cómoda sencilla ocupa la mitad de la pared norte.\n',
  'a3b62a06': 'Estás en un pequeño pasadizo secreto.  El polvo cubre en abundancia el suelo y la trampilla de la mitad oeste de la sala: es evidente que nadie lo ha tocado en siglos.  Hay en el aire un ligero olor a humedad, a moho y a tierra.\n',
  '9305b8f6': 'Esta sala es el centro de la fortaleza.  Una mesa central sirve para las reuniones.  Una sola silla grande en el extremo sur de la mesa es, sin duda, para quien dirige el lugar.\n',
  '702d90a1': 'Estás en la cocina limpia y bien cuidada de la fortaleza.\n',
  '3dcd7f43': 'Estás en una especie de cabaña pequeña, con un estanque en la esquina sudeste de la sala.\n',
  '7a786125': 'Estás en una especie de cabaña pequeña, con un estanque en la esquina sudeste de la sala.  Parece que alguien vive en esta cabaña.\n',
});
Object.assign(DELV_TRANSLATION_ES.text['*'], {
  '07feca27': 'Estás en un gran salón lleno de columnas, que va de norte a sur.  También hay un tramo de escaleras de mármol que sube.\n',
  '1518ec42': 'Estás en una sala con suelo de mármol azul, sin duda una sala de reuniones importante.  En la mitad oeste del salón, sobre una tarima, una mesa con cinco sillas enormes ocupa casi toda la sala.\n',
  'c2a35f3f': 'Estás en una tiendecita, con un mostrador de madera y dos sillas cerca.  Una cortina da a una trastienda detrás del mostrador.\n',
  '0bb9ab3f': 'Estás en las habitaciones privadas de detrás de la tienda de provisiones.  Son a la vez dormitorio, despacho y almacén.\n',
  'd0fa6aa4': 'Estás en un gran salón común.  El olor a comida y a vino llena el aire.\n',
  '75009dbc': 'Estás en lo que claramente es la cocina del salón común del este.  En el centro de la pared oeste hay dos grandes fogones, y en la pared este hay un mostrador gastado y manchado.\n',
  '448f8145': 'Has entrado en el cuartel del Magisterium, lleno de catres sencillos para los guardias que protegen este lugar.\n',
  'e6b0a332': 'Estás en los aposentos privados de uno de los Magos.  Están bien iluminados y limpios, lo que les da un aire abierto y acogedor.\n',
  '71f8e73b': 'Estás en los aposentos privados de uno de los Magos.  Son sencillos y espartanos, aunque los suaviza un poco una sencilla planta verde.\n',
  '014b0929': 'Estás en lo que seguramente serían los aposentos de uno de los Magos, pero ahora están vacíos y sin usar.\n',
  '9983ccfe': 'Estás en los aposentos privados de uno de los Magos.  Una estatua sencilla marca el ambiente de la sala, de una elegancia informal.\n',
  'd9113b1a': 'Estás en los aposentos privados de uno de los Magos, pero a primera vista parecen vacíos y sin usar, aunque está claro que alguien vive aquí.  Es evidente que no pasa aquí nada de tiempo.\n',
  '6fb51979': 'Estás en los aposentos privados de uno de los Magos, distintos del resto por la pesada puerta de metal y por una segunda salida al sur.  También parecen más cómodos que los demás.\n',
  'cdd8dbde': 'Estás en un lugar de lo más notable del Magisterium.  Pese a estar completamente bajo techo, sin ninguna fuente visible de luz exterior, estás en un jardín bien cuidado.  Lo decoran árboles y plantas sencillos, y un césped rico y bien recortado cubre el suelo.  Cuatro columnas, una fuente y un estanque le dan un toque elegante.\n',
  'c17d607e': 'Estás en una pequeña sala que es a la vez aula y laboratorio.  Sobre los mostradores hay un equipo extraño, y dos filas de sillas ocupan el centro de la sala.\n',
  '584f5c68': 'Estás en una especie de aula grande.  Está llena de sillas, pero por lo demás no tiene nada de particular.\n',
  '400d1b27': 'Estás en un aula mediana, llena de sillas.  También hay una salida hacia el norte.\n',
  '77600909': 'Parece una especie de almacén, donde se guardan pupitres y sillas de sobra.\n',
  '08de58f1': 'Parece que esta sala sirve para que los guardias no pierdan la práctica.\n',
  'ad1a9515': 'Estás en un gran pasillo principal, con columnas por el centro.  A lo largo del pasillo se ven, a distintas distancias, pesadas puertas de metal.\n',
  '3da22c7c': 'Estás en una gran biblioteca.  Estanterías y mesas con tomos extraños cubren todos los lados de las distintas paredes.\n',
  'c0b1686c': 'Estás en una pequeña sala de la biblioteca, abarrotada de estanterías, con tres tomos extraños sobre una mesa junto a la pared oeste.\n',
  '8b88e5a7': 'Estás en una sala más pequeña de la biblioteca.  Seis tomos descansan sobre una mesa junto a la pared sur.\n',
  'bcc5ec25': 'Estás en una sala pequeña y estrecha de la biblioteca.  Cuatro tomos descansan sobre la mesa junto a la pared este.\n',
  'c6145e2e': 'Estás en una sala muy pequeña de la biblioteca.  Tres tomos descansan sobre la mesa junto a la pared este.\n',
  '25e55845': 'Estás en una sala más pequeña de la biblioteca, con estanterías en las paredes y una mesa junto a la pared sur.  Hay cinco tomos sobre la mesa.\n',
  'bf6a7adf': 'Estás en lo que parece una especie de sala de estudio.  Una mesita en el centro está rodeada de sillas, y hay más sillas junto a las paredes.\n',
  '8f632960': 'Esto fue en tiempos una especie de casa de guardia, o cuerpo de guardia, aunque ahora está claro que a nadie le preocupa proteger el perímetro.\n',
  '11b56586': 'La sala está caliente, y el olor a humo, a metal trabajado y a sudor llena el aire.\n',
  '56d50857': '¡Esto huele a dinero!',
  '0754b989': 'Estás en el gran salón del castillo.  En el extremo norte de la sala hay una sola silla grande, con sillas menores a los lados.  Consigue combinar lo opulento con lo funcional.\n',
  '57efe235': 'Es un dormitorio más pequeño del castillo.  Está claro que todavía se usa.\n',
  'cc031080': 'Un dormitorio grande del castillo, cubierto por una fina capa de polvo: es evidente que nadie lo ha ocupado últimamente.\n',
  '3ebd33bc': 'Es evidente que esta es la \'estancia principal\' del castillo, aunque con la capa de polvo que lo cubre todo, también es evidente que nadie la ha habitado últimamente.\n',
  '4d38d064': 'El comedor formal del castillo es sencillo y elegante, con una mesa sobre una tarima y un espacio abierto al sur.\n',
  '36fdc35d': 'La cocina del castillo huele a pan recién hecho, a sabrosas carnes asadas y a otras comidas desconocidas.\n',
  'fe698ce7': 'La zona privada que da a la cocina es el hogar de dos personas, probablemente el servicio del castillo.\n',
  '8c874ad6': 'Estás en una sala sencilla con suelo de madera.  Seguramente no es su finalidad original, pero ahora sirve de dormitorio a alguien.\n',
  '3b671705': 'Esta casa de una sola habitación hace a la vez de vivienda y de lugar de trabajo para un mercader.\n',
  'e81ec266': 'Esta casa de una sola habitación hace a la vez de vivienda y de lugar de trabajo para un sastre.\n',
  'b9dc0fef': 'Oscura y desagradable, esta fortaleza sirve de prisión para quienes transgreden la ley de la tierra.\n',
  '924b9b3c': 'Estás en una casa particular ordenada, con cierto aroma a especias en el aire, quizá canela.',
  '837ea017': '  A través del arco del este oyes notas musicales sueltas.\n',
  '4023fabd': 'El hedor de los gases de las alcantarillas y de la podredumbre del río llena este edificio pequeño y sucio.\n',
  '7d8e1a8e': 'El olor que notaste en la zona parece salir de este edificio.  Entre el olor y las manchas por todas partes, parece que has encontrado la vivienda de un curtidor.\n',
  '1d60b9ea': 'El olor que sale de esta sala es casi insoportable.  Por algún motivo, una especie de hedor y una humedad asombrosamente alta se combinan en algo casi inaguantable.  Parece que aquí murió algo hace mucho tiempo y no ha dejado de pudrirse desde entonces.\n',
});
Object.assign(DELV_TRANSLATION_ES.text['*'], {
  'afbbe231': 'Estás en una vivienda pequeña, decorada con gusto, pero la capa de polvo indica que nadie ha estado aquí últimamente.\n',
  '64735947': '"Aquí es donde vive mi hermana Larisa, cuando no está explorando.  Debe de seguir en las ruinas de la Ciénaga de Khalkis."*',
  '72be901c': '"Mmm, Larisa ya debería haber vuelto.  Espero que no le haya pasado nada."*',
  '8ce87e67': 'Estás en una casa sencilla y espartana, aunque se nota un toque de olor a vino rancio y a carne asada.\n',
  '066e5b6e': 'Estás en el gran salón común de una taberna.  Tras la barra, al norte, se asa carne en un espetón, y al sur se ve una salita privada.\n',
  'b339f3ab': 'Estás en una pequeña sala del consejo.  Pese a los adornos del cargo, esta sala del Juez apenas se usa, y es evidente que tampoco la han limpiado de polvo últimamente.\n',
  '6940e80f': 'Estas estrechas habitaciones combinan un pequeño negocio con la vivienda.\n',
  '4ab2cbf7': 'Estás en un salón impresionante.  Altas columnas sostienen un techo elevado a lo largo del perímetro.  El centro del salón es un suelo hundido, de rico mármol.  Dentro hay un pequeño estanque que refleja la luz, y por toda esa zona hay estatuas repartidas.\n',
  '1addd0f3': 'Estás en un austero salón con columnas.  Además de los arcos principales al norte y al sur, unos arcos más pequeños llevan al este y al oeste.\n',
  '94fbfc12': 'Estás ante la verdadera sede del poder de Kosha.  En la mitad norte de la sala, sobre una tarima, hay una mesa enorme, y detrás, una sola silla enorme.\n',
  '96bc094a': 'Estás en una pequeña sala lateral, a todas luces pensada como una especie de salita o recibidor.\n',
  'a3de7e79': 'Esta sala son las estrechas habitaciones comunes, probablemente del servicio de la casa.\n',
  '5aba2222': 'Estás en un comedor informal para todos.\n',
  'b46fe453': 'Estás en un pequeño almacén, probablemente una especie de armería.\n',
  'c051be85': 'A través del aire lleno de hollín ves que es una pequeña herrería, muy bien cuidada.\n',
  '3e705d23': 'Varios telares grandes dominan esta sala, lo que indica un lugar donde se hace tela.\n',
  '29f16612': 'Esta trastienda tiene una rueca, sin duda el origen del hilo que usan los telares de fuera.\n',
  '8dff2b5e': 'Un gran almacén medio lleno, sobre todo de víveres y cajas.\n',
  '28e33b78': 'Está claro que en esta sala se tratan muchos negocios, con varias reuniones importantes en torno a una mesa sencilla con sillas lujosas.\n',
  '67b22204': 'Un dormitorio sencillo, a todas luces del señor de la Casa, ya que da a la sala de reuniones exterior.\n',
  'df94e84c': 'Decir espartana es quedarse corto con esta sala, que solo tiene un escritorio sencillo.  Es evidente que no es un lugar para reuniones.\n',
  '7ef33d80': 'Tan espartana como la sala de fuera, esta es parecida, pero no tanto, pues tiene un espejo sencillo en la pared.\n',
  'b6cea952': 'Este pasadizo secreto rezuma humedad, y el olor del mar se nota intenso en el aire.\n',
  '116c33e7': 'Si esta sala sirvió para algo en el pasado, está claro que ahora no, pues no tiene nada salvo una capa de polvo en el suelo y unos cuantos charcos de agua estancada, aunque también se nota el olor del mar.\n',
  '4f379f43': 'Esta sala tiene tres ventanas que dan a varias direcciones desde la fortaleza, lo que la hace un buen puesto de guardia.  Un arco al norte lleva a lo que a todas luces es el cuartel de la guardia.\n',
  'ec967842': 'Estás a la entrada de un templo abandonado y en ruinas.  Aparte de los animales, no hay rastro de vida.\n',
  'a804e306': 'Esta sala tiene una gran estatua en el centro.  Parece un hombre, con una expresión de dicha en el rostro.\n',
  'a4c23a24': 'Esta sala también tiene una gran estatua, aunque le falta algo de la dicha de la primera; en cambio, parece tener una expresión de sobrecogimiento.\n',
  '548db8b8': 'Parece que esta sala fue el alojamiento de algunos fieles.  Unas alfombras sencillas y los restos de sus ocupantes es todo lo que se ve.\n',
  'f7ff4f3f': 'No está claro si esto era una especie de biblioteca o un aula, pero aquí hay tanto pupitres como una estantería con libros.\n',
  '89c10494': 'Aquí hay filas de mesas y sillas.  Las mesas están manchadas por los años y el uso.\n',
  'd362b1ad': 'Está claro que esta es la cocina del templo, con una puerta al comedor de al lado.\n',
  'f16419c7': 'Esta sala es una especie de habitación privada, aunque no queda mucho después de tantos años.\n',
  '2bd840e2': 'Has entrado en una especie de capilla o lugar de culto, para el poder o el ser que adoraran los habitantes del templo.  Hay una especie de presencia que casi se puede saborear, pero el sabor es amargo, y apesta a algas podridas.\n',
  '3afa7f71': 'Estás en una especie de santuario interior del templo, con suelo de tierra natural.  Una fuente borbotea en la esquina noroeste, y el aire está lleno de un hedor a agua salada y a podredumbre.\n',
  '551c491a': 'Estás en una especie de gran caverna.  Está llena del hedor del mar, pero con el techo tan bajo no ves muy lejos, aunque en algún lugar hacia el oeste oyes el chapoteo de las olas.\n',
  'f6bab78a': 'Estás en una especie de cueva natural, que los mineros abrieron hace poco.\n',
  '592227f4': '¡Parte de la cueva se derrumba!\n',
});
Object.assign(DELV_TRANSLATION_ES.text, {
  // Omen, at the end of his Test
  '1CC3': {
    '6519565e': 'La visión de Omen vuelve...*"Bien hecho, humano.  No ha sido tan difícil, ¿verdad?"*',
    '6a8d2c1b': '"Y veo que has encontrado tu recompensa: bien hecho.  Que te sirva bien."*"Aun así, quizá ni esto baste, así que tengo otro regalo para ti."*',
    '011237db': '"Lástima que no encontraras tu recompensa: tu falta de atención no augura nada bueno..."*"Aun así, no carezco de compasión: te prometí ayuda, y ayuda tendrás."*',
    '0030b97d': '"Te concederé otro favor: este artefacto mágico de cartografía, que te deja ver por dónde has pasado"*',
    'c00b6caa': '"Recuerda nuestro consejo, y quizá volvamos a vernos: estaré vigilándote a ti y a tus actos."*',
    '089e9a44': '"Si alguna vez vuelves a mi pequeña \'Prueba\', te contaré un secreto."*"Cuando tiras de la palanca de la primera sala, se abre una pared ilusoria bajo la antorcha, así que puedes atravesar la pared por ahí."*"Desde esa sala secreta, basta con bajar por la escalera a mis aposentos de aquí."*',
    '79139b32': '"Mientras tanto, te devolveré a tus aposentos: no hables con nadie de este encuentro nuestro."*',
  },
});

